import React from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Input, Label, FormGroup } from 'reactstrap';
import moment from 'moment';
import Validator from 'validator';
import DatePicker from 'react-datepicker';
import Select from 'react-select';
import CustomButton from '../../../../../components/CustomButton';
import { employeeStatic } from '../../../../../config/constants';
import CommonTooltip from 'views/admin/Common/CommonTooltip';
import { formResMessage, infoIconSm } from 'utils/commonFunc';
import CustomSelect from 'components/CustomSelect';

const stateObj = {
  data: {
    subjectId: '',
    description: '',
    title: '',
    priority: 'MEDIUM',
    submissionDate: '',
  },
  errors: {},
  loading: false,
};

const priorities = [
  { label: 'Low', value: 'LOW' },
  { label: 'Medium', value: 'MEDIUM' },
  { label: 'High', value: 'HIGH' },
];

// react-select has no invalid state of its own: a red border like the other required fields when it has an error.
const selectErrorStyles = hasError => ({
  control: base => ({
    ...base,
    borderColor: hasError ? '#dc3545' : base.borderColor,
    '&:hover': { borderColor: hasError ? '#dc3545' : base['&:hover']?.borderColor },
  }),
});

class AssignmentFormModal extends React.Component {
  state = stateObj;

  getSubjects = () => {
    const { empSubjectList } = this.props;
    if (empSubjectList?.length) {
      return empSubjectList
        ?.filter(sto => {
          return sto?.subject?.studyLevel !== 'NONE' && sto?.subject?.subjectCode !== 'BREAK';
        })
        ?.map(item => {
          return {
            label: `${item?.subject?.name} (${item?.subject?.subjectCode})`,
            value: item?.subject?.subjectId,
          };
        });
    }
    return [];
  };

  handleSelectChange = (name, selectItem) => {
    this.setState({
      data: {
        ...this.state.data,
        [name]: selectItem.value,
      },
    });
  };

  handleChange = e =>
    this.setState({
      data: { ...this.state.data, [e.currentTarget.name]: e.currentTarget.value },
    });

  handleDateChange = (name, date) => {
    this.setState({
      data: { ...this.state.data, [name]: moment(date).format('YYYY-MM-DD HH:mm') },
    });
  };

  round = (date, duration, method) => {
    duration = duration || moment.duration(15, 'minutes');
    method = method || 'floor';
    return moment(Math[method](+date / +duration) * +duration);
  };

  handleSubmit = e => {
    e.preventDefault();
    const { data } = this.state;
    const errors = this.validate(data);
    this.setState({ errors });
    if (Object.keys(errors).length === 0) {
      this.setState({ loading: true });
      this.props
        .saveAssignment(data)
        .then(() => {
          this.stateReset();
          this.props.assignmentUpdateSuccess('add');
        })
        .catch(err => this.setError(err));
    }
  };

  setError = err => {
    this.setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  stateReset = () => {
    this.setState(stateObj);
  };

  formModalClose = () => {
    this.stateReset();
    this.props.formModalCloseProp();
  };

  validate = data => {
    const errors = {};

    if (Validator.isEmpty(data.subjectId.toString().trim())) {
      errors.subject = 'Subject cannot be empty';
    }

    if (Validator.isEmpty(data.priority)) {
      errors.priority = 'Priority cannot be empty';
    }

    // the backend needs at least 3 characters
    if (Validator.isEmpty(data.description)) {
      errors.description = 'Description cannot be empty';
    } else if (data.description.trim().length < 3) {
      errors.description = 'Description must be at least 3 characters';
    }

    if (Validator.isEmpty(data.title)) {
      errors.title = 'Assignment name cannot be empty';
    } else if (data.title.trim().length < 3) {
      errors.title = 'Assignment name must be at least 3 characters';
    }

    if (!data.submissionDate) {
      errors.submissionDate = 'Submission date cannot be empty';
    }

    return errors;
  };

  render() {
    const { isModalOpen } = this.props;
    const { data, errors, loading } = this.state;
    const thisData = (
      <Modal size="lg" isOpen={isModalOpen}>
        <form onSubmit={this.handleSubmit}>
          <ModalHeader>ADD ASSIGNMENT</ModalHeader>
          <ModalBody>
            {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
            <div className="content">
              <div className="container-fluid">
                <Row>
                  <Col sm={12}>
                    <FormGroup>
                      <Label htmlFor="">
                        Subject<sup> *</sup>{' '}
                        {
                          <CommonTooltip
                            content={`These all are the subjects that has been assigned to ${employeeStatic.toLowerCase()}`}>
                            {infoIconSm()}
                          </CommonTooltip>
                        }
                      </Label>
                      <CustomSelect
                        noLabel={true}
                        name="subjectId"
                        onChange={(name, value) => this.handleSelectChange(name, { value })}
                        options={this.getSubjects()}
                        value={data.subjectId}
                        applyLabelStyle={true}
                      />
                      {errors.subject && <span className="err-msg">{errors.subject}</span>}
                    </FormGroup>
                  </Col>
                </Row>
                <Row>
                  <Col sm={12}>
                    <FormGroup>
                      <Label htmlFor="">
                        Name<sup> *</sup>
                      </Label>
                      <Input
                        type="text"
                        name="title"
                        onChange={this.handleChange}
                        value={data.title}
                        placeholder="Enter here..."
                        maxLength="200"
                      />
                      {errors.title && <span className="err-msg">{errors.title}</span>}
                    </FormGroup>
                  </Col>
                  <Col sm={6}>
                    <FormGroup>
                      <Label htmlFor="">
                        Priority<sup> *</sup>
                      </Label>
                      <Select
                        name="priority"
                        onChange={value => this.handleSelectChange('priority', value)}
                        options={priorities}
                        value={priorities?.find(dataVal => dataVal.value === data.priority)}
                        styles={selectErrorStyles(!!errors.priority)}
                      />
                      {errors.priority && <span className="err-msg">{errors.priority}</span>}
                    </FormGroup>
                  </Col>
                  <Col md={6}>
                    <FormGroup className="customDatePickerWidth">
                      <Label htmlFor="">
                        Submission date<sup> *</sup>
                      </Label>
                      <br />
                      <DatePicker
                        className="form-control"
                        selected={data.submissionDate ? new Date(data.submissionDate) : null}
                        onChange={date => this.handleDateChange('submissionDate', date)}
                        showYearDropdown
                        showMonthDropdown
                        dateFormat="dd/MM/yyyy"
                        dropdownMode="select"
                      />
                      {errors.submissionDate && <span className="err-msg">{errors.submissionDate}</span>}
                    </FormGroup>
                  </Col>
                  <Col sm={12}>
                    <FormGroup>
                      <Label htmlFor="">
                        Description<sup> *</sup>
                      </Label>
                      <Input
                        type="textarea"
                        rows={4}
                        name="description"
                        onChange={this.handleChange}
                        value={data.description}
                        placeholder="Enter here..."
                        maxLength="400"
                      />
                      <small className="text-muted">{data.description.length}/400</small>
                      {errors.description && <span className="err-msg">{errors.description}</span>}
                    </FormGroup>
                  </Col>
                </Row>
              </div>
            </div>
          </ModalBody>
          <ModalFooter>
            <CustomButton type="submit" disabled={loading} loading={loading} />
            <CustomButton
              className="ml-2"
              type="button"
              color="default"
              disabled={loading}
              onClick={this.formModalClose}
              name="Cancel"
            />
          </ModalFooter>
        </form>
      </Modal>
    );
    return <div>{thisData}</div>;
  }
}

export default AssignmentFormModal;
