import React, { useEffect, useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Table, Input } from 'reactstrap';
import { formStudentName } from 'config/constants';
import CustomButton from 'components/CustomButton';
import { LoadingCard } from 'views/admin/Common/Loader';
import { fetchSubjectProgressReportApi } from 'actions/admin/marks';

const BulkMarkEntryModal = ({
  isOpen,
  formModalClose,
  courseStudents,
  subjectName,
  subjectId,
  examTypeDetailId,
  totalMark,
  batchId,
  token,
  saveMark,
  showWarning,
  onSaved,
}) => {
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  // Keyed by studentId: { progReportId, studentMark } - progReportId undefined means no mark
  // saved for that student yet, so submit uses POST instead of PUT.
  const [marksByStudent, setMarksByStudent] = useState({});
  // The marks as loaded: Save all writes only the rows that differ from these.
  const [loadedMarks, setLoadedMarks] = useState({});

  useEffect(() => {
    if (!isOpen) return;
    setLoading(true);
    fetchSubjectProgressReportApi({ batchId, examTypeDetailId, subjectId, token })
      .then(res => {
        const existing = {};
        res.data?.forEach(item => {
          if (item?.student?.studentId) {
            existing[item.student.studentId] = {
              progReportId: item.progReportId,
              studentMark: item.studentMark,
            };
          }
        });
        setMarksByStudent(existing);
        setLoadedMarks(existing);
      })
      .catch(() => showWarning('Could not load existing marks for this subject', 'error'))
      .finally(() => setLoading(false));
  }, [isOpen, batchId, examTypeDetailId, subjectId]);

  const handleMarkChange = (studentId, value) => {
    if (value !== '' && Number(value) > Number(totalMark)) {
      showWarning(`Mark cannot be more than ${totalMark}`, 'warning');
      return;
    }
    setMarksByStudent(prev => ({
      ...prev,
      [studentId]: { ...prev[studentId], studentMark: value },
    }));
  };

  const isFilled = val => val.studentMark !== '' && val.studentMark !== undefined && val.studentMark !== null;
  // Only a mark that is new or changed is written: a row left as it was loaded is not sent again.
  const entries = Object.entries(marksByStudent).filter(
    ([studentId, val]) => isFilled(val) && `${loadedMarks[studentId]?.studentMark ?? ''}` !== `${val.studentMark}`
  );

  const handleSaveAll = async () => {
    // A row with a progReportId already exists server-side, so it goes out via PUT (an
    // update) rather than POST - POSTing an already-entered mark again would collide with
    // the one-mark-per-student-per-subject-exam constraint.
    if (!entries.length) {
      showWarning('Nothing to save. Enter or change a mark first.', 'warning');
      return;
    }
    setSaving(true);
    const results = await Promise.allSettled(
      entries.map(([studentId, val]) => {
        const postData = {
          examTypeDetails: { examTypeDetailId },
          subject: { subjectId },
          studentMark: val.studentMark,
          student: { studentId: Number(studentId) },
          batchId,
        };
        return saveMark({ postData, ...(val.progReportId && { progReportId: val.progReportId }), token });
      })
    );
    setSaving(false);
    const failCount = results.filter(r => r.status === 'rejected').length;
    if (failCount) {
      showWarning(`Saved ${entries.length - failCount} of ${entries.length} marks - ${failCount} failed`, 'warning');
    } else {
      showWarning(`Saved marks for ${entries.length} student${entries.length > 1 ? 's' : ''}`, 'success');
    }
    onSaved?.();
    if (!failCount) formModalClose();
  };

  const closeBtn = (
    <i
      className="fas fa-times"
      style={{ fontSize: 20, color: '#000000', cursor: 'pointer' }}
      onClick={formModalClose}
    />
  );

  return (
    <Modal size="lg" isOpen={isOpen}>
      <ModalHeader close={closeBtn}>
        ENTER MARKS - {subjectName} (Total mark: {totalMark || '-'})
      </ModalHeader>
      <ModalBody style={{ maxHeight: '60vh', overflowY: 'auto' }}>
        {loading ? (
          <LoadingCard />
        ) : (
          <Table size="sm" responsive>
            <thead className="text-primary">
              <tr>
                <th>Reg. No</th>
                <th>Student</th>
                <th className="text-center" style={{ width: 140 }}>
                  Mark
                </th>
              </tr>
            </thead>
            <tbody>
              {courseStudents?.length ? (
                courseStudents.map(student => (
                  <tr key={student.studentId}>
                    <td>{student.registerNumber}</td>
                    <td>{formStudentName(student)}</td>
                    <td className="text-center">
                      <Input
                        type="number"
                        size="sm"
                        min={0}
                        max={totalMark || undefined}
                        value={
                          marksByStudent[student.studentId]?.studentMark !== undefined
                            ? marksByStudent[student.studentId]?.studentMark
                            : ''
                        }
                        onChange={e => handleMarkChange(student.studentId, e.target.value)}
                      />
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="3" className="text-center">
                    No students found for this class
                  </td>
                </tr>
              )}
            </tbody>
          </Table>
        )}
      </ModalBody>
      <ModalFooter>
        <CustomButton
          type="button"
          disabled={saving || loading || !entries.length}
          loading={saving}
          onClick={handleSaveAll}
          name={entries.length ? `Save all (${entries.length})` : 'Save all'}
        />
        <CustomButton
          className="ml-2"
          type="button"
          color="default"
          disabled={saving}
          onClick={formModalClose}
          name="Cancel"
        />
      </ModalFooter>
    </Modal>
  );
};

export default BulkMarkEntryModal;
