import React from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Input, Label, FormGroup } from 'reactstrap';
import Validator from 'validator';
import Select from 'react-select';
import CustomButton from '../../../../../components/CustomButton';
import { courseStatic, employeeStatic } from '../../../../../config/constants';
import CommonTooltip from 'views/admin/Common/CommonTooltip';
import { formResMessage, infoIconSm } from 'utils/commonFunc';

const stateObj = {
  subjectCode: '',
  data: {
    subjectId: '',
    description: '',
    name: '',
    // The period this task belongs to, e.g. "Period 1" - a plain descriptive label (matches
    // what the backend's `timePeriod` column actually stores: free text, not a real clock
    // time, and it's not tied to any specific timetable slot). Homework is a subject-for-the
    // -day thing, not a per-period thing - if a subject repeats across periods today, this
    // is still just one task, so there's nothing here for a teacher to pick or type.
    timePeriod: '',
  },
  errors: {},
  loading: false,
};

// react-select has no invalid state of its own: a red border like the other required fields when it has an error.
const selectErrorStyles = hasError => ({
  control: base => ({
    ...base,
    borderColor: hasError ? '#dc3545' : base.borderColor,
    '&:hover': { borderColor: hasError ? '#dc3545' : base['&:hover']?.borderColor },
  }),
});

class HomeWorkFormModal extends React.Component {
  state = stateObj;

  getCourseSubjectIdForSubjectCode = passSubCode => {
    if (this.props.courseSubjects?.length) {
      // The picked subject may belong to a different class than the one currently
      // selected in "Teacher class" (a teacher can be assigned subjects across several
      // classes) - courseSubjects is scoped to just the selected class, so a match here
      // isn't guaranteed. No match falls through to the "not assigned to this class"
      // error below instead of crashing.
      const fItem = this.props.courseSubjects?.find(item => {
        return item.subjectCode === passSubCode;
      });
      return fItem?.subjectId || null;
    }
    return null;
  };

  componentDidUpdate(prevProps) {
    const { isModalOpen, courseDayTimeSlots, courseSubjects, fetchCourseSubjects, fetchCourseDayTimeSlot } = this.props;
    if (prevProps.isModalOpen !== isModalOpen) {
      if (!courseSubjects?.length) fetchCourseSubjects?.(true);
      if (!courseDayTimeSlots?.length) fetchCourseDayTimeSlot?.();
    }
  }

  handleSelectSubjectChange = selectItem => {
    const subjectCode = selectItem.value;
    this.setState({ subjectCode }, () => {
      const subjectId = this.getCourseSubjectIdForSubjectCode(subjectCode);
      if (subjectId) {
        this.setState({
          data: {
            ...this.state.data,
            subjectId,
            // The subject's own slot on today's timetable, if it has one (e.g. "Period 1") -
            // blank for a subject with no scheduled slot today, which is fine since nothing
            // downstream depends on this being set.
            timePeriod: selectItem?.timePeriod || '',
          },
          errors: {
            ...this.state.errors,
            global: '',
          },
        });
      } else {
        this.setState({
          ...this.state,
          errors: {
            ...this.state.errors,
            global: `
            Selected subject (from time table) is not assigned to above selected ${courseStatic.toLowerCase()}.
            Please check subject module
            `,
          },
        });
      }
    });
  };

  handleChange = e => {
    this.setState({
      data: { ...this.state.data, [e.currentTarget.name]: e.currentTarget.value },
    });
  };

  handleSubmit = e => {
    e.preventDefault();
    const { data } = this.state;
    const errors = this.validate(data);
    this.setState({ errors });
    if (Object.keys(errors).length === 0) {
      this.setState({ loading: true });
      if (data.subjectId) {
        this.props
          .saveHomeWork(data)
          .then(() => {
            this.stateReset();
            this.props.homeWorkUpdateSuccess('add');
          })
          .catch(err => this.setError(err));
      } else {
        this.setState({
          ...this.state,
          errors: {
            ...this.state.errors,
            global: `
              Selected subject (from time table) is not assigned to above selected ${courseStatic.toLowerCase()}.
              Please check subject module for reference
              `,
          },
        });
      }
    }
  };

  setError = err => {
    this.setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  stateReset = () => {
    this.setState(stateObj);
  };

  formModalClose = () => {
    this.stateReset();
    this.props.formModalCloseProp();
  };

  validate = data => {
    const errors = {};

    if (Validator.isEmpty(this.state.subjectCode.toString().trim())) {
      errors.subjectCode = 'Subject cannot be empty';
    }

    // the backend needs at least 3 characters
    if (Validator.isEmpty(data.description)) {
      errors.description = 'Description cannot be empty';
    } else if (data.description.trim().length < 3) {
      errors.description = 'Description must be at least 3 characters';
    }

    // Homework validation //
    if (Validator.isEmpty(data.name)) {
      errors.name = 'Homework name cannot be empty';
    } else if (data.name.trim().length < 3) {
      errors.name = 'Homework name must be at least 3 characters';
    }

    return errors;
  };

  render() {
    const { isModalOpen, subTimes } = this.props;
    const { data, errors, loading, subjectCode } = this.state;
    const thisData = (
      <Modal size="lg" isOpen={isModalOpen}>
        <form onSubmit={this.handleSubmit}>
          <ModalHeader>ADD HOMEWORK</ModalHeader>
          <ModalBody>
            {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
            <div className="content">
              <div className="container-fluid">
                <Row>
                  <Col sm={12}>
                    <FormGroup>
                      <Label htmlFor="">
                        Subjects<sup> *</sup>{' '}
                        {
                          <CommonTooltip
                            content={`These all are ${employeeStatic.toLowerCase()} subjects. Based on the subjects that has been assigned to ${employeeStatic.toLowerCase()} for today's timesheet`}>
                            {infoIconSm()}
                          </CommonTooltip>
                        }
                      </Label>
                      <Select
                        name="subjectId"
                        onChange={value => this.handleSelectSubjectChange(value)}
                        options={subTimes}
                        value={subTimes?.find(dataVal => dataVal.value === subjectCode)}
                        styles={selectErrorStyles(!!errors.subjectCode)}
                      />
                      {errors.subjectCode && <span className="err-msg">{errors.subjectCode}</span>}
                    </FormGroup>
                  </Col>
                </Row>
                <Row>
                  <Col sm={12}>
                    <FormGroup>
                      <Label htmlFor="">
                        Homework name<sup> *</sup>
                      </Label>
                      <Input
                        type="text"
                        name="name"
                        onChange={this.handleChange}
                        value={data.name}
                        placeholder="Enter here..."
                        maxLength="100"
                      />
                      {errors.name && <span className="err-msg">{errors.name}</span>}
                    </FormGroup>
                  </Col>
                </Row>
                <Row>
                  <Col sm={12}>
                    <FormGroup>
                      <Label htmlFor="">
                        Description<sup> *</sup>
                      </Label>
                      <Input
                        type="textarea"
                        rows={4}
                        name="description"
                        onChange={this.handleChange}
                        value={data.description}
                        placeholder="Enter here..."
                        maxLength="400"
                      />
                      <small className="text-muted">{data.description.length}/400</small>
                      {errors.description && <span className="err-msg">{errors.description}</span>}
                    </FormGroup>
                  </Col>
                </Row>
              </div>
            </div>
          </ModalBody>
          <ModalFooter>
            <CustomButton type="submit" disabled={loading} loading={loading} name="Save" />
            <CustomButton
              className="ml-2"
              type="button"
              color="default"
              disabled={loading}
              onClick={this.formModalClose}
              name="Cancel"
            />
          </ModalFooter>
        </form>
      </Modal>
    );
    return <div>{thisData}</div>;
  }
}

export default HomeWorkFormModal;
