import React from 'react';
import { connect } from 'react-redux';
import { Row, Col } from 'reactstrap';
import moment from 'moment';

import {
  saveAssignmentService,
  viewStudentAssignmentStatusService,
  deleteAssignmentService,
} from 'actions/admin/students';
import AssignmentFormModal from './components/AssignmentFormModal.jsx';
import StudentsStatusViewModal from './components/StudentsStatusViewModal.jsx';
import constants, { courseStatic } from '../../../../config/constants.js';
import { store } from '../../../../index.js';
import { showToast } from '../../../../actions/admin/auth.js';
import CustomButton from '../../../../components/CustomButton.jsx';
import TaskList from '../components/TaskList';
import LoadMore from '../components/LoadMore';
import ListDropDown from 'views/admin/Common/ListDropDown.jsx';
import { LoadingCard } from 'views/admin/Common/Loader.jsx';
import { formResMessage } from 'utils/commonFunc.js';

class AssignmentPage extends React.Component {
  constructor() {
    super();
    this.state = {
      selectedDate: new Date(),
      showAlert: false,
      message: '',
      alertType: '',
      isModalOpen: false,
      confirmModalOpen: false,
      isStatusModalOpen: false,
    };
  }

  componentDidMount() {
    this.fetchAssignmentsData(this.state.selectedDate, false);
  }

  showWarning = (message, type) => {
    this.setState({ confirmModalOpen: false });
    store.dispatch(showToast(message, type));
  };

  fetchAssignmentsData = (date, canCallEmpSubject, page = this.props.assignmentPageParams?.page, refetchAgain) => {
    this.props.fetchAssignmentsData(date, canCallEmpSubject, page, refetchAgain);
  };

  // Assignment section ///
  formModalOpen = () => {
    // if(moment(this.state.selectedDate).format('YYYY-MM-DD') <= moment(new Date()).format('YYYY-MM-DD')){
    //   alert('Cant')
    // } else {
    this.setState({ isModalOpen: true });
    // }
  };

  formModalClose = () => {
    this.setState({
      isModalOpen: false,
      confirmModalOpen: false,
      isStatusModalOpen: false,
    });
  };

  saveAssignment = data => {
    const assignmentData = {
      createdUser: {
        id: this.props.loggedUserRole === constants.roles.teacher ? this.props.loggedUserId : this.props.propEmployeeId,
      },
      employee: { employeeId: this.props.propEmployeeId },
      subject: { subjectId: data.subjectId },
      title: data.title,
      priority: data.priority,
      description: data.description,
      submissionDate: moment(moment(data.submissionDate).format('YYYY-MM-DD HH:mm:ss')).valueOf(),
    };
    return this.props.saveAssignment({ assignmentData, token: this.props.loggedUserToken });
  };

  viewStudentStatus = assignmentId => {
    return this.props
      .viewStudentAssignmentStatus({
        assignmentId,
        token: this.props.loggedUserToken,
      })
      .then(() =>
        this.setState({
          isModalOpen: false,
          confirmModalOpen: false,
          isStatusModalOpen: true,
        })
      );
  };

  assignmentUpdateSuccess = () => {
    this.setState({ isModalOpen: false });
    this.showWarning('Assignment added successfully', 'success');
    this.fetchAssignmentsData(this.state.selectedDate, false, null, true);
  };

  deleteAssignment = assignmentItem => {
    if (
      moment(assignmentItem.creationDateTime).format('YYYY-MM-DD') === moment(new Date()).format('YYYY-MM-DD') &&
      moment(assignmentItem.creationDateTime).format('YYYY-MM-DD HH:mm') <=
        moment(new Date()).format('YYYY-MM-DD 18:00')
    ) {
      this.deleteConfirmAssignment(assignmentItem.assignmentId);
    } else {
      this.showWarning('Time has expired to remove Assignment', 'error');
    }
  };

  deleteConfirmAssignment = assignmentId => {
    return this.props
      .deleteAssignment({ assignmentId, token: this.props.loggedUserToken })
      .then(() => {
        this.fetchAssignmentsData(this.state.selectedDate, false, null, true);
      })
      .catch(err => {
        this.showWarning(formResMessage(err), 'error');
      });
  };

  fetchPageData = page => {
    this.fetchAssignmentsData(this.state.selectedDate, false, page, true);
  };

  render() {
    const { isModalOpen, isStatusModalOpen } = this.state;
    const {
      propsCourseId,
      assignmentsData,
      employee,
      courseSubjects,
      studentsAssignmentStatusList,
      assignmentFetching,
      empSubjectList,
    } = this.props;

    // the teacher's latest assignments in this class (newest first and grouped by TaskList)
    const items = (assignmentsData?.content || [])
      .filter(fData => fData.subject.course.courseId === propsCourseId)
      .map(item => ({
        id: item.assignmentId,
        title: item.title,
        subject: item.subject?.name,
        description: item.description,
        date: item.creationDateTime,
        dueDate: item.submissionDate,
        priority: item.priority,
        by: item.createdUser?.name,
        actions: (
          <ListDropDown
            actionList={['students status', 'delete']}
            assignmentItem={item}
            viewStudentStatus={() => this.viewStudentStatus(item.assignmentId)}
            deleteItem={() => this.deleteAssignment(item)}
          />
        ),
      }));

    const tableData = (
      <>
        <TaskList
          groupBy="day"
          emptyTitle="Nothing to show here yet"
          emptySubtitle={
            propsCourseId
              ? 'Assignments you give show here, newest first.'
              : `Select a ${courseStatic.toLowerCase()} first.`
          }
          items={items}
        />
        <LoadMore
          visible={items.length >= this.props.limit}
          loading={assignmentFetching}
          onClick={this.props.onLoadMore}
        />
      </>
    );

    return (
      <div className="mt-2">
        <Row className="mb-3">
          <Col>
            <CustomButton
              style={{ float: 'right' }}
              onClick={this.formModalOpen}
              disabled={!propsCourseId}
              name="Add Assignment"
            />
            {!propsCourseId && (
              <span style={{ color: 'orange' }}>
                <sup>*</sup>Select {courseStatic.toLowerCase()} to enable
              </span>
            )}
          </Col>
        </Row>
        {assignmentFetching && !items.length ? <LoadingCard /> : tableData}
        <AssignmentFormModal
          isModalOpen={isModalOpen}
          propsCourseId={propsCourseId}
          formModalCloseProp={this.formModalClose}
          courseSubjects={courseSubjects}
          saveAssignment={this.saveAssignment}
          employee={employee}
          assignmentUpdateSuccess={this.assignmentUpdateSuccess}
          empSubjectList={empSubjectList}
        />
        <StudentsStatusViewModal
          isStatusModalOpen={isStatusModalOpen}
          studentsAssignmentStatusList={studentsAssignmentStatusList}
          // assignment={assignmentList.filter(fData => fData.subject.course.courseId === propsCourseId)[0]}
          formModalClose={this.formModalClose}
        />
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    loggedUserRole: state.auth.loggedUserRole,
    assignmentsData: state.students.assignmentsData,
    studentsAssignmentStatusList: state.students.studentsAssignmentStatusList,
    empSubjectList: state?.subjects?.empSubjectList,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    saveAssignment: data => dispatch(saveAssignmentService(data)),
    viewStudentAssignmentStatus: data => dispatch(viewStudentAssignmentStatusService(data)),
    deleteAssignment: data => dispatch(deleteAssignmentService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(AssignmentPage);
