import React, { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Input, Label, FormGroup } from 'reactstrap';
import moment from 'moment';
import colors from 'config/colors';
import CustomButton from '../../../../../components/CustomButton';
import DatePicker from 'views/admin/Common/Datepicker';
import { formResMessage } from 'utils/commonFunc';
import CustomSelect from 'components/CustomSelect';

const SubjectExamFormModal = ({
  isSubjectExamModalOpen,
  saveSubjectExam,
  updateExam,
  examUpdateSuccess,
  formModalCloseProp,
  exam,
  examType,
  courseSubjects,
  subjectExamData,
  mainExamStartDate,
  mainExamEndDate,
  onEditMainExam,
  examDuration = '3',
}) => {
  const stateObj = {
    data: {
      examDate: '',
      examDuration: 3,
      examHallCode: '',
      examHallName: '',
      examStartTime: '',
      examSubjectDetailId: 0,
      subject: {
        subjectId: 0,
      },
    },
    errors: {},
    loading: false,
  };

  const [stateVal, setState] = useState(stateObj);

  useEffect(() => {
    if (exam && Object.keys(exam).length) {
      setState(prevState => ({
        ...prevState,
        data: {
          school: { schoolId: exam.school.schoolId },
          examDetailId: exam.examDetailId,
          examTitle: exam.examTitle,
          examType: exam.examType,
          examDate: exam.examDate,
          examEndDate: exam.examEndDate,
          batch: { batchId: exam.batch.batchId },
        },
      }));
    }
  }, [exam]);

  const handleChange = (name, value) => {
    setState(prevState => ({
      ...prevState,
      data: {
        ...prevState.data,
        [name]: value,
      },
    }));
  };

  const handleSelectChange = (name, selectItem) => {
    setState(prevState => ({
      ...prevState,
      data: {
        ...prevState.data,
        subject: { subjectId: selectItem },
      },
    }));
  };

  const handleDateChange = (name, date) => {
    setState(prevState => ({
      ...prevState,
      data: {
        ...prevState.data,
        [name]: name === 'examDate' ? moment(date).format('YYYY-MM-DD HH:mm') : date,
        ...(name === 'examDate' && {
          examStartTime: null,
        }),
      },
    }));
  };

  const handleSubmit = e => {
    e.preventDefault();
    let dataVal = stateVal.data;
    const errorsObj = validate(dataVal);
    setState(prevState => ({ ...prevState, errors: errorsObj }));
    if (!Object.keys(errorsObj).length) {
      setState(prevState => ({ ...prevState, loading: true }));
      if (dataVal.examDetailId) {
        return updateExam(dataVal)
          .then(() => {
            stateValReset();
            examUpdateSuccess('update');
          })
          .catch(err => setError(err));
      }
      // const dur = dataVal.examDuration.toString();
      dataVal = {
        ...dataVal,
        examDate: moment(dataVal.examDate).format('YYYY-MM-DD'),
        examStartTime: moment(dataVal.examDate).format('HH:mm'),
      };
      const isSamePeriodExist = subjectExamData?.[examType]?.some(el => {
        return (
          el.examDate === moment(dataVal.examDate).format('YYYY-MM-DD') &&
          moment(el.examStartTime, ['h:mm A']).format('HH:mm') === dataVal?.examStartTime
        );
      });
      if (!isSamePeriodExist) {
        return saveSubjectExam(dataVal)
          .then(() => {
            stateValReset();
            examUpdateSuccess('add');
          })
          .catch(err => setError(err));
      } else {
        setError({
          response: {
            data: {
              message: 'Validation failure',
              details: ['Exam already exist in the same date and time period'],
            },
          },
        });
      }
    }
  };

  const setError = err => {
    setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  const stateValReset = () => {
    setState(stateObj);
  };

  const formModalClose = () => {
    stateValReset();
    formModalCloseProp();
  };

  const validate = dataVal => {
    const errorsList = {};
    if (!dataVal.examDate) {
      errorsList.examDate = 'Start Date and Time cannot be empty';
    } else if (
      moment(dataVal.examDate).format('HH:mm') < moment(dataVal.examDate).format('09:00') ||
      moment(dataVal.examDate).format('HH:mm') > moment(dataVal.examDate).format('16:30')
    ) {
      errorsList.examDate = 'Exam Start Time should be between 9 AM to 4.30 PM';
    }

    if (!dataVal.examHallName) {
      errorsList.examHallName = 'Hall name cannot be empty';
    }

    if (!dataVal.examHallCode) {
      errorsList.examHallCode = 'Hall code cannot be empty';
    }

    if (!dataVal.subject?.subjectId) {
      errorsList.subject = 'Subject cannot be empty';
    }

    return errorsList;
  };

  const { data, errors, loading } = stateVal;
  const examEnums = {
    QUART_YEARLY: { label: 'Quarter Yearly', name: 'Quarter Yearly', value: 'QUART_YEARLY' },
    HALF_YEARLY: { label: 'Half Yearly', name: 'Half Yearly', value: 'HALF_YEARLY' },
    ANUAL_EXAM: { label: 'Annual Exam', name: 'Annual Exam', value: 'ANUAL_EXAM' },
    MID_TERM: { label: 'Mid Term Exam', name: 'Mid Term Exam', value: 'MID_TERM' },
    CLASS_TEST: { label: 'Class Test', name: 'Class Test', value: 'CLASS_TEST' },
  };
  const splitTime = examDuration?.toString()?.split(':');
  const hrs = splitTime?.[0] ? Number(splitTime?.[0]) : 3;
  const mins = splitTime?.[1] ? Number(splitTime?.[1]) : 0;
  const hourseToMins = hrs * 60;
  const minToMins = mins;
  const timeIntervalinMinutes = examDuration ? hourseToMins + minToMins : 180;
  // const timeDurInHours = examDuration ? moment.duration(examDuration).asHours() : 2;
  const propSubjectList = courseSubjects.map(item => ({
    value: item?.subjectId,
    label: `${item.name} (${item.subjectCode})`,
  }));
  const selDate = data.examDate ? new Date(data.examDate) : new Date();
  const examMinTime = moment(selDate).hours(9).minute(0).toDate();
  const examMaxTime = moment(selDate).hours(16).minute(30).toDate();
  const thisData = (
    <Modal size="lg" isOpen={isSubjectExamModalOpen}>
      <form onSubmit={handleSubmit}>
        <ModalHeader>{data.examDetailId ? 'UPDATE SUBJECT EXAM' : 'ADD SUBJECT EXAM'}</ModalHeader>
        <ModalBody>
          {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
          <div className="content">
            <div className="container-fluid">
              <Row>
                <Col>
                  <p>
                    <b>Main Exam:</b> {examEnums[examType]?.label}{' '}
                    <span style={{ marginLeft: 30 }}>
                      <b>Duration:</b>{' '}
                      {!!hrs && <span style={{ color: 'green' }}>{`${hrs} hours ${mins} minutes`}</span>}
                      {/* {`${timeDurInHours} Hours`} */}
                    </span>
                  </p>
                </Col>
              </Row>
              <Row>
                <Col sm={6}>
                  <FormGroup>
                    <Label htmlFor="">
                      Exam Subject<sup> *</sup>
                    </Label>
                    <CustomSelect
                      noLabel
                      name="subjectId"
                      value={data?.subject?.subjectId}
                      onChange={(name, value) => handleSelectChange('subjectId', value, 'subject')}
                      options={propSubjectList}
                      applyLabelStyle={true}
                    />
                    {errors.subject && <span className="err-msg">{errors.subject}</span>}
                  </FormGroup>
                </Col>

                <Col md={6}>
                  <FormGroup className="customDatePickerWidth">
                    <Label htmlFor="">
                      Exam Date and Start Time<sup> *</sup>
                    </Label>
                    <br />
                    <DatePicker
                      className="form-control"
                      selectedDate={data.examDate ? new Date(data.examDate) : null}
                      handleDateChange={value => handleDateChange('examDate', value)}
                      placeholderText="Select date..."
                      // Past dates are allowed (exams are also entered after they happened). The only bounds are
                      // the main exam's own start and end dates, when it has them.
                      minDate={mainExamStartDate ? new Date(mainExamStartDate) : undefined}
                      maxDate={mainExamEndDate ? new Date(mainExamEndDate) : undefined}
                      // disabled={new Date(data.examDate) <= new Date()}
                      showTimeSelect={true}
                      showDateWithTime={true}
                      minTime={examMinTime}
                      maxTime={examMaxTime}
                      timeIntervals={timeIntervalinMinutes}
                      dropdownMode="select"
                    />
                    {errors.examDate && <span className="err-msg">{errors.examDate}</span>}
                    {mainExamStartDate && mainExamEndDate && (
                      <div style={{ fontSize: 12, color: colors.grey2, marginTop: 6 }}>
                        This exam runs from <b>{moment(mainExamStartDate).format('DD MMM YYYY')}</b> to{' '}
                        <b>{moment(mainExamEndDate).format('DD MMM YYYY')}</b>, so only dates in that period can be
                        picked.
                        {onEditMainExam && (
                          <>
                            {' '}
                            Need other dates?{' '}
                            <a
                              href="#edit-dates"
                              style={{ color: colors.accent, fontWeight: 'bold' }}
                              onClick={e => {
                                e.preventDefault();
                                onEditMainExam();
                              }}>
                              Change the exam dates
                            </a>
                          </>
                        )}
                      </div>
                    )}
                  </FormGroup>
                </Col>
                <Col md={6}>
                  <FormGroup>
                    <Label htmlFor="">
                      Exam Hall Name<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="examHallName"
                      value={data.examHallName}
                      placeholder="Enter here..."
                      maxLength="50"
                      onChange={e => handleChange('examHallName', e.target.value)}
                    />
                    {errors.examHallName && <span className="err-msg">{errors.examHallName}</span>}
                  </FormGroup>
                </Col>
                <Col md={6}>
                  <FormGroup>
                    <Label htmlFor="">
                      Exam Hall Code<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="examHallCode"
                      value={data.examHallCode}
                      placeholder="Enter here..."
                      maxLength="50"
                      onChange={e => handleChange('examHallCode', e.target.value)}
                    />
                    {errors.examHallCode && <span className="err-msg">{errors.examHallCode}</span>}
                  </FormGroup>
                </Col>
              </Row>
            </div>
          </div>
        </ModalBody>
        <ModalFooter>
          <CustomButton type="submit" disabled={loading} loading={loading} />
          <CustomButton
            className="ml-2"
            type="button"
            color="default"
            disabled={loading}
            onClick={formModalClose}
            name="Cancel"
          />
        </ModalFooter>
      </form>
    </Modal>
  );

  return <div>{thisData}</div>;
};

export default SubjectExamFormModal;
