// Material UI
import { ScrollTabPanel } from '../Reports/index.js';
import { passEmployeeIdToStore } from './components/EmpActivityFilter.jsx';
import { passCourseIdToStore } from './components/EmpActivityFilter.jsx';
import { Card } from '@material-ui/core';
import colors from 'config/colors.js';
