const tabList = [
  { tabIndex: 0, tabTitle: 'Time Table', query: 'calendar', icon: <InsertInvitationIcon /> },
  { tabIndex: 1, tabTitle: 'Attendance', query: 'attendance', icon: <HowToRegIcon /> },
  { tabIndex: 2, tabTitle: 'Home work & Assignments', query: 'home-work', icon: <MenuBookIcon /> },
  // { tabIndex: 3, tabTitle: 'Assignment', query: 'assignment' },
  { tabIndex: 3, tabTitle: 'Online Class', query: 'online-class', icon: <VideocamIcon /> },
  { tabIndex: 4, tabTitle: 'Exams & Marks', query: 'exams-marks', icon: <AssignmentTurnedInIcon /> },
];

// Circulars, the notice board and events/holidays do not depend on a teacher or class, so they live in the sidebar
// (Announcements) instead of here. Old links (bookmarks, dashboard cards) with ?tab=circular / ?tab=activities still land there.
const MOVED_TABS = {
  circular: params => (params.get('sub') === 'noticeboard' ? '/admin/notice-board' : '/admin/circulars'),
  activities: () => '/admin/events-holidays',
};

export const empOrCourseEmptyDiv = (
  <Card>
    <div className="p-3 font-weight-bold text-center" style={{ color: 'red', fontSize: 15 }}>
      Either {employeeStatic} or {courseStatic} is Empty
    </div>
  </Card>
);

export const passActiveTabAndCourseId = (activeTab, courseId) => {
  if (activeTab) store?.dispatch(setStoreActiveTab(activeTab));
  if (activeTab && courseId) store?.dispatch(setVisitedCourseId({ activeTab, courseId }));
};

const LIST_PAGE = 20;

class EmployeeActivityPage extends React.Component {
  constructor() {
    super();
    this.state = {
      schoolId: 0,
      employeeId: 0,
      courseId: 0,
      selectedDate: new Date(),
      activeTab: 0,
      assignmentPageParams: {
        page: 1,
        size: 10,
      },
      // how many of the latest home work / assignments are listed; "Load more" raises it
      homeworkLimit: LIST_PAGE,
      assignmentLimit: LIST_PAGE,
      value: 0,
      subActive: 0,
      disableAll: false,
      isAttendanceLoading: false,
      initiateType: '',
      // Loading
      attendanceFetchLoading: false,
      homeworkFetching: false,
      employeeListFetching: false,
      courseListFetching: false,
      // Fetched into local state, not the shared state.employees.employeeList redux slice -
      // Staff Attendance/Teacher Subjects/Reports etc. all write into that same slot with
      // whatever profession they last fetched, so reading it here after visiting one of those
      // pages could silently show workers in what's meant to be a teachers-only list.
      schoolEmployeeList: [],
    };
  }
  isLoading = (name, value) => {
    this.setState({
      [name]: value,
    });
  };

  // URL query params (?tab=&employeeId=&courseId=) keep the current selection across a
  // reload. Reading/writing goes through these two helpers so every caller stays in sync
  // instead of each one re-parsing location.search or clobbering the other params.
  getQueryParams = () => new URLSearchParams(this.props.location?.search);

  updateUrlParams = updates => {
    const params = this.getQueryParams();
    Object.entries(updates).forEach(([key, value]) => {
      if (value === null || value === undefined || value === 0 || value === '') {
        params.delete(key);
      } else {
        params.set(key, value);
      }
    });
    this.props.history.replace(`${this.props.location.pathname}?${params.toString()}`);
  };

  componentDidMount() {
    const params = this.getQueryParams();
    const tabParam = params.get('tab');
    if (MOVED_TABS[tabParam]) {
      params.delete('tab');
      const rest = params.toString();
      this.props.history.replace(`${MOVED_TABS[tabParam](params)}${rest ? `?${rest}` : ''}`);
      return;
    }
    const cTab = tabParam ? tabList.find(dto => dto.query === tabParam) : null;
    this.toggleActivityTab(null, cTab ? cTab.tabIndex : 0, true);

    const globalSchool = getGlobalSchoolUtils();
    const { batchId } = getGlobalCurrentBatchUtils();
    if (globalSchool) {
      this.setState({ schoolId: globalSchool.schoolId }, () => {
        if (batchId && !this.props.subjectList?.length) {
          this.props.fetchSchoolSubjects({
            schoolId: globalSchool.schoolId,
            batchId,
            token: this.props.loggedUserToken,
          });
        }
        if (this.props.loggedUserRole === constants.roles.SA || this.props.loggedUserRole === constants.roles.admin) {
          this.fetchAllEmployees();
        } else if (this.props.loggedUserRole === constants.roles.teacher) {
          this.fetchEmployeeCourses(this.props.loggedUserId);
          if (!this.props.userProfile?.employeeId) {
            this.props.fetchUser({
              userRole: constants.roles.teacher,
              userId: this.props.loggedUserId,
              token: this.props.loggedUserToken,
            });
          }
        }
      });
    } else {
      this.showWarning('Please select school', 'warning');
    }
  }

  componentDidUpdate(prevProps) {
    if (prevProps.storeEmployeeId !== this.props.storeEmployeeId && this.props.storeEmployeeId) {
      // Only treat this as a genuine "user switched teacher" event when a teacher was
      // already selected before. On the very first auto-selection (prevProps had none yet),
      // fetchAllEmployees already fetched courses for it honoring the URL's courseId -
      // re-fetching here with isSelectChange=true would stomp that back to the first course.
      if (prevProps.storeEmployeeId) {
        this.fetchEmployeeCourses(this.props.storeEmployeeId, true);
      }
      this.setState({ employeeId: this.props.storeEmployeeId });
      this.updateUrlParams({ employeeId: encodeUrlId(this.props.storeEmployeeId) });
    }

    if (prevProps.storeCourseId !== this.props.storeCourseId && this.props.storeCourseId) {
      this.fetchCourseStudents(this.props.storeCourseId, true);
      this.setState({ courseId: this.props.storeCourseId });
      this.updateUrlParams({ courseId: encodeUrlId(this.props.storeCourseId) });
    } else if (prevProps.storeCourseId && !this.props.storeCourseId) {
      // The new teacher has no class: drop the old class from the url so a reload doesn't bring it back.
      this.updateUrlParams({ courseId: null });
    }
  }

  fetchAllEmployees = async () => {
    let employeeList = this.state.schoolEmployeeList;
    if (!employeeList?.length) {
      this.isLoading('employeeListFetching', true);
      employeeList =
        (await fetchSchoolEmployeesApi({
          schoolId: this.state.schoolId,
          token: this.props.loggedUserToken,
          pageParams: this.state.assignmentPageParams,
          profession: 'TEACHING',
        })) || [];
      this.setState({ schoolEmployeeList: employeeList });
      this.isLoading('employeeListFetching', false);
    }
    if (employeeList?.length) {
      const urlEmployeeId = decodeUrlId(this.getQueryParams().get('employeeId'));
      const matchedEmployee = employeeList.find(dto => dto.employeeId === urlEmployeeId);
      let { employeeId } = matchedEmployee || employeeList[0];
      // Nobody picked a teacher yet (first visit, or a dashboard card): start on the first teacher that has a class,
      // instead of one without classes, which leaves every tab here empty behind a red "No class found".
      const startedWithoutTeacher = !matchedEmployee && !this.props.storeEmployeeId;
      if (startedWithoutTeacher) {
        employeeId = await this.findFirstEmployeeWithCourse(employeeList, employeeId);
      }
      if (!this.props.storeEmployeeId && employeeId) {
        passEmployeeIdToStore(employeeId);
        passCourseIdToStore(0);
      }
      this.setState(prevState => ({
        ...prevState,
        employeeId,
        courseId: 0,
      }));
      this.fetchEmployeeCourses(employeeId, startedWithoutTeacher);
    }
  };

  findFirstEmployeeWithCourse = async (employeeList, fallbackEmployeeId) => {
    const { batchId } = getGlobalCurrentBatchUtils();
    if (!batchId) return fallbackEmployeeId;
    this.isLoading('courseListFetching', true);
    try {
      for (const employee of employeeList) {
        const courses = await this.props.fetchEmployeeCourses({
          employeeId: employee.employeeId,
          batchId,
          token: this.props.loggedUserToken,
        });
        if (courses?.length) return employee.employeeId;
      }
      return fallbackEmployeeId;
    } finally {
      this.isLoading('courseListFetching', false);
    }
  };

  fetchEmployeeCourses = async (employeeId, isSelectChange) => {
    const { batchId } = getGlobalCurrentBatchUtils();
    if (employeeId) {
      this.setState({
        employeeId,
        ...(isSelectChange && { courseId: 0 }),
      });
      if (batchId) {
        let courseList = this.props.empCourseList;
        if (!courseList?.length || isSelectChange) {
          this.isLoading('courseListFetching', true);
          courseList = await this.props.fetchEmployeeCourses({
            employeeId,
            batchId,
            token: this.props.loggedUserToken,
          });
          this.isLoading('courseListFetching', false);
        }
        if (courseList?.length) {
          let courseId = courseList[0].courseId;
          if (!isSelectChange) {
            const urlCourseId = decodeUrlId(this.getQueryParams().get('courseId'));
            const matchedCourse = courseList.find(dto => dto.courseId === urlCourseId);
            if (matchedCourse) {
              courseId = matchedCourse.courseId;
            }
          }
          if (courseId && courseId !== this.props.storeCourseId) {
            passActiveTabAndCourseId(this.state.activeTab, courseId);
            passCourseIdToStore(courseId);
          }
          this.setState({
            courseId,
          });
          if (this.state.activeTab === 2) {
            // another class starts again from the latest page
            this.setState({ homeworkLimit: LIST_PAGE, assignmentLimit: LIST_PAGE }, () => {
              this.fetchHomeWorksData(this.state.selectedDate, true, true);
              this.fetchAssignmentsData(this.state.selectedDate, false, null, true);
            });
          }
        } else {
          passCourseIdToStore(0);
        }
      }
    } else if (isSelectChange) {
      this.setState({
        employeeId: 0,
        courseId: 0,
      });
    }
  };

  fetchStudentAbsentees = async (courseId, date) => {
    const { batchId } = getGlobalCurrentBatchUtils();
    if (courseId) {
      if (this.state.schoolId && batchId) {
        this.props.fetchClassPeriods({
          schoolId: this.state.schoolId,
          batchId,
          courseId,
          day: moment(date).format('ddd').toUpperCase(),
          token: this.props.loggedUserToken,
        });
      }
      if (batchId) {
        this.isLoading('attendanceFetchLoading', true);
        await this.props.fetchStudentAbsentees({
          courseId,
          batchId,
          date: moment(date).format('YYYY-MM-DD'),
          token: this.props.loggedUserToken,
        });
        this.isLoading('attendanceFetchLoading', false);
      }
    }
  };

  fetchCourseStudents = (courseId, isSelectChange) => {
    const { batchId } = getGlobalCurrentBatchUtils();
    if (courseId) {
      this.setState({ courseId });
      const date = this.state.selectedDate;
      if (
        (!this.props.courseStudentList?.length || isSelectChange) &&
        (this.state.activeTab === 1 || this.state.activeTab === 4)
      ) {
        this.props.fetchCourseStudents({
          courseId,
          batchId,
          token: this.props.loggedUserToken,
        });
      }
      if (this.state.activeTab === 1) {
        this.fetchStudentAbsentees(courseId, date);
      }
      this.setState({ homeworkLimit: LIST_PAGE, assignmentLimit: LIST_PAGE }, () => {
        this.fetchHomeWorksData(this.state.selectedDate, true, true);
        this.fetchAssignmentsData(this.state.selectedDate, false, null, true);
      });
      const { startYear, endYear } = getCurrentYearBatchUtils();
      if (!batchId && this.state.schoolId) {
        this.props.fetchCurrentBatch({
          courseId,
          startYear,
          endYear,
          token: this.props.loggedUserToken,
          schoolId: this.state.schoolId,
        });
      }
    } else if (isSelectChange) {
      this.setState({
        courseId: 0,
      });
    }
  };

  fetchHomeWorksData = async (date, canCallEmpSubject, refetchAgain, limit = this.state.homeworkLimit) => {
    const { storeCourseId = this.state.courseId, homeWorkList } = this.props;
    if (date && this.state.employeeId && storeCourseId && (!homeWorkList?.length || refetchAgain)) {
      this.isLoading('homeworkFetching', true);
      await this.props.fetchAllHomeWorks({
        employeeId: this.state.employeeId,
        courseId: storeCourseId,
        token: this.props.loggedUserToken,
        limit,
      });
      this.isLoading('homeworkFetching', false);
    }
    if (this.state.employeeId && (canCallEmpSubject || !this.props.empSubjectList?.length)) {
      this.props.fetchEmployeeSubjects({
        employeeId: this.state.employeeId,
        token: this.props.loggedUserToken,
      });
    }
  };

  fetchAllAssignments = async (date, refetchAgain, limit = this.state.assignmentLimit) => {
    const { storeCourseId = this.state.courseId } = this.props;
    if (
      date &&
      this.state.employeeId &&
      storeCourseId &&
      (!this.props.assignmentsData?.content?.length || refetchAgain)
    ) {
      this.isLoading('assignmentFetching', true);
      await this.props.fetchAllAssignments({
        employeeId: this.state.employeeId,
        courseId: storeCourseId,
        token: this.props.loggedUserToken,
        limit,
      });
      this.isLoading('assignmentFetching', false);
    }
  };

  // "Load more": the next LIST_PAGE older items (the list is asked again with a bigger limit).
  loadMoreHomeWork = () => {
    const homeworkLimit = this.state.homeworkLimit + LIST_PAGE;
    this.setState({ homeworkLimit });
    return this.fetchHomeWorksData(this.state.selectedDate, false, true, homeworkLimit);
  };

  loadMoreAssignments = () => {
    const assignmentLimit = this.state.assignmentLimit + LIST_PAGE;
    this.setState({ assignmentLimit });
    return this.fetchAllAssignments(this.state.selectedDate, true, assignmentLimit);
  };

  fetchAssignmentsData = (date, canCallEmpSubject, page, refetchAgain) => {
    if (page && page !== this.state.assignmentPageParams.page) {
      this.setState(
        {
          assignmentPageParams: {
            ...this.state.assignmentPageParams,
            page,
          },
        },
        () => {
          this.fetchAllAssignments(date, refetchAgain);
        }
      );
    } else {
      this.fetchAllAssignments(date, refetchAgain);
    }
  };

  showWarning = (message, type) => {
    this.attendanceLoading(false);
    this.setState({
      confirmModalOpen: false,
      assignConfirmModalOpen: false,
    });
    store.dispatch(showToast(message, type));
  };

  toggleActivityTab = (event, tabIndex, isInitialOpen) => {
    if (tabIndex !== undefined && this.state.activeTab !== tabIndex) {
      // Not on the first open: the teacher and class are still being picked automatically then.
      if (!isInitialOpen && tabIndex <= 4 && this.getDisableAll()) {
        const message =
          this.props.loggedUserRole === constants.roles.teacher
            ? `Please select a ${courseStatic.toLowerCase()} to perform this action`
            : `Please select a ${employeeStatic.toLowerCase()} and ${courseStatic.toLowerCase()} to perform this action`;
        this.showWarning(message, 'warning');
      }
      store.dispatch(setStoreActiveTab(tabIndex));
      this.setState({ activeTab: tabIndex }, () => {
        if (tabIndex === 1 || tabIndex === 4) {
          this.fetchCourseStudents(this.props.storeCourseId);
        }
        if (tabIndex === 2) {
          this.fetchHomeWorksData(this.state.selectedDate, false);
          this.fetchAssignmentsData(this.state.selectedDate, false);
        }
      });
      const cTab = tabList.find(dto => dto.tabIndex === tabIndex);
      if (cTab) {
        this.updateUrlParams({ tab: cTab.query });
      }
    }
  };

  passSelectedDate = selectedDate => {
    const { storeCourseId = this.state.courseId } = this.props;
    this.setState({ selectedDate });
    if (this.state.activeTab === 1) {
      this.fetchStudentAbsentees(storeCourseId, selectedDate);
    }
  };

  initiateAttendance = type => {
    this.setState({ initiateType: type });
    const { batchId } = getGlobalCurrentBatchUtils();
    const { courseId } = this.state;
    if (batchId && courseId) {
      this.props
        .initiateAttendance({
          batchId,
          courseId,
          token: this.props.loggedUserToken,
          type,
          // The day being looked at (today by default), so a past day can be started too.
          date: moment(this.state.selectedDate).format('YYYY-MM-DD'),
        })
        .then(res => {
          store.dispatch(getStudentsAbsentees(res.data));
          this.attendanceLoading(false);
        });
    } else {
      this.showWarning('Either Batch or course is invalid, Please check and try again', 'warning');
    }
  };

  updateAttendance = async data => {
    const { storeCourseId = this.state.courseId } = this.props;
    const globalSchool = getGlobalSchoolUtils();
    const { batchId } = getGlobalCurrentBatchUtils();
    return this.props
      .updateAttendance({
        updateData: data.studentAbsentArr,
        month: data.month,
        day: parseInt(data.day, 10),
        token: this.props.loggedUserToken,
        courseId: storeCourseId,
        batchId,
        schoolId: this.state.schoolId || globalSchool?.schoolId,
      })
      .then(res => {
        store.dispatch(getStudentsAbsentees(res.data));
        this.showWarning('Updated successfully', 'success');
        this.attendanceLoading(false);
      })
      .catch(err => this.setError(err));
  };

  deleteStudentAbsent = async data => {
    await this.props.deleteStudentAbsent({
      deleteData: [data.deleteData],
      month: data.month,
      day: parseInt(data.day, 10),
      token: this.props.loggedUserToken,
    });
  };

  setError = err => {
    this.showWarning(formResMessage(err), 'error');
  };

  attendanceLoading = value => {
    this.setState({ isAttendanceLoading: value, initiateType: null });
  };

  // componentWillUnmount() {
  //   store.dispatch({ type: 'CLEAR_STORE_EXCEPT_AUTH_SCHOOL' });
  // }

  getDisableAll = () => {
    const { loggedUserRole, storeEmployeeId, storeCourseId } = this.props;
    if (loggedUserRole === constants.roles.SA || loggedUserRole === constants.roles.admin) {
      return !storeEmployeeId || !storeCourseId;
    } else if (loggedUserRole === constants.roles.teacher) {
      return !storeCourseId;
    }
  };

  render() {
    const {
      activeTab,
      // employeeId,
      // courseId,
      schoolId,
      assignmentPageParams,
      // disableAll,
      isAttendanceLoading,
      initiateType,
      // Loading
      attendanceFetchLoading,
      homeworkFetching,
      assignmentFetching,
      employeeListFetching,
      courseListFetching,
      schoolEmployeeList,
    } = this.state;
    const {
      loggedUserRole,
      empCourseList,
      classPeriodList,
      studentsAbsentees,
      courseStudentList: courseStudents,
      currentBatch,
      storeEmployeeId: storeEmpId,
      storeCourseId,
      loggedUserId,
      userProfile,
    } = this.props;
    const disableAll = this.getDisableAll(); // Except the tabs that greater than 4.
    const storeEmployeeId = loggedUserRole === constants.roles.teacher ? loggedUserId : storeEmpId;
    const isTeacherLogin = loggedUserRole === constants.roles.teacher;
    const selectedEmployee = schoolEmployeeList?.find(dto => dto.employeeId === storeEmployeeId);
    // Tabs up to Exams & Marks work on one teacher's class; without one, say so instead of leaving the page blank.
    const noClassState = (
      <EmptyState
        icon={<AppsIcon style={{ color: colors.accent }} />}
        title={
          !isTeacherLogin && !storeEmployeeId
            ? `Select a ${employeeStatic.toLowerCase()} to continue`
            : isTeacherLogin
            ? `No ${courseStatic.toLowerCase()} is assigned to you yet`
            : `No ${courseStatic.toLowerCase()} found${
                selectedEmployee?.name ? ` for ${toTitleCase(selectedEmployee.name)}` : ''
              }`
        }
        subtitle={
          isTeacherLogin
            ? `Ask your school admin to assign a ${courseStatic.toLowerCase()} to you for this batch.`
            : `Choose another ${employeeStatic.toLowerCase()} above, or assign a ${courseStatic.toLowerCase()} to this ${employeeStatic.toLowerCase()} first.`
        }
      />
    );
    const noClassGuard = (node, tab) =>
      activeTab === tab && disableAll && !employeeListFetching && !courseListFetching ? noClassState : node;

    return (
      <div className="content">
        <EmpActivityFilter
          activeTab={activeTab}
          loggedUserRole={loggedUserRole}
          employees={schoolEmployeeList}
          employeeId={storeEmployeeId}
          courseId={storeCourseId}
          courses={empCourseList}
          fetchEmployeeCourses={this.fetchEmployeeCourses}
          fetchCourseStudents={this.fetchCourseStudents}
          employeeListFetching={employeeListFetching}
          teacherName={userProfile?.name}
          courseListFetching={courseListFetching}
        />
        <Paper square>
          <Tabs
            value={activeTab}
            onChange={(e, tabIndex) => this.toggleActivityTab(e, tabIndex)}
            indicatorColor=""
            textColor="inherit"
            variant="scrollable"
            scrollButtons="on"
            aria-label="scrollable force tabs example">
            {tabList.map(item => {
              return (
                <Tab
                  key={item.tabIndex}
                  icon={item?.icon}
                  label={item.tabTitle}
                  style={{
                    fontWeight: 'bold',
                    color: activeTab === item.tabIndex ? colors.accent : '',
                    borderBottom: activeTab === item.tabIndex ? `3px solid ${colors.accent}` : '',
                  }}
                />
              );
            })}
          </Tabs>
        </Paper>
        <ScrollTabPanel value={activeTab} index={0}>
          <br />
          {noClassGuard(
            <CalendarPage
              propEmployeeId={storeEmployeeId}
              propsCourseId={storeCourseId}
              propsSchoolId={schoolId}
              courses={empCourseList}
              courseStudents={courseStudents}
              isEmpOrCourseIdIsInvalid={disableAll}
              disableAll={disableAll || activeTab !== 0}
            />,
            0
          )}
        </ScrollTabPanel>
        <ScrollTabPanel value={activeTab} index={1}>
          <br />
          {noClassGuard(
            <AttendanceWithLeavesPage
              disableAll={disableAll || activeTab !== 1}
              isEmpOrCourseIdIsInvalid={disableAll}
              stateCourseId={storeCourseId}
              courseId={storeCourseId}
              propEmployeeId={storeEmployeeId}
              courseStudents={courseStudents}
              passSelectedDate={this.passSelectedDate}
              classPeriodList={classPeriodList?.filter(
                dto => dto.subjectCode !== 'LUNCH' && dto.subjectCode !== 'BREAK'
              )}
              studentsAbsentees={studentsAbsentees}
              isAttendanceLoading={isAttendanceLoading}
              attendanceLoading={this.attendanceLoading}
              initiateAttendance={this.initiateAttendance}
              updateAttendance={this.updateAttendance}
              deleteStudentAbsent={this.deleteStudentAbsent}
              showWarning={(messageData, type) => this.showWarning(messageData, type)}
              initiateType={initiateType}
              attendanceFetchLoading={attendanceFetchLoading}
            />,
            1
          )}
        </ScrollTabPanel>
        <ScrollTabPanel value={activeTab} index={2}>
          <br />
          {noClassGuard(
            <HomeWorkPage
              disableAll={disableAll || activeTab !== 2}
              homeworkFetching={homeworkFetching}
              assignmentFetching={assignmentFetching}
              isEmpOrCourseIdIsInvalid={disableAll}
              propEmployeeId={storeEmployeeId}
              propsCourseId={storeCourseId}
              propsSchoolId={schoolId}
              courseStudents={courseStudents}
              fetchHomeWorksData={this.fetchHomeWorksData}
              fetchAssignmentsData={this.fetchAssignmentsData}
              assignmentPageParams={assignmentPageParams}
              homeworkLimit={this.state.homeworkLimit}
              assignmentLimit={this.state.assignmentLimit}
              onLoadMoreHomeWork={this.loadMoreHomeWork}
              onLoadMoreAssignments={this.loadMoreAssignments}
            />,
            2
          )}
        </ScrollTabPanel>
        <ScrollTabPanel value={activeTab} index={3}>
          <br />
          {noClassGuard(
            <MeetingPage
              disableAll={disableAll || activeTab !== 3}
              isEmpOrCourseIdIsInvalid={disableAll}
              propEmployeeId={storeEmployeeId}
              courseId={storeCourseId}
              courseStudents={courseStudents}
            />,
            3
          )}
        </ScrollTabPanel>
        <ScrollTabPanel value={activeTab} index={4}>
          <br />
          {noClassGuard(
            <MarksPage
              disableAll={disableAll || activeTab !== 4}
              isEmpOrCourseIdIsInvalid={disableAll}
              propEmployeeId={storeEmployeeId}
              courseId={storeCourseId}
              courseStudents={courseStudents}
              currentBatch={currentBatch}
            />,
            4
          )}
        </ScrollTabPanel>
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    loggedUserRole: state.auth.loggedUserRole,
    // employeesData: state.employees.employeesData,
    empCourseList: state.courses.empCourseList,
    courseStudents: state.students.courseStudentData?.content || [],
    courseStudentList: state.schools.courseStudentList,
    classPeriodList: state.students.classPeriodList,
    studentsAbsentees: state.students.studentsAbsenteesList,
    currentBatch: state.batches.currentBatch || {},
    storeEmployeeId: state.employees.storeEmployeeId,
    storeCourseId: state.employees.storeCourseId,
    subjectList: state.subjects.subjectList || [],
    homeWorkList: state.students.homeWorkList,
    assignmentsData: state.students.assignmentsData,
    empSubjectList: state.subjects.empSubjectList || [],
    userProfile: state.auth.userProfile,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchEmployeeCourses: data => dispatch(fetchEmployeeCoursesService(data)),
    fetchCourseStudents: data => dispatch(fetchSchoolCourseStudentsService(data)),

    // Attendance
    fetchClassPeriods: data => dispatch(fetchClassPeriodsService(data)),
    fetchStudentAbsentees: data => dispatch(fetchStudentAbsenteesService(data)),
    initiateAttendance: data => dispatch(initiateAttendanceService(data)),
    updateAttendance: data => dispatch(updateAttendanceService(data)),
    deleteStudentAbsent: data => dispatch(deleteStudentAbsentService(data)),

    // Home work
    fetchEmployeeSubjects: data => dispatch(fetchEmployeeSubjectsService(data)),
    fetchAllHomeWorks: data => dispatch(fetchAllHomeWorksService(data)),
    // Assignment
    fetchAllAssignments: data => dispatch(fetchAllAssignmentsService(data)),
    // Subjects
    fetchSchoolSubjects: data => dispatch(fetchSchoolSubjectsService(data)),
    // Current batch
    fetchCurrentBatch: data => dispatch(fetchCurrentBatchByYearService(data)),
    fetchUser: data => dispatch(fetchUserService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(EmployeeActivityPage);
