import React, { useState } from 'react';
import { Dropdown, DropdownToggle, DropdownMenu } from 'reactstrap';
import ConfirmModal from './ConfirmModal';
import AssignmentIcon from '@material-ui/icons/Assignment';
import VisibilityIcon from '@material-ui/icons/Visibility';
import EditIcon from '@material-ui/icons/Edit';
import DeleteIcon from '@material-ui/icons/Delete';
import AccountCircleIcon from '@material-ui/icons/AccountCircle';
import { MenuItem } from '@material-ui/core';
import useAppProvider from 'providers/useAppProvider';

const ListDropDown = ({
  actionList,
  viewItem,
  fetchItem,
  deleteItem,
  viewStudentStatus,
  viewStudentReport,
  viewStudentTaskAssignmentReport,
  viewStudentProgressReport,
}) => {
  const stateObj = {
    isOpen: false,
    confirmModalOpen: false,
  };
  const { buttonColor, buttonBorderColor } = useAppProvider();

  const [stateVal, setState] = useState(stateObj);

  const toggle = () => setState(prevState => ({ ...prevState, isOpen: !prevState.isOpen }));

  const deleteCancel = () => setState(prevState => ({ ...prevState, confirmModalOpen: false }));

  const deleteAsk = () => setState(prevState => ({ ...prevState, confirmModalOpen: true }));

  const deleteConfirm = () => {
    deleteItem();
    deleteCancel();
  };

  const actionClick = acType => {
    const cb = {
      view: viewItem,
      edit: fetchItem,
      delete: deleteAsk,
      'students status': viewStudentStatus,
      'student report': viewStudentReport,
      view_student: viewItem,
      student_report: viewStudentReport,
      student_task_assignment: viewStudentTaskAssignmentReport,
      student_progress_report: viewStudentProgressReport,
      view_as_user: viewItem,
    };
    if (typeof cb?.[acType] === 'function') cb?.[acType]();
  };

  const getIcon = (name, color) => (
    <i className={`fas ${name}`} style={color ? { color } : {}} aria-hidden="true" type="ellipsis" />
  );

  const renderIcon = actionType => {
    const icons = {
      view: <VisibilityIcon fontSize="small" />,
      edit: <EditIcon fontSize="small" />,
      delete: <DeleteIcon fontSize="small" />,
      'students status': <AccountCircleIcon fontSize="small" />,
      view_student: <VisibilityIcon fontSize="small" />,
      view_report: <AssignmentIcon fontSize="small" />,
      student_report: <AssignmentIcon fontSize="small" />,
      student_task_assignment: <AssignmentIcon fontSize="small" />,
      student_progress_report: <AssignmentIcon fontSize="small" />,
      view_as_user: <VisibilityIcon fontSize="small" />,
    };
    return icons?.[actionType];
  };

  const values = {
    edit: 'Edit',
    view: 'View details',
    view_report: 'View full report',
    delete: 'Delete',
    view_student: 'View Student',
    student_report: 'View student report',
    student_task_assignment: 'Student task & assignments report',
    student_progress_report: 'Student progress report',
    view_as_user: 'View as user',
    'students status': 'Students status',
  };

  if (actionList?.length) {
    return (
      <>
        <Dropdown size="sm" direction="left" isOpen={stateVal.isOpen} toggle={() => toggle()} style={{ margin: -5 }}>
          <DropdownToggle color="link" style={{ background: 'white', border: '0.5px solid #cccccc' }}>
            {getIcon('fa-ellipsis-h', buttonColor || buttonBorderColor)}
          </DropdownToggle>
          {stateVal.isOpen && (
            <DropdownMenu size="sm" left="true" style={{ borderRadius: 'inherit' }}>
              {actionList
                .map(el => ({ key: el, label: values[el] }))
                .map((dt, i) => {
                  return (
                    <React.Fragment key={i}>
                      <MenuItem onClick={() => actionClick(dt?.key)} size="small" left="true" style={{ fontSize: 12 }}>
                        {renderIcon(dt?.key)}
                        <span style={{ margin: '5px 0px 5px 10px' }}>{dt.label?.toUpperCase()}</span>
                      </MenuItem>
                    </React.Fragment>
                  );
                })}
            </DropdownMenu>
          )}
        </Dropdown>
        <ConfirmModal
          confirmModalOpen={stateVal.confirmModalOpen}
          deleteConfirm={deleteConfirm}
          deleteCancel={deleteCancel}
        />
      </>
    );
  }
  return null;
};

export default ListDropDown;
