import React from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Input, Label, FormGroup } from 'reactstrap';
import moment from 'moment';
import Validator from 'validator';
import DatePicker from 'react-datepicker';
import CustomButton from '../../../../../components/CustomButton';
import { formResMessage } from 'utils/commonFunc';

const stateObj = {
  data: {
    meetingId: null,
    title: '',
    description: '',
    meetupDate: '',
    meetupEndTime: '',
    meetupStartTime: '',
    meetupUrl: '',
    status: 'PENDING',
  },
  errors: {},
  loading: false,
};

export const getSelecDateTime = (time = new Date()) => {
  const dateTime = moment(time).format();
  return dateTime;
};

class MeetingFormModal extends React.Component {
  state = stateObj;

  componentDidUpdate(prevProps) {
    if (prevProps?.meeting !== this.props.meeting) {
      const { meeting } = this.props;
      this.setState({
        data: {
          meetingId: meeting?.meetingId,
          title: meeting?.title,
          description: meeting?.description,
          meetupDate: meeting?.meetupDate,
          meetupEndTime: getSelecDateTime(meeting?.meetupEndTime, meeting?.meetupDate),
          meetupStartTime: getSelecDateTime(meeting?.meetupStartTime, meeting?.meetupDate),
          meetupUrl: meeting?.meetupUrl,
          status: 'PENDING',
        },
      });
    }
  }

  handleChange = e =>
    this.setState({
      data: { ...this.state.data, [e.currentTarget.name]: e.currentTarget.value },
    });

  handleDateChange = (name, date) => {
    this.setState({
      data: {
        ...this.state.data,
        [name]: name === 'meetupDate' ? moment(date).format('YYYY-MM-DD') : date,
        ...(name === 'meetupDate' && {
          meetupStartTime: null,
          meetupEndTime: null,
        }),
      },
    });
  };

  handleSubmit = e => {
    e.preventDefault();
    const { data } = this.state;
    const errors = this.validate(data);
    this.setState({ errors });
    if (!Object.keys(errors).length) {
      const postData = {
        ...data,
        meetupStartTime: getSelecDateTime(data.meetupStartTime, data.meetupDate),
        meetupEndTime: getSelecDateTime(data.meetupEndTime, data.meetupDate),
      };
      this.setState({ loading: true });
      if (data.meetingId) {
        return this.props
          .updateMeeting(postData)
          .then(() => {
            this.stateReset();
            this.props.meetingUpdateSuccess('update');
          })
          .catch(err => {
            this.setError(err);
          });
      }
      return this.props
        .saveMeeting(postData)
        .then(() => {
          this.stateReset();
          this.props.meetingUpdateSuccess('add');
        })
        .catch(err => {
          this.setError(err);
        });
    }
  };

  setError = err => {
    this.setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  stateReset = () => {
    this.setState(stateObj);
  };

  formModalClose = () => {
    this.stateReset();
    this.props.formModalCloseProp();
  };

  validate = data => {
    const errors = {};

    if (Validator.isEmpty(data.description)) {
      errors.description = 'Description cannot be empty';
    }

    if (Validator.isEmpty(data.title)) {
      errors.title = 'Title cannot be empty';
    }

    if (!data.meetupDate) {
      errors.meetupDate = 'Online class date cannot be empty';
    }

    if (!data.meetupStartTime) {
      errors.meetupStartTime = 'Start time cannot be empty';
    }

    if (!data.meetupEndTime) {
      errors.meetupEndTime = 'End time cannot be empty';
    }

    if (!data.meetupUrl) {
      errors.meetupUrl = 'Online class location link cannot be empty';
    } else if (!Validator.isURL(data.meetupUrl)) {
      errors.meetupUrl = 'Invalid meeting location link';
    }

    if (
      data.meetupStartTime &&
      moment(data.meetupStartTime).format('YYYY-MM-DD HH:mm') === moment(data.meetupEndTime).format('YYYY-MM-DD HH:mm')
    ) {
      errors.meetupEndTime = 'End time and Start time cannot be the same';
    } else if (
      data.meetupEndTime &&
      moment(data.meetupStartTime).format('YYYY-MM-DD HH:mm') > moment(data.meetupEndTime).format('YYYY-MM-DD HH:mm')
    ) {
      errors.meetupEndTime = 'End time cannot be less than start time';
    }

    return errors;
  };

  getHour = (date, isStartTime) => {
    if (isStartTime) {
      return 9; // 9AM
    }
    return moment(date || null).format('HH');
  };

  getMinute = (date, isStartTime) => {
    if (isStartTime) {
      return 0; // 9AM
    }
    return moment(date || null).format('mm');
  };

  render() {
    const { isModalOpen } = this.props;
    const { data, errors, loading } = this.state;
    // An online class can be edited on any day, past or upcoming.
    const canEdit = () => true;
    const thisData = (
      <Modal size="lg" isOpen={isModalOpen}>
        <form onSubmit={this.handleSubmit}>
          <ModalHeader>{data.meetingId ? 'UPDATE ONLINE CLASS' : 'ADD NEW ONLINE CLASS'}</ModalHeader>
          <ModalBody>
            {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
            <div className="content">
              <div className="container-fluid">
                <Row>
                  <Col sm={12}>
                    <FormGroup>
                      <Label htmlFor="">
                        Title<sup> *</sup>
                      </Label>
                      <Input
                        type="text"
                        name="title"
                        onChange={this.handleChange}
                        value={data.title}
                        placeholder="Enter here..."
                        maxLength="200"
                      />
                      {errors.title && <span className="err-msg">{errors.title}</span>}
                    </FormGroup>
                  </Col>
                </Row>
                <Row>
                  <Col sm={12}>
                    <FormGroup>
                      <Label htmlFor="">
                        Online Class Location Link<sup> *</sup>
                        <span style={{ color: 'orange', marginLeft: 5 }}>[Google-Meet, Zoom, Webx, etc.,]</span>
                      </Label>
                      <Input
                        type="text"
                        name="meetupUrl"
                        onChange={this.handleChange}
                        value={data.meetupUrl}
                        placeholder="Enter here..."
                        maxLength="200"
                      />
                      {errors.meetupUrl && <span className="err-msg">{errors.meetupUrl}</span>}
                    </FormGroup>
                  </Col>
                </Row>
                <Row>
                  <Col md={12}>
                    <FormGroup className="customDatePickerWidth">
                      <Label htmlFor="">
                        Online class date<sup> *</sup>
                      </Label>
                      <br />
                      <DatePicker
                        className="form-control"
                        selected={data.meetupDate ? new Date(data.meetupDate) : null}
                        onChange={date => this.handleDateChange('meetupDate', date)}
                        // showYearDropdown
                        showMonthDropdown
                        dateFormat="dd/MM/yyyy"
                        dropdownMode="select"
                      />
                      {errors.meetupDate && <span className="err-msg">{errors.meetupDate}</span>}
                    </FormGroup>
                  </Col>
                </Row>
                <Row>
                  <Col md={6}>
                    <FormGroup className="customDatePickerWidth">
                      <Label htmlFor="">
                        Start time<sup> *</sup>
                      </Label>
                      <br />
                      <DatePicker
                        className="form-control"
                        selected={data.meetupStartTime ? new Date(data.meetupStartTime) : null}
                        onChange={date => this.handleDateChange('meetupStartTime', date)}
                        showTimeSelect
                        showTimeSelectOnly
                        timeIntervals={5}
                        timeCaption="Time"
                        dateFormat="h:mm aa"
                        minDate={new Date(data.meetupDate)}
                        maxDate={new Date(data.meetupDate)}
                        minTime={moment(data.meetupDate)
                          .hours(this.getHour(data.meetupDate, true))
                          .minute(this.getMinute(data.meetupDate, true))
                          .toDate()}
                        maxTime={moment(data.meetupDate).hours(18).minute(30).toDate()}
                        disabled={!data.meetupDate}
                        dropdownMode="select"
                      />
                      {errors.meetupStartTime && <span className="err-msg">{errors.meetupStartTime}</span>}
                    </FormGroup>
                  </Col>
                  <Col md={6}>
                    <FormGroup className="customDatePickerWidth">
                      <Label htmlFor="">
                        End time<sup> *</sup>
                      </Label>
                      <br />
                      <DatePicker
                        className="form-control"
                        selected={data.meetupEndTime ? new Date(data.meetupEndTime) : null}
                        onChange={date => this.handleDateChange('meetupEndTime', date)}
                        showTimeSelect
                        showTimeSelectOnly
                        timeIntervals={5}
                        timeCaption="Time"
                        dateFormat="h:mm aa"
                        minDate={new Date(data.meetupDate)}
                        maxDate={new Date(data.meetupDate)}
                        minTime={moment(data.meetupDate)
                          .hours(this.getHour(data.meetupStartTime))
                          .minute(this.getMinute(data.meetupStartTime))
                          .toDate()}
                        maxTime={moment(data.meetupDate).hours(19).minute(0).toDate()}
                        disabled={!data.meetupDate || !data.meetupStartTime}
                        dropdownMode="select"
                      />
                      {errors.meetupEndTime && <span className="err-msg">{errors.meetupEndTime}</span>}
                    </FormGroup>
                  </Col>
                </Row>
                <Row>
                  <Col sm={12}>
                    <FormGroup>
                      <Label htmlFor="">
                        Description<sup> *</sup>
                      </Label>
                      <Input
                        multiple
                        type="text"
                        name="description"
                        onChange={this.handleChange}
                        value={data.description}
                        placeholder="Enter here..."
                        maxLength="1000"
                      />
                      {errors.description && <span className="err-msg">{errors.description}</span>}
                    </FormGroup>
                  </Col>
                </Row>
              </div>
            </div>
          </ModalBody>
          <ModalFooter>
            <CustomButton type="submit" disabled={loading || !canEdit()} loading={loading} />
            <CustomButton
              className="ml-2"
              type="button"
              color="default"
              disabled={loading}
              onClick={this.formModalClose}
              name="Cancel"
            />
          </ModalFooter>
        </form>
      </Modal>
    );
    return <div>{thisData}</div>;
  }
}

export default MeetingFormModal;
