import React, { useEffect, useState } from 'react';
import moment from 'moment';
import { Modal, ModalHeader, ModalBody, ModalFooter, Table, Input } from 'reactstrap';
import EmptyState from 'views/admin/Common/EmptyState';
import CustomButton from 'components/CustomButton';
import { formResMessage } from 'utils/commonFunc';

const isStarted = exam => moment(new Date(exam.examDate)).format('YYYY-MM-DD') < moment().format('YYYY-MM-DD');

// A student's marks for a main exam. A teacher or admin can switch it to edit mode: every subject of the exam gets its own
// box and one Save writes the changed ones (a mark that exists is updated, a new one added). Subjects whose exam has not been
// held yet are shown but cannot be filled in.
const MarkViewModal = ({
  isViewMarkModalOpen,
  formModalClose,
  studentExamMarkList: myExamSubjectList,
  mainExamTotalMark,
  courseStudentDiv,
  // Editing
  subjectExams = [],
  examTypeDetailId,
  studentId,
  batchId,
  token,
  saveMark,
  showWarning,
  onSaved,
}) => {
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [values, setValues] = useState({});

  const studentExamMarkList = myExamSubjectList.map(el => ({
    ...el,
    totalMark: mainExamTotalMark,
  }));
  const savedFor = subjectId => myExamSubjectList.find(item => item.subject?.subjectId === subjectId);
  const canEdit = !!studentId && !!saveMark && subjectExams.length > 0;
  const rows = [...subjectExams].sort((a, b) => new Date(a.examDate) - new Date(b.examDate));

  useEffect(() => {
    if (!isViewMarkModalOpen) {
      setEditing(false);
    }
  }, [isViewMarkModalOpen]);

  const startEditing = () => {
    const initial = {};
    rows.forEach(exam => {
      const saved = savedFor(exam.subject?.subjectId);
      initial[exam.subject?.subjectId] = saved?.progReportId ? `${saved.studentMark ?? ''}` : '';
    });
    setValues(initial);
    setEditing(true);
  };

  const change = (subjectId, value) => {
    if (value !== '' && Number(mainExamTotalMark) && Number(value) > Number(mainExamTotalMark)) {
      showWarning(`Mark cannot be more than ${mainExamTotalMark}`, 'warning');
      return;
    }
    setValues(prev => ({ ...prev, [subjectId]: value }));
  };

  const changedRows = rows.filter(exam => {
    const subjectId = exam.subject?.subjectId;
    const saved = savedFor(subjectId);
    return (
      isStarted(exam) &&
      values[subjectId] !== '' &&
      values[subjectId] !== undefined &&
      `${saved?.progReportId ? saved.studentMark : ''}` !== `${values[subjectId]}`
    );
  });

  const saveAll = async () => {
    if (!changedRows.length) {
      showWarning('Nothing to update. Change a mark first.', 'warning');
      return;
    }
    setSaving(true);
    const results = await Promise.allSettled(
      changedRows.map(exam => {
        const subjectId = exam.subject?.subjectId;
        const saved = savedFor(subjectId);
        return saveMark({
          postData: {
            examTypeDetails: { examTypeDetailId },
            subject: { subjectId },
            studentMark: values[subjectId],
            student: { studentId },
            batchId,
          },
          ...(saved?.progReportId && { progReportId: saved.progReportId }),
          token,
        });
      })
    );
    setSaving(false);
    const failed = results.filter(result => result.status === 'rejected');
    onSaved?.();
    if (failed.length) {
      showWarning(
        `Saved ${changedRows.length - failed.length} of ${changedRows.length} marks. ${formResMessage(
          failed[0].reason
        )}`,
        'error'
      );
    } else {
      showWarning('Marks updated successfully', 'success');
      setEditing(false);
    }
  };

  const emptyDiv = (
    <tr>
      <td colSpan="4">
        <EmptyState compact bare icon="far fa-clipboard" title="No marks yet" />
      </td>
    </tr>
  );
  const closeBtn = (
    <i
      className="fas fa-times"
      style={{ fontSize: 20, color: '#000000', cursor: 'pointer' }}
      onClick={formModalClose}
    />
  );

  const editTotal = rows.reduce((sum, exam) => sum + (Number(values[exam.subject?.subjectId]) || 0), 0);

  const thisData = (
    <Modal size="lg" isOpen={isViewMarkModalOpen}>
      <ModalHeader close={closeBtn}>{editing ? 'ENTER STUDENT MARKS' : 'VIEW STUDENT MARK'}</ModalHeader>
      <ModalBody style={{ background: 'powdergrey' }}>
        <div className="content">
          <div className="container-fluid">
            {courseStudentDiv}
            <hr />
            {editing ? (
              <Table size="sm" responsive>
                <thead className="text-primary">
                  <tr>
                    <th>Subject</th>
                    <th className="text-center">Total Mark</th>
                    <th className="text-center" style={{ width: 140 }}>
                      Student Mark
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {rows.map(exam => {
                    const subjectId = exam.subject?.subjectId;
                    const started = isStarted(exam);
                    return (
                      <tr key={exam.examSubjectDetailId}>
                        <td>
                          {exam.subject?.name}
                          {!started && <div style={{ fontSize: 12, color: '#888' }}>Exam not held yet</div>}
                        </td>
                        <td className="text-center">{mainExamTotalMark}</td>
                        <td className="text-center">
                          <Input
                            type="number"
                            size="sm"
                            min={0}
                            max={mainExamTotalMark || undefined}
                            disabled={!started || saving}
                            value={values[subjectId] ?? ''}
                            onChange={e => change(subjectId, e.target.value)}
                          />
                        </td>
                      </tr>
                    );
                  })}
                  <tr>
                    <td>
                      <strong>Total marks</strong>
                    </td>
                    <td className="text-center">
                      <strong>{(Number(mainExamTotalMark) || 0) * rows.length}</strong>
                    </td>
                    <td className="text-center">
                      <strong>{editTotal}</strong>
                    </td>
                  </tr>
                </tbody>
              </Table>
            ) : (
              <Table size="sm" responsive>
                <thead className="text-primary">
                  <tr>
                    <th>Subject</th>
                    <th className="text-center">Total Mark</th>
                    <th className="text-center">Student Mark</th>
                  </tr>
                </thead>
                <tbody>
                  {studentExamMarkList.length > 0
                    ? studentExamMarkList.map((item, i) => {
                        return (
                          <tr key={i}>
                            <td>{item.subject.name}</td>
                            <td className="text-center">{item.totalMark}</td>
                            <td className="text-center">{item.studentMark}</td>
                          </tr>
                        );
                      })
                    : emptyDiv}
                  {studentExamMarkList.length > 0 && (
                    <tr>
                      <td>
                        <strong>Total marks</strong>
                      </td>
                      <td className="text-center">
                        <strong>
                          {studentExamMarkList.map(data => data.totalMark).reduce((a, b) => a + (b ? b : 0), 0)}
                        </strong>
                      </td>
                      <td className="text-center">
                        <strong>
                          {studentExamMarkList.map(data => data.studentMark).reduce((a, b) => a + (b ? b : 0), 0)}
                        </strong>
                      </td>
                    </tr>
                  )}
                </tbody>
              </Table>
            )}
          </div>
        </div>
      </ModalBody>
      {canEdit && (
        <ModalFooter>
          {editing ? (
            <>
              <CustomButton type="button" loading={saving} disabled={saving} onClick={saveAll} name="Update marks" />
              <CustomButton
                className="ml-2"
                type="button"
                color="default"
                disabled={saving}
                onClick={() => setEditing(false)}
                name="Cancel"
              />
            </>
          ) : (
            <CustomButton
              type="button"
              onClick={startEditing}
              name={studentExamMarkList.length ? 'Edit marks' : 'Enter marks'}
            />
          )}
        </ModalFooter>
      )}
    </Modal>
  );

  return <div>{thisData}</div>;
};

export default MarkViewModal;
