import React from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter } from 'reactstrap';
import CustomButton from '../../../../../components/CustomButton';
import EmptyState from 'views/admin/Common/EmptyState';

class StudentsStatusViewModal extends React.PureComponent {
  render() {
    const { isStatusModalOpen, formModalClose, studentsAssignmentStatusList } = this.props;
    const thisData = (
      <Modal size="lg" isOpen={isStatusModalOpen}>
        <form onSubmit={this.handleSubmit}>
          <ModalHeader>STUDENTS ASSIGNMENT STATUS</ModalHeader>
          <ModalBody>
            <div className="content">
              <div className="container-fluid">
                <table className="table table-bordered">
                  <thead>
                    <th>#</th>
                    <th>Student</th>
                    <th>Status</th>
                  </thead>
                  <tbody>
                    {studentsAssignmentStatusList?.length > 0 ? (
                      studentsAssignmentStatusList.map(item => {
                        return (
                          <tr key={item.studentAssignSeqId}>
                            <td>{item.studentAssignSeqId}</td>
                            <td>{`${item.firstName} ${item.lastName}`}</td>
                            <td>{item.status}</td>
                          </tr>
                        );
                      })
                    ) : (
                      <tr>
                        <td colSpan={3}>
                          <EmptyState compact bare icon="fas fa-user-graduate" title="No students found" />
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </ModalBody>
          <ModalFooter>
            <CustomButton type="button" color="default" onClick={formModalClose} name="Cancel" />
          </ModalFooter>
        </form>
      </Modal>
    );
    return <div>{thisData}</div>;
  }
}

export default StudentsStatusViewModal;
