import React, { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Input, Label, FormGroup } from 'reactstrap';
import Select from 'react-select';
import moment from 'moment';
import ReactDatePicker from 'react-datepicker';
import {
  formResMessage,
  getCurrentYearBatchUtils,
  getGlobalCurrentBatchUtils,
  infoIconSm,
} from '../../../../../utils/commonFunc';
import CustomButton from '../../../../../components/CustomButton';
import CommonTooltip from 'views/admin/Common/CommonTooltip';
import { courseStatic } from 'config/constants';

const localCommonExams = [
  {
    name: 'QUART_YEARLY',
  },
  {
    name: 'HALF_YEARLY',
  },
  {
    name: 'ANUAL_EXAM',
  },
  {
    name: 'MID_TERM',
  },
  {
    name: 'CLASS_TEST',
  },
];
const ExamTypeFormModal = ({
  isModalOpen,
  saveExamType,
  // updateExam,
  examUpdateSuccess,
  formModalCloseProp,
  exam,
  commonExams,
  examTypeList,
}) => {
  const currentBatch = getGlobalCurrentBatchUtils();
  const stateObj = {
    data: {
      school: { schoolId: 0 },
      createdUser: { id: 0 },
      batch: { batchId: null },
      examDetailId: 0,
      examTitle: '',
      examType: '',
      startDate: '',
      endDate: '',
      examDuration: '',
      subjectTotalMark: '',
    },
    errors: {},
    loading: false,
  };

  const [stateVal, setState] = useState(stateObj);

  useEffect(() => {
    if (exam && Object.keys(exam).length) {
      setState(prevState => ({
        ...prevState,
        data: {
          school: { schoolId: exam.school.schoolId },
          examDetailId: exam.examDetailId,
          examTitle: exam.examTitle,
          examType: exam.examType,
          startDate: exam.startDate,
          endDate: exam.endDate,
          batch: { batchId: exam.batch.batchId },
        },
      }));
    }
  }, [exam]);

  const handleChange = (name, value) => {
    setState(prevState => ({
      ...prevState,
      data: {
        ...prevState.data,
        [name]: value,
      },
    }));
  };

  const handleSelectChange = (name, selectItem) => {
    setState(prevState => ({
      ...prevState,
      data: {
        ...prevState.data,
        [name]: selectItem.value,
        examTitle: selectItem.name,
      },
    }));
  };

  const handleDateChange = (name, date) => {
    setState(prevState => ({
      ...prevState,
      data: {
        ...prevState.data,
        [name]: moment(date).format('YYYY-MM-DD'),
      },
    }));
  };

  const checkIsExamExist = async (sDate, eDate) => {
    const convert = dt => moment(new Date(dt)).format('YYYY-MM-DD');
    const someExist = examTypeList.some(sEl => {
      return (
        (convert(sDate) > convert(sEl.startDate) && convert(sDate) < convert(sEl.endDate)) ||
        (convert(eDate) > convert(sEl.startDate) && convert(eDate) < convert(sEl.endDate)) ||
        (convert(sEl.startDate) > convert(sDate) && convert(sEl.startDate) < convert(eDate)) ||
        (convert(sEl.endDate) > convert(sDate) && convert(sEl.endDate) < convert(eDate))
      );
    });
    return someExist;
  };

  const handleSubmit = async e => {
    e.preventDefault();
    let dataVal = stateVal.data;
    const errorsObj = validate(dataVal);
    setState(prevState => ({ ...prevState, errors: errorsObj }));
    if (!Object.keys(errorsObj).length) {
      setState(prevState => ({ ...prevState, loading: true }));
      // if (dataVal.examDetailId) {
      //   return updateExam(dataVal)
      //     .then(() => {
      //       stateValReset();
      //       examUpdateSuccess('update');
      //     })
      //     .catch(err => setError(err));
      // } else {
      const { startYear, endYear } = getCurrentYearBatchUtils();
      dataVal = {
        ...dataVal,
        examDuration: dataVal?.examDuration ? moment.utc(dataVal?.examDuration * 3600 * 1000).format('HH:mm') : 0,
        startYear,
        endYear,
      };
      const isExamDateExist = await checkIsExamExist(dataVal.startDate, dataVal.endDate);
      if (!isExamDateExist) {
        return saveExamType(dataVal)
          .then(() => {
            stateValReset();
            examUpdateSuccess('add');
          })
          .catch(err => setError(err));
      } else {
        setError({
          response: {
            data: {
              message: 'Validation failure',
              details: ['Exam date range is clashing with exist exam date range'],
            },
          },
        });
      }
    }
  };

  const setError = err => {
    setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  const stateValReset = () => {
    setState(stateObj);
  };

  const formModalClose = () => {
    stateValReset();
    formModalCloseProp();
  };

  const validate = dataVal => {
    const errorsList = {};
    if (!dataVal.examType) {
      errorsList.examType = 'Exam type cannot be empty';
    }

    if (!dataVal.startDate) {
      errorsList.startDate = 'Start Date cannot be empty';
    }

    if (!dataVal.endDate) {
      errorsList.endDate = 'End Date cannot be empty';
    } else if (data?.startDate > data?.endDate) {
      errorsList.endDate = 'End date cannot be less than Start date';
    }

    if (!dataVal.examDuration) {
      errorsList.examDuration = 'Exam duration cannot be empty';
    } else if (dataVal.examDuration > 4) {
      errorsList.examDuration = 'Exam duration cannot be more than 4 hours';
    } else if (dataVal.examDuration < 1) {
      errorsList.examDuration = 'Exam duration cannot be less than 1 hour';
    }

    if (!dataVal.subjectTotalMark) {
      errorsList.subjectTotalMark = 'Exam total mark cannot be empty';
    } else if (dataVal.subjectTotalMark > 300) {
      errorsList.subjectTotalMark = 'Exam total mark cannot be more than 300';
    } else if (dataVal.subjectTotalMark < 25) {
      errorsList.subjectTotalMark = 'Exam total mark cannot be less than 25';
    }

    return errorsList;
  };

  const { data, errors, loading } = stateVal;
  const { startYear, endYear } = getCurrentYearBatchUtils();
  const examEnums = {
    QUART_YEARLY: { label: 'Quarter Yearly', name: 'Quarter Yearly', value: 'QUART_YEARLY' },
    HALF_YEARLY: { label: 'Half Yearly', name: 'Half Yearly', value: 'HALF_YEARLY' },
    ANUAL_EXAM: { label: 'Annual Exam', name: 'Annual Exam', value: 'ANUAL_EXAM' },
    MID_TERM: { label: 'Mid Term Exam', name: 'Mid Term Exam', value: 'MID_TERM' },
    CLASS_TEST: { label: 'Class Test', name: 'Class Test', value: 'CLASS_TEST' },
  };

  const examTypes = (commonExams?.length ? commonExams : localCommonExams)?.map(el => ({ ...examEnums[el.name] }));
  const selDur = data?.examDuration ? moment.utc(data?.examDuration * 3600 * 1000).format('HH:mm') : 0;
  const thisData = (
    <Modal size="lg" isOpen={isModalOpen}>
      <form onSubmit={handleSubmit}>
        <ModalHeader>{data.examDetailId ? 'UPDATE MAIN EXAM' : 'ADD MAIN EXAM'}</ModalHeader>
        <ModalBody>
          {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
          <div className="content">
            <div className="container-fluid">
              <Row>
                <Col>
                  <p>
                    <b>Batch:</b>
                    {` June ${currentBatch.startYear || startYear} to May ${currentBatch.endYear || endYear}`}{' '}
                    <span style={{ color: 'green' }}>Choose the exam start and end dates within this period.</span>
                  </p>
                </Col>
              </Row>
              <Row>
                <Col sm={6}>
                  <FormGroup>
                    <Label htmlFor="">
                      Select Exam Type<sup> *</sup>
                    </Label>
                    <Select
                      value={examTypes.find(dt => dt.value === data.examType) || null}
                      onChange={value => handleSelectChange('examType', value)}
                      options={examTypes}
                      isDisabled={data.examDetailId}
                    />
                    {errors.examType && <span className="err-msg">{errors.examType}</span>}
                  </FormGroup>
                </Col>
                <Col md={6}>
                  <FormGroup>
                    <Label htmlFor="">
                      Exam Title<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="examTitle"
                      value={data.examTitle}
                      placeholder="Enter here..."
                      maxLength="50"
                      disabled
                    />
                  </FormGroup>
                </Col>
                <Col md={6}>
                  <FormGroup className="customDatePickerWidth">
                    <Label htmlFor="">
                      Exam Start Date<sup> *</sup>
                    </Label>
                    <br />
                    <ReactDatePicker
                      className="form-control"
                      selected={data.startDate ? new Date(data.startDate) : null}
                      onChange={value => handleDateChange('startDate', value)}
                      dateFormat="dd/MM/yyyy"
                      showMonthDropdown
                      showYearDropdown
                      placeholderText="Select date..."
                      dropdownMode="select"
                    />
                    {errors.startDate && <span className="err-msg">{errors.startDate}</span>}
                  </FormGroup>
                </Col>
                <Col md={6}>
                  <FormGroup className="customDatePickerWidth">
                    <Label htmlFor="">
                      Exam End Date<sup> *</sup>
                    </Label>
                    <br />
                    <ReactDatePicker
                      className="form-control"
                      selected={data.endDate ? new Date(data.endDate) : null}
                      onChange={value => handleDateChange('endDate', value)}
                      dateFormat="dd/MM/yyyy"
                      showMonthDropdown
                      showYearDropdown
                      placeholderText="Select date..."
                      minDate={data.startDate ? new Date(data.startDate) : undefined}
                      dropdownMode="select"
                    />
                    {errors.endDate && <span className="err-msg">{errors.endDate}</span>}
                  </FormGroup>
                </Col>
                <Col md={6}>
                  <FormGroup>
                    <Label htmlFor="">
                      Duration hours (Max 4)<sup> *</sup>{' '}
                      {!!selDur && (
                        <span style={{ color: 'green' }}>{`${Number(selDur.split(':')[0])} hours ${Number(
                          selDur.split(':')[1]
                        )} minutes`}</span>
                      )}
                      <CommonTooltip
                        className="ml-1"
                        content={`This time duration for all the exams comes under ${
                          examTypes?.find(dt => dt.value === data.examType)?.label
                        } for selected ${courseStatic.toLowerCase()}`}>
                        {infoIconSm()}
                      </CommonTooltip>
                    </Label>
                    <Input
                      type="number"
                      name="examDuration"
                      value={data.examDuration}
                      placeholder="Enter here..."
                      // maxLength="50"
                      onChange={e => {
                        const value = e.target.value;
                        if (value <= 4) {
                          handleChange('examDuration', value);
                        }
                      }}
                    />
                    {errors.examDuration && <span className="err-msg">{errors.examDuration}</span>}
                  </FormGroup>
                </Col>
                <Col md={6}>
                  <FormGroup>
                    <Label htmlFor="">
                      Subject total mark<sup> *</sup>
                      <CommonTooltip
                        className="ml-2"
                        content={`This total mark for all the exams comes under ${
                          examTypes?.find(dt => dt.value === data.examType)?.label
                        } for selected ${courseStatic.toLowerCase()}`}>
                        {infoIconSm()}
                      </CommonTooltip>
                    </Label>
                    <Input
                      type="number"
                      name="subjectTotalMark"
                      value={data.subjectTotalMark}
                      placeholder="Enter here..."
                      // maxLength="50"
                      onChange={e => {
                        const value = e.target.value;
                        if (value <= 300) {
                          handleChange('subjectTotalMark', value);
                        }
                      }}
                    />
                    {errors.subjectTotalMark && <span className="err-msg">{errors.subjectTotalMark}</span>}
                  </FormGroup>
                </Col>
              </Row>
            </div>
          </div>
        </ModalBody>
        <ModalFooter>
          <CustomButton type="submit" disabled={loading} loading={loading} />
          <CustomButton
            className="ml-2"
            type="button"
            color="default"
            disabled={loading}
            onClick={formModalClose}
            name="Cancel"
          />
        </ModalFooter>
      </form>
    </Modal>
  );

  return <div>{thisData}</div>;
};

export default ExamTypeFormModal;
