import React, { useEffect, useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Label, FormGroup } from 'reactstrap';
import ReactDatePicker from 'react-datepicker';
import moment from 'moment';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';
import { formResMessage } from 'utils/commonFunc';

const day = value => moment(new Date(value)).format('YYYY-MM-DD');

// Changes the period of a main exam (start and end date). The subject exams of that exam have to stay inside the new
// period, and it may not overlap another main exam of the class - both are checked here before anything is saved.
const EditExamDatesModal = ({ isOpen, exam, subjectExams = [], otherExams = [], onClose, onSave }) => {
  const [startDate, setStartDate] = useState(null);
  const [endDate, setEndDate] = useState(null);
  const [error, setError] = useState('');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (isOpen && exam) {
      setStartDate(exam.startDate ? day(exam.startDate) : null);
      setEndDate(exam.endDate ? day(exam.endDate) : null);
      setError('');
      setSaving(false);
    }
  }, [isOpen, exam]);

  const subjectDays = subjectExams.map(item => day(item.examDate)).sort();
  const firstSubjectDay = subjectDays[0];
  const lastSubjectDay = subjectDays[subjectDays.length - 1];

  const validate = () => {
    if (!startDate || !endDate) return 'Select both the start date and the end date';
    if (startDate > endDate) return 'The end date cannot be before the start date';
    if (subjectDays.length && (firstSubjectDay < startDate || lastSubjectDay > endDate)) {
      return `Subject exams are scheduled from ${moment(firstSubjectDay).format('DD MMM YYYY')} to ${moment(
        lastSubjectDay
      ).format('DD MMM YYYY')}. The exam period has to include these days (or change those subject exams first).`;
    }
    const clash = otherExams.find(other => !(endDate < day(other.startDate) || startDate > day(other.endDate)));
    if (clash) return `These dates overlap the exam "${clash.examTitle}" of this class`;
    return '';
  };

  const submit = async () => {
    const message = validate();
    setError(message);
    if (message) return;
    setSaving(true);
    try {
      await onSave({ startDate, endDate });
    } catch (err) {
      setError(formResMessage(err));
      setSaving(false);
    }
  };

  return (
    <Modal isOpen={isOpen} toggle={saving ? undefined : onClose} size="md">
      <ModalHeader toggle={saving ? undefined : onClose}>EDIT EXAM DATES</ModalHeader>
      <ModalBody>
        {error && <div className="alert alert-danger">{error}</div>}
        <p style={{ marginBottom: 14 }}>
          <b>{exam?.examTitle}</b>
          <span style={{ color: colors.grey2 }}>
            {' '}
            now runs {exam?.startDate ? moment(exam.startDate).format('DD MMM YYYY') : '--'} to{' '}
            {exam?.endDate ? moment(exam.endDate).format('DD MMM YYYY') : '--'}
          </span>
        </p>
        <Row>
          <Col md={6}>
            <FormGroup className="customDatePickerWidth">
              <Label>
                Start date<sup> *</sup>
              </Label>
              <br />
              <ReactDatePicker
                className="form-control"
                selected={startDate ? new Date(startDate) : null}
                onChange={date => setStartDate(date ? day(date) : null)}
                dateFormat="dd/MM/yyyy"
                showMonthDropdown
                showYearDropdown
                dropdownMode="select"
              />
            </FormGroup>
          </Col>
          <Col md={6}>
            <FormGroup className="customDatePickerWidth">
              <Label>
                End date<sup> *</sup>
              </Label>
              <br />
              <ReactDatePicker
                className="form-control"
                selected={endDate ? new Date(endDate) : null}
                onChange={date => setEndDate(date ? day(date) : null)}
                minDate={startDate ? new Date(startDate) : undefined}
                dateFormat="dd/MM/yyyy"
                showMonthDropdown
                showYearDropdown
                dropdownMode="select"
              />
            </FormGroup>
          </Col>
        </Row>
        {!!subjectDays.length && (
          <div style={{ fontSize: 12, color: colors.grey2 }}>
            Its subject exams run {moment(firstSubjectDay).format('DD MMM YYYY')} to{' '}
            {moment(lastSubjectDay).format('DD MMM YYYY')}; the new period has to include them.
          </div>
        )}
      </ModalBody>
      <ModalFooter>
        <CustomButton name="Save dates" onClick={submit} disabled={saving} loading={saving} />
        <CustomButton className="ml-2" color="default" name="Cancel" onClick={onClose} disabled={saving} />
      </ModalFooter>
    </Modal>
  );
};

export default EditExamDatesModal;
