import React from 'react';
import { connect } from 'react-redux';
import moment from 'moment';
import { getGlobalCurrentBatchUtils, formResMessage } from '../../../../utils/commonFunc.js';
import { store } from '../../../../index.js';
import { showToast } from '../../../../actions/admin/auth.js';
import { fetchTimetableAllocationApi } from 'actions/admin/courses';
import { LoadingCard } from 'views/admin/Common/Loader.jsx';
import { passActiveTabAndCourseId } from '../EmployeeActivityPage.jsx';
import TimetableAllocationGrid from 'views/admin/TimeTable/TimetableAllocationGrid.jsx';
import EmptyState from 'views/admin/Common/EmptyState';
import colors from 'config/colors';
import constants, { employeeStatic } from 'config/constants';
// import MuiTable from 'views/admin/Common/MuiTable.jsx';

export const dayList = [
  { label: 'Monday', value: 'MON' },
  { label: 'Tuesday', value: 'TUE' },
  { label: 'Wednesday', value: 'WED' },
  { label: 'Thursday', value: 'THU' },
  { label: 'Friday', value: 'FRI' },
  { label: 'Saturday', value: 'SAT' },
];

export const timePeriods = {
  1: 'I',
  2: 'II',
  3: 'III',
  4: 'IV',
  5: 'V',
  6: 'VI',
  7: 'VII',
  8: 'VIII',
  9: 'IX',
  10: 'X',
};
export const getPeriodName = periodInx => timePeriods[periodInx + 1];

// Closure
export const getNext = () => {
  let count = 0;
  return () => count++;
};
export const getNextCount = getNext();

export const getDayPeriods = (dayItem, inx, courseDayTimeSlots) => {
  const dayTimeTableList = courseDayTimeSlots.filter(dto => dto.day === dayItem.value);
  return (
    <tr key={inx}>
      <td align="center" height="50">
        <b>{dayItem.label}</b>
      </td>
      {dayTimeTableList.map((mEl, index) => {
        const isBreakOrLunch = ['BREAK', 'LUNCH'].includes(mEl.subjectCode);
        const subCode = (
          <span style={{ color: '#bcbcbc', fontWeight: 'bold', fontSize: 11 }}> ({mEl.subjectCode})</span>
        );
        return (
          <td
            key={index}
            align="center"
            height="50"
            style={isBreakOrLunch ? { color: 'orange', fontSize: 13, fontWeight: 'bold' } : { fontSize: 13 }}>
            {!isBreakOrLunch ? (
              <>
                {mEl.subjectName || mEl.subject} {subCode}
              </>
            ) : (
              (mEl.subjectName || mEl.subject)?.toUpperCase()
            )}
          </td>
        );
      })}
    </tr>
  );
};

class TimeTablePage extends React.Component {
  constructor() {
    super();
    this.state = {
      activeTab: '1',
      activityType: 'HOLIDAY',
      selectedDate: new Date(),
      selectedDay:
        moment().format('ddd').toUpperCase() === 'SUN'
          ? moment().add(1, 'day').format('ddd').toUpperCase()
          : moment().format('ddd').toUpperCase(),
      isTimetableFetching: false,
      timetableData: null,
      // 'class': the chosen class's time table; 'teacher': the chosen teacher's own periods across all their classes
      view: 'class',
      teacherTimetable: null,
      isTeacherTimetableFetching: false,
    };
  }

  componentDidMount() {
    const { visitedCourseIds, activeTab, propsCourseId } = this.props;
    if (propsCourseId && visitedCourseIds?.[activeTab] !== propsCourseId) {
      passActiveTabAndCourseId(activeTab, propsCourseId);
      this.fetchTimetableAllocation();
    } else if (!this.props.disableAll) {
      this.fetchTimetableAllocation();
    }
  }

  componentDidUpdate(prevProps) {
    const { activeTab, propsCourseId, propsSchoolId } = this.props;
    // propsSchoolId arrives one render late (EmployeeActivityPage reads it from
    // localStorage inside its own componentDidMount), so on a fresh mount where
    // propsCourseId is already known (e.g. returning to this tab after navigating away
    // and back, with the course already selected from before) componentDidMount's fetch
    // is skipped for missing schoolId, and propsCourseId never "changes" afterwards to
    // trigger this effect - watch propsSchoolId's arrival too so that case still fetches.
    if (prevProps.propsCourseId !== propsCourseId || (!prevProps.propsSchoolId && propsSchoolId)) {
      propsCourseId && passActiveTabAndCourseId(activeTab, propsCourseId);
      this.fetchTimetableAllocation();
    }
  }

  toggle = tab => {
    if (this.state.activeTab !== tab) {
      this.setState({ activeTab: tab });
    }
  };

  fetchTimetableAllocation = async () => {
    const { batchId } = getGlobalCurrentBatchUtils();
    const { propsCourseId, propsSchoolId, loggedUserToken } = this.props;
    if (batchId && propsCourseId && propsSchoolId) {
      this.setState({ isTimetableFetching: true });
      try {
        const res = await fetchTimetableAllocationApi({
          schoolId: propsSchoolId,
          courseId: propsCourseId,
          batchId,
          token: loggedUserToken,
        });
        this.setState({ timetableData: res.data });
      } catch (err) {
        this.showWarning(formResMessage(err), 'error');
      }
      this.setState({ isTimetableFetching: false });
    }
  };

  // The teacher's own time table: the periods they take in every class they teach, taken from each class's time table (so a change
  // made on Generate time table shows here at once). Read only; the admin edits on Generate time table.
  fetchTeacherTimetable = async () => {
    const { batchId } = getGlobalCurrentBatchUtils();
    const { propEmployeeId, propsSchoolId, loggedUserToken, courses } = this.props;
    if (!batchId || !propEmployeeId || !propsSchoolId || !courses?.length) {
      this.setState({ teacherTimetable: null });
      return;
    }
    this.setState({ isTeacherTimetableFetching: true });
    try {
      const results = await Promise.all(
        courses.map(course =>
          fetchTimetableAllocationApi({
            schoolId: propsSchoolId,
            courseId: course.courseId,
            batchId,
            token: loggedUserToken,
          })
        )
      );
      const timetable = results
        .flatMap(res => res.data?.timetable || [])
        .filter(cell => (cell.teacherIds || []).includes(Number(propEmployeeId)))
        // the grid shows the teacher under the subject: here it is the class the teacher takes that period in
        .map(cell => ({ ...cell, teacherNames: [cell.courseName], collision: false, collisionColor: undefined }));
      this.setState({
        teacherTimetable: {
          timetable,
          totalPeriods: 48,
          allocatedPeriods: timetable.length,
          emptyPeriods: 48 - timetable.length,
          collisionCount: 0,
          subjectAllocations: [],
          teacherAllocations: [],
          collisions: [],
        },
      });
    } catch (err) {
      this.showWarning(formResMessage(err), 'error');
    }
    this.setState({ isTeacherTimetableFetching: false });
  };

  changeView = view => {
    this.setState({ view }, () => view === 'teacher' && this.fetchTeacherTimetable());
  };

  showWarning = (message, type) => {
    store.dispatch(showToast(message, type));
  };

  handleDayChange = sItem => {
    this.setState({
      ...this.state,
      selectedDay: sItem.value,
    });
  };

  render() {
    const { isTimetableFetching, timetableData, view, teacherTimetable, isTeacherTimetableFetching } = this.state;
    const isTeacherView = view === 'teacher';
    const options = [
      { key: 'class', label: 'Class time table' },
      { key: 'teacher', label: `${employeeStatic}'s time table` },
    ];
    return (
      <div className="content">
        <div
          style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 10 }}>
          <div
            role="tablist"
            style={{ display: 'inline-flex', padding: 3, borderRadius: 20, background: colors.sidebarActiveItemBg }}>
            {options.map(option => (
              <button
                key={option.key}
                type="button"
                role="tab"
                aria-selected={view === option.key}
                onClick={() => this.changeView(option.key)}
                style={{
                  border: 0,
                  borderRadius: 17,
                  padding: '5px 16px',
                  fontSize: 13,
                  fontWeight: 'bold',
                  cursor: 'pointer',
                  color: view === option.key ? colors.accent : colors.accentDark,
                  opacity: view === option.key ? 1 : 0.75,
                  background: view === option.key ? '#fff' : 'transparent',
                  boxShadow: view === option.key ? '0 1px 4px rgba(91,21,132,0.25)' : 'none',
                }}>
                {option.label}
              </button>
            ))}
          </div>
          {this.props.loggedUserRole !== constants.roles.guardian && (
            <a href="/admin/generate-time-table" style={{ fontSize: 13, fontWeight: 'bold', color: colors.accent }}>
              Edit on Generate time table
            </a>
          )}
        </div>
        <div className="mt-3">
          {isTeacherView ? (
            isTeacherTimetableFetching ? (
              <LoadingCard />
            ) : teacherTimetable?.timetable?.length ? (
              <TimetableAllocationGrid data={teacherTimetable} readOnly />
            ) : (
              <EmptyState
                icon="far fa-calendar-alt"
                title="No periods on the time table"
                subtitle={`This ${employeeStatic.toLowerCase()} is not on any class time table yet. Allocate on Generate time table.`}
              />
            )
          ) : isTimetableFetching ? (
            <LoadingCard />
          ) : (
            <TimetableAllocationGrid data={timetableData} readOnly />
          )}
        </div>
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserToken: state.auth.loggedUserToken,
    loggedUserRole: state.auth.loggedUserRole,
    visitedCourseIds: state.auth.visitedCourseIds,
    activeTab: state.auth.activeTab,
  };
};

export default connect(mapStateToProps)(TimeTablePage);
