import React from 'react';
import SubTabs from '../SubTabs.jsx';
import LeavesPage from '../Leaves/LeavesPage.jsx';
import { empOrCourseEmptyDiv } from '../EmployeeActivityPage.jsx';
import AttendancePage from './AttendancePage.jsx';

const subTabList = [
  { tabName: 'Attendance', index: 0 },
  { tabName: 'Students leave', index: 1 },
];

// Students leave used to live under the Time Table tab, but a timetable and a leave request
// aren't related - whether a student was on leave is attendance information, so it belongs next
// to Attendance instead. Wraps AttendancePage unchanged and reuses the same SubTabs + LeavesPage
// pairing Time Table used to have.
class AttendanceWithLeavesPage extends React.Component {
  state = { subActive: 0 };

  handleSubTabChange = tab => {
    if (tab !== this.state.subActive) {
      this.setState({ subActive: tab });
    }
  };

  render() {
    const { subActive } = this.state;
    const { courseId, propEmployeeId, isEmpOrCourseIdIsInvalid, ...attendanceProps } = this.props;

    return (
      <div className="content">
        <SubTabs
          className="mb-3"
          subTabs={subTabList}
          subActive={subActive}
          tabToggle={tab => this.handleSubTabChange(tab)}
          disabled={isEmpOrCourseIdIsInvalid}
        />
        {subActive === 0 && <AttendancePage {...attendanceProps} isEmpOrCourseIdIsInvalid={isEmpOrCourseIdIsInvalid} />}
        {subActive === 1 &&
          (isEmpOrCourseIdIsInvalid ? (
            empOrCourseEmptyDiv
          ) : (
            <LeavesPage
              disableAll={attendanceProps.disableAll}
              subActive={subActive}
              courseId={courseId}
              propEmployeeId={propEmployeeId}
              isEmpOrCourseIdIsInvalid={isEmpOrCourseIdIsInvalid}
            />
          ))}
      </div>
    );
  }
}

export default AttendanceWithLeavesPage;
