import React from 'react';
import '../EmployeeActivityPage.css';
import moment from 'moment';
import DatePicker from 'views/admin/Common/Datepicker';
import { Card, CardBody, Row, Col, FormGroup, Label } from 'reactstrap';
// Material UI
import { withStyles } from '@material-ui/core/styles';
import FormControlLabel from '@material-ui/core/FormControlLabel';
import Checkbox from '@material-ui/core/Checkbox';
import { green, pink } from '@material-ui/core/colors';
import TextField from '@material-ui/core/TextField';
import CheckCircleIcon from '@material-ui/icons/CheckCircle';
import BorderColorIcon from '@material-ui/icons/BorderColor';
import CancelIcon from '@material-ui/icons/Cancel';
import { courseStatic } from '../../../../config/constants';
import CustomButton from '../../../../components/CustomButton';
import MuiTable from 'views/admin/Common/MuiTable';
import { LoadingCard } from 'views/admin/Common/Loader';
import CustomSelect from 'components/CustomSelect';
import axios from 'axios';
import constants from 'config/constants';
import { setCommonParam } from 'actions/admin/auth';
import { getGlobalCurrentBatchUtils } from 'utils/commonFunc';
import { store } from '../../../../index';
import CustomDraggableDialog from 'views/admin/Common/CustomDraggableDialog';
import QrCodeScanner from './QrCodeScanner/QrCodeScanner';
import Chip from '@material-ui/core/Chip';
import PeopleIcon from '@material-ui/icons/People';
import colors from 'config/colors';

const getStartAndEndTime = (sT, eT) => {
  return {
    start: moment().format(`YYYY-MM-DDT${sT}.00Z`),
    end: moment().format(`YYYY-MM-DDT${eT}.00Z`),
  };
};
const generalPeriods = {
  periodOne: getStartAndEndTime('09:15', '10:00'), // 1
  periodTwo: getStartAndEndTime('10:00', '10:45'), // 2
  morBreak: getStartAndEndTime('10:45', '11:00'), // Morning break
  periodThree: getStartAndEndTime('11:00', '11:45'), // 3
  periodFour: getStartAndEndTime('11:45', '12:30'), // 4
  lunch: getStartAndEndTime('12:30', '13:30'), // Lunch
  periodFive: getStartAndEndTime('13:30', '14:15'), // 5
  periodSix: getStartAndEndTime('14:15', '15:00'), // 6
  eveBreak: getStartAndEndTime('15:00', '15:15'), // Evening break
  periodSeven: getStartAndEndTime('15:15', '16:00'), // 7
  periodEight: getStartAndEndTime('16:00', '16:45'), // 8
  periodNine: getStartAndEndTime('16:45', '17:30'), // 9 - Special class
  periodTen: getStartAndEndTime('17:30', '18:15'), // 10 - Special class
};

const periodStrings = [
  { name: 'periodOne', order: 1 },
  { name: 'periodTwo', order: 2 },
  { name: 'periodThree', order: 3 },
  { name: 'periodFour', order: 4 },
  { name: 'periodFive', order: 5 },
  { name: 'periodSix', order: 6 },
  { name: 'periodSeven', order: 7 },
  { name: 'periodEight', order: 8 },
  { name: 'periodNine', order: 9 },
  { name: 'periodTen', order: 10 },
];
const firstFourPeriods = ['periodOne', 'periodTwo', 'periodThree', 'periodFour'];
const remainingPeriods = ['periodFive', 'periodSix', 'periodSeven', 'periodEight', 'periodNine', 'periodTen'];

const GreenCheckbox = withStyles({
  root: {
    '&$checked': {
      color: green[600],
    },
    disabled: {
      color: green[600],
    },
  },
  checked: {},
})(props => <Checkbox color="default" {...props} />);

const SecondaryCheckbox = withStyles({
  root: {
    '&$checked': {
      color: pink[600],
    },
    disabled: {
      color: pink[600],
    },
  },
  checked: {},
})(props => <Checkbox color="default" {...props} />);

class AttendancePage extends React.Component {
  state = {
    courses: [],
    courseId: 0,
    classPeriod: '',
    selectedDate: new Date(),
    studentAbsentArr: [],
    reasonItem: {},
    presentAll: false,
    // Day wise (the whole day, Full day) is how attendance is normally taken, so it is what the page opens on.
    attendanceType: 'DAY_WISE',
    dayWise: 'FULL_DAY',
    // the class's student leaves (approved or pending) on the selected day
    studentLeaves: [],
  };

  updatePeriodData = () => {
    const { classPeriodList } = this.props;
    if (classPeriodList?.length) {
      if (!this.state.classPeriod) {
        const currentTimePeriod = periodStrings.find(pl => {
          const st = generalPeriods[pl]?.start;
          const et = generalPeriods[pl]?.end;
          const cd = moment().format();
          return st <= cd && et >= cd;
        });
        this.setState({
          classPeriod:
            currentTimePeriod?.order <= classPeriodList?.length ? currentTimePeriod.name : classPeriodList[0].period,
          presentAll: false,
        });
      }
    }
  };

  componentDidMount() {
    this.loadLeaves();
  }

  // The students of the class who are on leave on the selected day. A leave shows as Absent (and cannot be ticked Present),
  // is skipped by Present All, and never counts as an entry still to be filled in - the same as on the mobile app.
  loadLeaves = async () => {
    const { stateCourseId } = this.props;
    const { batchId } = getGlobalCurrentBatchUtils();
    const requestDate = moment(this.state.selectedDate).format('YYYY-MM-DD');
    if (!stateCourseId || !batchId) {
      this.setState({ studentLeaves: [] });
      return;
    }
    try {
      const res = await axios.get(
        `${constants.API_BASE_URL}/api/student/student-leave-on-date/${stateCourseId}/${batchId}/${requestDate}`,
        constants.setHeader(store.getState().auth.loggedUserToken)
      );
      if (
        stateCourseId === this.props.stateCourseId &&
        requestDate === moment(this.state.selectedDate).format('YYYY-MM-DD')
      ) {
        this.setState({
          studentLeaves: (res.data || []).filter(dto => ['APPROVED', 'PENDING'].includes(dto.leaveStatus)),
        });
      }
    } catch (err) {
      this.setState({ studentLeaves: [] });
    }
  };

  isStudentOnLeave = studentId => this.state.studentLeaves.some(dto => dto.student?.studentId === studentId);

  // A leave approved after the attendance was started is shown as Absent, but the stored entry still says NO_SCHEDULE (the
  // backend only fills approved leaves in when it starts the day): saved together with the rest so the record agrees with the screen.
  approvedLeaveAbsentRows = studentAbsentArr =>
    (this.props.studentsAbsentees || [])
      .filter(item => !studentAbsentArr.some(dto => dto.studentId === item.studentId))
      .map(item => {
        const leave = this.state.studentLeaves.find(
          dto => dto.student?.studentId === item.studentId && dto.leaveStatus === 'APPROVED'
        );
        const allPeriods = [...firstFourPeriods, ...remainingPeriods];
        if (!leave || !allPeriods.some(period => item[period] === 'NO_SCHEDULE')) {
          return null;
        }
        const row = { ...item, reason: item.reason || leave.reason };
        allPeriods.forEach(period => {
          row[period] = 'ABSENT';
        });
        return row;
      })
      .filter(Boolean);

  componentDidUpdate = (prevProps, prevState) => {
    const { stateCourseId, classPeriodList = [] } = this.props;
    if (
      prevProps.stateCourseId !== stateCourseId ||
      prevState.selectedDate !== this.state.selectedDate ||
      prevProps.studentsAbsentees?.length !== this.props.studentsAbsentees?.length
    ) {
      this.loadLeaves();
    }
    if (
      (prevProps.stateCourseId !== stateCourseId || prevProps.classPeriodList !== classPeriodList) &&
      classPeriodList.length
    ) {
      this.updatePeriodData();
    }
  };

  initiateAttendance = (e, type) => {
    e?.preventDefault();
    this.props.attendanceLoading(true);
    this.props.initiateAttendance(type);
  };

  handleDateChange = async selectedDate => {
    this.setState(prevState => {
      return { ...prevState, selectedDate };
    });
    await this.props.passSelectedDate(selectedDate);
    this.updatePeriodData();
  };

  handleCheck = async (absItem, checkedValue, checkType) => {
    const { studentAbsentArr, attendanceType, dayWise } = this.state;
    const absArr = [...studentAbsentArr];
    if (attendanceType === 'PERIOD_WISE') {
      const inx = absArr?.findIndex(data => data.studentId === absItem?.studentId);
      if (inx !== null && inx > -1) {
        absArr[inx] = {
          ...absArr[inx],
          [this.state.classPeriod]: checkedValue === 'PRESENT' ? 'ABSENT' : 'PRESENT',
          ...(checkType === 'absent' && { reason: absArr[inx].reason }),
        };
      } else {
        absArr.push({
          ...absItem,
          [this.state.classPeriod]: checkType === 'present' ? 'PRESENT' : 'ABSENT',
        });
      }
      this.setState(prevState => ({
        ...prevState,
        studentAbsentArr: absArr,
        ...(checkType === 'absent' && this.state.presentAll && { presentAll: false }),
      }));
    } else {
      // Bug fixed: this used to `.map()` over the *entire* studentAbsentArr and re-toggle every
      // already-marked student on every single click, instead of touching only the clicked
      // student - clicking one student's Present/Absent after others were already marked
      // silently flipped everyone else's entries too. Now mirrors the PERIOD_WISE branch above:
      // find-this-student-or-push, only ever writing the clicked student's record.
      const perList = dayWise === 'HALF_DAY' ? firstFourPeriods : [...firstFourPeriods, ...remainingPeriods];
      const inx = absArr?.findIndex(data => data.studentId === absItem?.studentId);
      if (inx !== null && inx > -1) {
        let resObj = { ...absArr[inx] };
        perList.forEach(incEl => {
          resObj[incEl] = checkedValue === 'PRESENT' ? 'ABSENT' : 'PRESENT';
        });
        absArr[inx] = {
          ...resObj,
          ...(checkType === 'absent' && { reason: absArr[inx].reason }),
        };
      } else {
        // Also fixed: a brand-new entry (this student's first click in day-wise mode) has no
        // prior classPeriod value, so `checkedValue` is undefined here - the old
        // `checkedValue === 'PRESENT' ? 'ABSENT' : 'PRESENT'` check always fell through to
        // 'PRESENT' no matter which button was clicked, so a first click on Absent silently
        // recorded Present instead. Use `checkType` (which button was actually clicked) instead,
        // matching the PERIOD_WISE branch's equivalent else-case above.
        let resObj = { ...absItem };
        perList.forEach(incEl => {
          resObj[incEl] = checkType === 'present' ? 'PRESENT' : 'ABSENT';
        });
        absArr.push(resObj);
      }
      this.setState(prevState => ({
        ...prevState,
        studentAbsentArr: absArr,
        ...(checkType === 'absent' && this.state.presentAll && { presentAll: false }),
      }));
    }
  };

  enableEdit = (absStudent, editField, canEdit) => {
    this.setState(prevState => ({
      ...prevState,
      reasonItem: {
        ...prevState.reasonItem,
        [absStudent.studentId]: absStudent.reason,
      },
      [editField]: canEdit,
    }));
  };

  updateReason = (absItem, canReasonEditName) => {
    const absArr = [...this.state.studentAbsentArr];
    const inx = absArr?.findIndex(data => data.studentId === absItem?.studentId);
    if (inx !== null && inx > -1) {
      absArr[inx] = {
        ...absArr[inx],
        reason: this.state.reasonItem[absItem.studentId]?.trim(),
      };
    } else {
      absArr.push({
        ...absItem,
        reason: this.state.reasonItem[absItem.studentId]?.trim(),
      });
    }

    this.setState(prevState => ({
      ...prevState,
      studentAbsentArr: absArr,
      [canReasonEditName]: false,
    }));
  };

  isSomeAttendanceEntryPending = () => {
    const { studentsAbsentees } = this.props;
    const { classPeriod, studentAbsentArr } = this.state;
    return studentsAbsentees?.some(el => {
      if (this.isStudentOnLeave(el.studentId)) {
        return false;
      }
      if (el?.[classPeriod] === 'NO_SCHEDULE') {
        const existItem = studentAbsentArr?.find(dto => dto.studentId === el.studentId);
        if (existItem) {
          return existItem[classPeriod] === 'NO_SCHEDULE';
        }
        const isPending = true;
        return isPending;
      }
      return false;
    });
  };

  updateAttendance = async () => {
    const { selectedDate } = this.state;
    const studentAbsentArr = [
      ...this.state.studentAbsentArr,
      ...this.approvedLeaveAbsentRows(this.state.studentAbsentArr),
    ];
    if (this.state.studentAbsentArr?.length) {
      if (!this.isSomeAttendanceEntryPending()) {
        this.props.showWarning('Updating attendance...', 'info');
        this.props.attendanceLoading(true);
        return this.props
          .updateAttendance({
            studentAbsentArr,
            month: moment(selectedDate).format('MMMM'),
            day: moment(selectedDate).format('DD'),
          })
          .then(() => {
            this.setState({
              studentAbsentArr: [],
              reasonItem: {},
              presentAll: false,
            });
          });
      } else {
        this.props.showWarning(
          'There are some entries is not update neither present nor absent, Please check and try again',
          'warning'
        );
      }
    } else {
      this.props.showWarning('There is no changes in students attendance to update', 'info');
    }
  };

  resetAttendanceState = (name, selectItem) => {
    this.setState({
      studentAbsentArr: [],
      reasonItem: {},
      ...(name && selectItem && { [name]: selectItem }),
      presentAll: false,
    });
  };

  submitResult() {
    const { studentsAbsentees } = this.props;
    const { studentAbsentArr } = this.state;
    if (
      studentsAbsentees?.length &&
      studentAbsentArr?.length &&
      JSON.stringify(studentsAbsentees || []) !== JSON.stringify(studentAbsentArr || [])
    ) {
      if (
        confirm(
          'There are some changes in currently selected period. Changing period will delete all the selected period attendance entries. Do you want to continue?'
        ) === false
      ) {
        return false;
      } else {
        return true;
      }
    }
    return true;
  }

  handleSelectChange = (name, selectItem) => {
    if (name === 'classPeriod') {
      if (this.state.studentAbsentArr?.length) {
        if (this.submitResult()) {
          this.resetAttendanceState(name, selectItem);
        }
      } else {
        this.resetAttendanceState(name, selectItem);
      }
    } else {
      this.setState(prevState => ({
        ...prevState,
        presentAll: false,
        dayWise: selectItem,
      }));
    }
  };

  handlePresentAllCheck = () => {
    const { attendanceType, dayWise } = this.state;
    this.setState({ presentAll: true });
    if (attendanceType === 'PERIOD_WISE') {
      const absArr = this.props.studentsAbsentees
        .filter(dto => !this.isStudentOnLeave(dto.studentId))
        .filter(dto => dto?.[this.state.classPeriod] !== 'PRESENT')
        .map(absItem => ({
          ...absItem,
          [this.state.classPeriod]: 'PRESENT',
        }));
      this.setState(prevState => ({
        ...prevState,
        studentAbsentArr: absArr,
      }));
    } else {
      const perList = dayWise === 'HALF_DAY' ? firstFourPeriods : [...firstFourPeriods, ...remainingPeriods];
      const absDaysArr = this.props.studentsAbsentees
        .filter(dto => !this.isStudentOnLeave(dto.studentId))
        .map(dto => {
          let resObj = {
            ...dto,
          };
          perList.forEach(incEl => {
            resObj[incEl] = resObj?.[incEl] !== 'PRESENT' ? 'PRESENT' : resObj?.[incEl];
          });
          return resObj;
        });
      this.setState(prevState => ({
        ...prevState,
        studentAbsentArr: absDaysArr,
      }));
    }
  };

  handleAttendanceTypeChange = attendanceType => {
    if (this.submitResult()) {
      this.resetAttendanceState();
      this.setState(prevState => ({
        ...prevState,
        presentAll: false,
        attendanceType,
        // choosing Day wise always starts on Full day
        ...(attendanceType === 'DAY_WISE' && { dayWise: 'FULL_DAY' }),
      }));
    }
  };

  openScanDialog = () => {
    setCommonParam('isDragDialogOpen', true);
  };

  render() {
    const { classPeriod, selectedDate, studentAbsentArr, reasonItem, presentAll, attendanceType, dayWise } = this.state;
    const {
      isAttendanceLoading,
      disableAll,
      stateCourseId,
      courseStudents,
      classPeriodList,
      studentsAbsentees,
      initiateType,
      // loading
      attendanceFetchLoading,
    } = this.props;

    const isTodaySelected = moment(selectedDate).isSame(moment(), 'day');

    // The API doesn't guarantee period order, so sort by the period's actual position
    // (periodOne < periodTwo < ...) rather than trusting whatever order it comes back in -
    // otherwise the dropdown can list periods out of sequence.
    const classPeriodArr = [...(classPeriodList || [])]
      .sort((a, b) => {
        const orderA = periodStrings.find(pl => pl.name === a.period)?.order ?? 0;
        const orderB = periodStrings.find(pl => pl.name === b.period)?.order ?? 0;
        return orderA - orderB;
      })
      .map(item => ({
        label: `${item.subjectName} - ${item.timePeriod}`,
        value: item.period,
      }));

    // Day wise attendance doesn't use periods at all, so it must not be gated on the period
    // list - only period-wise attendance needs a selected class period to mark against.
    const disableCheckbox = attendanceType === 'PERIOD_WISE' ? !classPeriod : false;
    // Day-wise entries are written to every period key in the day's period list at once (see
    // handleCheck/handlePresentAllCheck below), all with the same value - so any one of them,
    // e.g. periodOne, reflects the row's actual state. Reading `classPeriod` here instead (which
    // stays '' whenever the selected day has no scheduled periods) silently hid every day-wise
    // present/absent mark: the checkbox never showed checked and the Present/Absent counts stayed
    // at 0 even though the entry was being recorded correctly.
    const representativePeriod = attendanceType === 'PERIOD_WISE' ? classPeriod : 'periodOne';

    // A segmented pill control reads as a deliberate two-way mode switch at a glance - a plainer
    // pair of radio buttons here looked like two ordinary form fields rather than one toggle.
    const attendanceTypeToggle = (
      <div
        style={{
          display: 'inline-flex',
          borderRadius: 8,
          border: `1.5px solid ${colors.accent}`,
          overflow: 'hidden',
          opacity: !courseStudents?.length ? 0.5 : 1,
          pointerEvents: !courseStudents?.length ? 'none' : 'auto',
        }}>
        {[
          { value: 'DAY_WISE', label: 'Day wise' },
          { value: 'PERIOD_WISE', label: 'Period wise' },
        ].map(opt => {
          const isActive = attendanceType === opt.value;
          return (
            <button
              key={opt.value}
              type="button"
              onClick={() => !isAttendanceLoading && this.handleAttendanceTypeChange(opt.value)}
              style={{
                border: 'none',
                outline: 'none',
                cursor: 'pointer',
                padding: '8px 16px',
                fontSize: 13,
                fontWeight: 'bold',
                backgroundColor: isActive ? colors.accent : '#FFFFFF',
                color: isActive ? '#FFFFFF' : colors.accent,
                transition: 'background-color 0.15s ease',
              }}>
              {opt.label}
            </button>
          );
        })}
      </div>
    );

    // Attendance can be taken or corrected for any day (a teacher may fill a whole week at the end of it).
    const presentAllDiv = (
      <FormControlLabel
        control={
          <GreenCheckbox
            disabled={presentAll || disableCheckbox || !studentsAbsentees?.length}
            checked={!!presentAll}
            onChange={() => !isAttendanceLoading && this.handlePresentAllCheck()}
          />
        }
        label="Present All"
      />
    );

    const getAttendanceList = () => {
      return studentsAbsentees?.map(item => {
        const currentAbsentItem = studentAbsentArr?.find(dto => dto.absentId === item.absentId) || item;
        const student = courseStudents?.find(data => data.studentId === item.studentId);
        const editField = `${currentAbsentItem.studentId}_edit`;
        const presentCheck = currentAbsentItem[representativePeriod] === 'PRESENT';
        const onLeave = this.isStudentOnLeave(currentAbsentItem.studentId);
        const absentCheck = currentAbsentItem[representativePeriod] === 'ABSENT' || onLeave;
        const stateReason = reasonItem[currentAbsentItem.studentId];
        const absentReason = stateReason !== undefined ? stateReason : currentAbsentItem.reason;
        const studentName = student?.firstName
          ? `${student?.firstName}${student?.middleName ? ` ${student?.middleName}` : ''} ${student?.lastName}`
          : '';
        return {
          // Merged reg no + name into one column, matching the mobile app's student row layout
          // (TeacherView.js formStudentName + a grey bracketed register number underneath).
          student: (
            <>
              <span>{studentName}</span>
              {student?.registerNumber && (
                <span style={{ color: colors.grey3, fontSize: 12, marginLeft: 6 }}>({student.registerNumber})</span>
              )}
            </>
          ),
          absentAction: (
            <>
              <FormControlLabel
                control={
                  <GreenCheckbox
                    disabled={disableCheckbox || onLeave}
                    checked={!!presentCheck && !onLeave}
                    onChange={() =>
                      !isAttendanceLoading &&
                      this.handleCheck(currentAbsentItem, currentAbsentItem[representativePeriod], 'present')
                    }
                  />
                }
                label="Present"
              />
              <FormControlLabel
                control={
                  <SecondaryCheckbox
                    disabled={disableCheckbox || onLeave}
                    checked={!!absentCheck}
                    onChange={() => {
                      !isAttendanceLoading &&
                        this.handleCheck(currentAbsentItem, currentAbsentItem[representativePeriod], 'absent');
                    }}
                  />
                }
                label="Absent"
              />
            </>
          ),
          editAction: (
            <>
              {!this.state[editField] && absentCheck && (absentReason || absentCheck) ? (
                <>
                  {onLeave ? 'Leave' : absentReason}
                  {/* a leave is its own reason: it is not edited here */}
                  {!onLeave && (
                    <>
                      <BorderColorIcon
                        className="ml-1"
                        style={{ color: 'green', cursor: 'pointer' }}
                        fontSize="small"
                        color="action"
                        onClick={() => {
                          !isAttendanceLoading && this.enableEdit(currentAbsentItem, editField, true);
                        }}
                      />
                    </>
                  )}
                </>
              ) : null}
              {this.state[editField] && (
                <span className="row">
                  <TextField
                    label="Reason"
                    multiline
                    rows={2}
                    variant="outlined"
                    id={`${item[classPeriod]}`}
                    value={reasonItem[item.studentId] || absentReason || ''}
                    size="small"
                    onChange={e => {
                      if (!isAttendanceLoading) {
                        e.persist();
                        this.setState({
                          reasonItem: {
                            [item.studentId]: e.target.value,
                          },
                        });
                      }
                    }}
                    onBlur={() => {
                      !isAttendanceLoading && this.updateReason(currentAbsentItem, editField);
                    }}
                  />
                  <CheckCircleIcon
                    className="ml-1 mr-1"
                    style={{ color: 'green', cursor: 'pointer' }}
                    fontSize="small"
                    color="action"
                    onClick={() => {
                      !isAttendanceLoading && this.updateReason(currentAbsentItem, editField);
                    }}
                  />
                  <CancelIcon
                    fontSize="small"
                    color="secondary"
                    onClick={() => this.enableEdit(currentAbsentItem, editField, false)}
                  />
                </span>
              )}
            </>
          ),
        };
      });
    };

    const tableHeaders = ['Student', 'Attendance', 'Absent reason'];

    // Present All rendered as its own body row (first, above the actual students) rather than
    // packed into the column header - it now shows up with the table itself in both Period wise
    // and Day wise mode, instead of sitting off to the side in the filter card above the table.
    const presentAllRow = presentAllDiv && { student: '', absentAction: presentAllDiv, editAction: '' };

    const tableData = (
      <MuiTable
        tableHeaders={tableHeaders}
        tableBodyData={{
          content:
            courseStudents?.length > 0 && studentsAbsentees?.length > 0
              ? [...(presentAllRow ? [presentAllRow] : []), ...getAttendanceList()]
              : [],
        }}
        bodyColumns={['student', 'absentAction', 'editAction']}
        hidePagination={true}
        cellPadding={{ paddingTop: 5, paddingBottom: 5 }}
      />
    );

    // const isWeekEnd = moment(new Date()).weekday() === 6 || moment(new Date()).weekday() === 0;

    const attendanceTypes = [
      { label: 'Full day', value: 'FULL_DAY' },
      { label: 'Half day', value: 'HALF_DAY' },
    ];

    const presentCount =
      studentsAbsentees?.filter(item => {
        const currentAbsentItem = studentAbsentArr?.find(dto => dto.absentId === item.absentId) || item;
        return currentAbsentItem[representativePeriod] === 'PRESENT';
      })?.length || 0;
    const absentCount =
      studentsAbsentees?.filter(item => {
        const currentAbsentItem = studentAbsentArr?.find(dto => dto.absentId === item.absentId) || item;
        return currentAbsentItem[representativePeriod] === 'ABSENT';
      })?.length || 0;
    const totalCount = studentsAbsentees?.length || 0;

    return (
      <div className="content">
        <Card className="p-3 mb-3">
          <Row>
            <Col xs={12} sm={6} md={3} className="mb-3 mb-sm-0">
              <FormGroup className="customDatePickerWidth mb-0">
                <Label htmlFor="">
                  <strong>
                    Date<sup> *</sup>{' '}
                  </strong>
                  {!stateCourseId ? (
                    <span style={{ color: 'orange' }}> [Select {courseStatic.toLowerCase()} to enable]</span>
                  ) : (
                    <Chip
                      size="small"
                      label="Today"
                      clickable={!isTodaySelected}
                      onClick={() => !isTodaySelected && !isAttendanceLoading && this.handleDateChange(new Date())}
                      style={{
                        marginLeft: 6,
                        fontWeight: 'bold',
                        fontSize: 11,
                        height: 20,
                        cursor: isTodaySelected ? 'default' : 'pointer',
                        backgroundColor: isTodaySelected ? colors.accent : `${colors.accent}1a`,
                        color: isTodaySelected ? '#FFFFFF' : colors.accent,
                      }}
                    />
                  )}
                </Label>
                <br />
                <DatePicker
                  handleDateChange={date => !isAttendanceLoading && this.handleDateChange(date)}
                  selectedDate={selectedDate}
                  disabled={!stateCourseId || !courseStudents.length || attendanceFetchLoading}
                  dropdownMode="select"
                />
              </FormGroup>
            </Col>
            <Col xs={12} sm={6} md={9}>
              <div style={{ display: 'flex', flexDirection: 'row', flexWrap: 'wrap' }}>
                <div style={{ minWidth: 220 }}>
                  <FormGroup className="mb-0">
                    {/* Invisible spacer matching the select's single-line label height, so the
                    toggle and the dropdown's actual controls start on the same row - both labels
                    must stay single-line (the periods-warning below used to live inside the
                    select's label and wrap it to two lines, pushing the dropdown down out of
                    line with this toggle). */}
                    <Label style={{ visibility: 'hidden' }}>
                      <strong>Mode</strong>
                    </Label>
                    <br />
                    {attendanceTypeToggle}
                  </FormGroup>
                </div>
                <div style={{ flex: 1, minWidth: 220, paddingInline: 10 }}>
                  <FormGroup className="mb-0">
                    <CustomSelect
                      label={
                        attendanceType === 'PERIOD_WISE' ? (
                          <strong>
                            Class Period<sup> *</sup>
                          </strong>
                        ) : (
                          <strong>
                            Type<sup> *</sup>
                          </strong>
                        )
                      }
                      name={attendanceType === 'PERIOD_WISE' ? 'classPeriod' : 'dayWise'}
                      onChange={(name, value) => {
                        this.handleSelectChange(attendanceType === 'PERIOD_WISE' ? 'classPeriod' : 'dayWise', value);
                      }}
                      value={attendanceType === 'PERIOD_WISE' ? classPeriod : dayWise}
                      disabled={attendanceFetchLoading || !courseStudents?.length}
                      options={attendanceType === 'PERIOD_WISE' ? classPeriodArr : attendanceTypes}
                    />
                    {attendanceType === 'PERIOD_WISE' && !classPeriodArr.length && (
                      // The timetable itself may well be set up (other days can have periods) -
                      // this is specifically about the selected date's day of week having none,
                      // so naming the day avoids reading as "you forgot to import the timetable".
                      <span style={{ color: 'orange', fontSize: 12, display: 'block', marginTop: 4 }}>
                        No periods scheduled for {moment(selectedDate).format('dddd')} in the timetable. Period wise
                        needs at least one period to select; otherwise use Day wise.
                      </span>
                    )}
                  </FormGroup>
                </div>
              </div>
            </Col>
          </Row>
          {/* Total/Present/Absent on the left, Update on the right, same row - matches the
          mobile app's layout (TeacherView.js: count tiles above the list, Update at the bottom
          right of the date card), instead of Update sharing a cramped column with the date and
          mode controls up top. */}
          {(totalCount > 0 || studentsAbsentees?.length > 0) && (
            <Row className="mt-2">
              <Col xs={12} className="d-flex justify-content-between align-items-center flex-wrap">
                <div>
                  {totalCount > 0 && (
                    <>
                      <Chip
                        size="small"
                        icon={<PeopleIcon style={{ color: colors.accent }} />}
                        label={`Total: ${totalCount}`}
                        style={{ marginRight: 8, fontWeight: 'bold', backgroundColor: `${colors.accent}1a` }}
                      />
                      <Chip
                        size="small"
                        label={`Present: ${presentCount}`}
                        style={{ marginRight: 8, fontWeight: 'bold', backgroundColor: '#43a04724', color: '#2e7d32' }}
                      />
                      <Chip
                        size="small"
                        label={`Absent: ${absentCount}`}
                        style={{ fontWeight: 'bold', backgroundColor: '#e5393524', color: '#c62828' }}
                      />
                    </>
                  )}
                </div>
                {studentsAbsentees?.length > 0 && (
                  <div>
                    {/* Temporarily disabled so web and mobile stay consistent - mobile doesn't
                      have QR-scan attendance yet. Re-enable this button once mobile's version ships.
                      <CustomButton variant="outlined" name="Scan" onClick={this.openScanDialog} /> */}
                    <CustomButton
                      onClick={this.updateAttendance}
                      disabled={
                        !selectedDate ||
                        !stateCourseId ||
                        !courseStudents.length ||
                        isAttendanceLoading ||
                        attendanceFetchLoading
                      }
                      name="Update"
                      showLoader={true}
                      loading={isAttendanceLoading}
                    />
                  </div>
                )}
              </Col>
            </Row>
          )}
        </Card>
        {attendanceFetchLoading ? (
          <LoadingCard />
        ) : !studentsAbsentees?.length ? (
          <Card>
            <CardBody>
              <div className="text-center" style={{ padding: 30 }}>
                <Row>
                  <Col xs={12} sm={12} md={12} lg={12}>
                    <CustomButton
                      className="justify-content-center align-self-center"
                      onClick={e => this.initiateAttendance(e, 'day')}
                      name={
                        moment(selectedDate).isSame(moment(), 'day')
                          ? 'Initiate attendance for today'
                          : `Initiate attendance for ${moment(selectedDate).format('DD MMM YYYY')}`
                      }
                      disabled={!selectedDate || !stateCourseId || !courseStudents?.length || isAttendanceLoading}
                      type="submit"
                      loading={isAttendanceLoading && initiateType === 'day'}
                    />
                  </Col>
                </Row>
              </div>
            </CardBody>
          </Card>
        ) : !disableAll && studentsAbsentees?.length ? (
          tableData
        ) : null}
        <CustomDraggableDialog width={500} height={window.innerHeight}>
          <QrCodeScanner toggleModal={this.openScanDialog} />
        </CustomDraggableDialog>
      </div>
    );
  }
}

export default AttendancePage;
