import React, { useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, FormGroup, Label, CustomInput, FormText } from 'reactstrap';
import { downloadSampleFile, formResMessage } from 'utils/commonFunc';
import CustomButton from '../../../../components/CustomButton';
import { employeesStatic } from '../../../../config/constants';

const ImportEmployeesModal = ({
  isImportEmployeesModalOpen,
  formModalClose,
  uploadData,
  uploadSuccess,
  scrollToTop,
  headerName,
  uploadFor,
}) => {
  const stateObj = {
    data: {
      batches: [],
      courses: [],
    },
    courseArr: [],
    formObj: {
      selectedFile: null,
      fileName: '',
    },
    errors: {},
  };
  const [stateVal, setState] = useState(stateObj);

  const fileUpload = e => {
    const file = e.currentTarget?.files?.[0];
    if (file) {
      setState(prevState => ({
        ...prevState,
        formObj: {
          ...prevState.formObj,
          selectedFile: file,
          fileName: file?.name,
        },
      }));
    }
  };

  const onSubmit = e => {
    e.preventDefault();
    const { formObj } = stateVal;
    const errors = validate(formObj);
    setState(prevState => ({ ...prevState, errors }));
    if (!Object.keys(errors).length) {
      setState(prevState => ({ ...prevState, loading: true }));
      const formData = new FormData();
      formData.append('file', formObj.selectedFile, formObj.selectedFile.name);
      return uploadData(formData)
        .then(() => {
          stateValReset();
          uploadSuccess('add');
        })
        .catch(err => setError(err));
    }
  };

  const validate = data => {
    const errors = {};
    if (!data?.fileName) {
      errors.fileName = 'File cannot be empty';
    }
    // if (validator.isEmpty(data.courseId.toString())) {
    //     errors.courseId = "Course cannot be empty";
    // }
    return errors;
  };

  const setError = err => {
    scrollToTop();
    // window.scrollTo(0, 0);
    setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  const stateValReset = () => setState(stateObj);

  const formModalCloseClick = () => {
    stateValReset();
    formModalClose();
  };

  const { errors, loading } = stateVal;
  if (document.getElementById('selectedFile') && document.getElementById('imageElement')) {
    const x = document.getElementById('selectedFile').value;
    document.getElementById('imageElement').innerHTML = x;
  }
  const closeBtn = (
    <i
      className="fas fa-times"
      style={{ fontSize: 20, color: '#000000', cursor: 'pointer' }}
      onClick={() => (!loading ? formModalCloseClick() : undefined)}
    />
  );
  const thisData = (
    <Modal isOpen={isImportEmployeesModalOpen}>
      <form onSubmit={onSubmit}>
        <ModalHeader close={closeBtn}>{headerName || `IMPORT ${employeesStatic.toUpperCase()}`}</ModalHeader>
        <ModalBody style={{ background: 'powdergrey' }}>
          {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
          <div className="row float-right mr-1">
            {downloadSampleFile(uploadFor === 'MARKS' ? 'marks' : 'employees')}
          </div>
          <FormGroup className="mt-3">
            <Label for="selectedFile">
              Select excel file <sup>*</sup>
            </Label>
            <CustomInput
              type="file"
              id="selectedFile"
              name="selectedFile"
              onChange={fileUpload}
              placeholder="Please choose excel sheet"
              accept=".xlsx, application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel"
              // onClick={() => document.getElementById('selectedFile').click()}
            />
            {errors.fileName && <span className="err-msg">{errors.fileName}</span>}
            <FormText color="muted" id="imageElement" />
          </FormGroup>
        </ModalBody>
        <ModalFooter>
          <CustomButton type="submit" disabled={loading} loading={loading} />
          <CustomButton
            className="ml-2"
            type="button"
            color="default"
            disabled={loading}
            onClick={formModalCloseClick}
            name="Cancel"
          />
        </ModalFooter>
      </form>
    </Modal>
  );

  return <div>{thisData}</div>;
};

export default ImportEmployeesModal;
