import React from 'react';
import CustomButton from 'components/CustomButton';

// "Load more" under a list of the latest items: shown while the last load filled its whole page (so there may be older ones).
const LoadMore = ({ visible, loading, onClick }) =>
  visible ? (
    <div className="text-center mt-3 mb-2">
      <CustomButton
        variant="outlined"
        name="Load more"
        loading={loading}
        disabled={loading}
        showLoader
        onClick={onClick}
      />
    </div>
  ) : null;

export default LoadMore;
