import React from 'react';
import './style.css';
import { useState } from 'react';
import { QrReader } from 'react-qr-reader';
import CustomSelect from 'components/CustomSelect';
import CustomButton from 'components/CustomButton';
import { useDispatch, useSelector } from 'react-redux';
import { showToast } from 'actions/admin/auth';
import { formResMessage, getGlobalSchoolUtils } from 'utils/commonFunc';
import { scanAndUpdateAttendanceApi } from 'actions/admin/students';

const QrCodeScanner = () => {
  const dispatch = useDispatch();
  const reduxStore = useSelector(state => state);
  const { loggedUserToken, loggedUserId, loggedUserSchool } = reduxStore?.auth || {};
  const [selected, setSelected] = useState('user');
  const [startScan, setStartScan] = useState(false);
  const [loadingScan, setLoadingScan] = useState(false);

  const handleScan = async (result, error) => {
    const { schoolId = 0 } = getGlobalSchoolUtils() || {};
    if (result?.text) {
      console.log('result', result?.text);
      try {
        setLoadingScan(true);
        await scanAndUpdateAttendanceApi({
          token: loggedUserToken,
          userId: loggedUserId,
          schoolId: loggedUserSchool || schoolId,
          qrText: result?.text,
        });
        setLoadingScan(false);
        dispatch(showToast(`Updated attendance for ${result?.text} successful`, 'success'));
        // toggleModal();
      } catch (err) {
        dispatch(showToast(formResMessage(err), 'error'));
      }
    }

    if (error) {
      console.error('handleScan-err', error);
    }
  };

  const selectOptions = [
    { label: 'Back camera', value: 'environment' },
    { label: 'Front camera', value: 'user' },
  ];

  return (
    <div className="text-center">
      <CustomButton
        name={startScan ? 'Stop Scan' : 'Start Scan for Attendance'}
        onClick={() => {
          setStartScan(!startScan);
        }}
      />
      {loadingScan && <p className="mt-2 mb-0">Update in progress... Please wait</p>}
      {startScan && (
        <div className="mt-3">
          <CustomSelect
            value={selected}
            onChange={(name, value) => setSelected(value)}
            options={selectOptions}
            noLabel
          />
          <div className="qr-code-container">
            <QrReader
              onResult={(result, error) => {
                !loadingScan && handleScan(result, error);
              }}
              constraints={{ facingMode: selected }}
            />
          </div>
        </div>
      )}
    </div>
  );
};

export default QrCodeScanner;
