import { withRouter } from 'react-router-dom';
import React, { Component } from 'react';
import { connect } from 'react-redux';
import { FormGroup, Label, Row, Col } from 'reactstrap';
import {
  saveMarkService,
  clearReducer,
  fetchStudentExamMarkService,
  fetchBatchOfExamService,
  fetchAllExamTypeService,
  saveExamTypeService,
  saveSubjectExamService,
  deleteSubExamService,
  updateExamTypeService,
} from 'actions/admin/marks';
import { fetchCourseSubjectsService } from 'actions/admin/subjects';
import MarkViewModal from './components/MarkViewModal';
