import constants, { courseStatic } from 'config/constants';
import { fetchCommonExamService } from 'actions/admin/config';
import moment from 'moment';
import colors from 'config/colors';
import SubjectExamFormModal from './components/SubjectExamFormModal';
import EditExamDatesModal from './components/EditExamDatesModal';
import EventIcon from '@material-ui/icons/Event';
