import { CommonLoader } from 'views/admin/Common/Loader';
import CustomSelect from 'components/CustomSelect';

const subTabList = [
  { tabName: `${courseStatic} exams`, index: 0 },
  { tabName: 'Student marks', index: 1 },
  { tabName: 'Marks sheet', index: 2 },
];

export const examTypes = [
  { label: 'Quarter Yearly Exam', value: 'QUART_YEARLY' },
  { label: 'Half Yearly Exam', value: 'HALF_YEARLY' },
  { label: 'Annual Exam', value: 'ANUAL_EXAM' },
  { label: 'Mid Term Test', value: 'MID_TERM' },
  { label: 'Class Test', value: 'CLASS_TEST' },
];

const initMarkData = {
  examTypeDetailId: 0,
  examSubjectDetailId: 0,
  subjectId: 0,
  mark: 0,
};

class MarksPage extends Component {
  state = {
    // The main exam whose dates are being changed (null when that dialog is closed).
    editExam: null,
    subActive: 0,
    isRefreshing: false,
    currentIndex: 0,
    studentName: '',
    batch: '',
    courseName: '',
    batchId: 0,
    studentId: 0,
    isModalOpen: false,
    isViewMarkModalOpen: false,
    // New flow
    examTypeDetailId: 0,
    examType: '',
    isTypeModalOpen: false,
    isSubjectExamModalOpen: false,
    isAddMarkModalOpen: false,
    confirmModalOpen: false,
    deleteMainExamId: 0,
    deleteSubExamId: 0,
    markData: initMarkData,
    // examSubjectDetailId whose mark is being written right now (shows a spinner in place of the check)
    markSavingId: 0,
    mainExamStartDate: '',
    mainExamEndDate: '',
    examDuration: '0',
    subjectTotalMark: 0,
    isImportMarkModalOpen: false,
    // Import marks
    mainExamId: 0,
    subjectId: 0,
    mainExamTotalMark: 0,
    // Bulk (inline, no-file) mark entry
    isBulkMarkModalOpen: false,
    bulkMarkSubjectId: 0,
    bulkMarkSubjectName: '',
    bulkMarkExamTypeDetailId: 0,
    bulkMarkTotalMark: 0,
    // loaders
    mainExamFetching: false,
    subExamFetching: false,
  };

  isLoading = (name, value) => this.setState({ [name]: value });

  fetchCommonExams = async () => {
    if (this.state.schoolId && !this.props.commonExams?.length) {
      await this.props.fetchCommonExams({
        schoolId: this.state.schoolId,
        token: this.props.loggedUserToken,
        userId: this.props.loggedUserId,
      });
    }
  };

  fetchIntialData = async (isFirstCall, refetchAgain) => {
    const { batchId } = getGlobalCurrentBatchUtils();
    if (!this.props.disableAll || refetchAgain) {
      this.fetchExamTypesAndExams(refetchAgain);
      if (this.props.courseStudents?.length) {
        const studentId = this.props.courseStudents?.[0]?.studentId || this.state.studentId;
        this.setState({ studentId });
      } else {
        const students = await this.props.fetchCourseStudents({
          courseId: this.props.courseId,
          batchId,
          token: this.props.loggedUserToken,
        });
        const studentId = students?.[0]?.studentId || this.state.studentId;
        this.setState({ studentId });
      }
      // The subjects belong to the chosen class: read again whenever the class changed, never reuse the previous class's list (the
      // Add subject exam form listed LKG subjects for a 12th std class)
      if (refetchAgain || !this.props.courseSubjects?.length) {
        this.props.fetchCourseSubjects({ courseId: this.props.courseId, token: this.props.loggedUserToken });
      }
    }
  };

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    if (globalSchool) {
      this.setState({ schoolId: globalSchool.schoolId }, () => {
        this.fetchCommonExams();
      });
    }
    this.fetchIntialData(true);
  }

  componentDidUpdate = async prevProps => {
    if (prevProps.courseId !== this.props.courseId) {
      this.fetchIntialData(false, true);
    }
  };

  showWarning = (message, type) => {
    store.dispatch(showToast(message, type));
  };

  fetchBatchExams = async (examType = this.state.examType, refetchAgain) => {
    const { batchId } = getGlobalCurrentBatchUtils();
    if (batchId && examType && (!this.props.subjectExamData?.[examType]?.length || refetchAgain)) {
      this.isLoading('subExamFetching', true);
      await this.props.fetchBatchExams({
        examType: examType || this.state.examType,
        batchId,
        token: this.props.loggedUserToken,
      });
      this.isLoading('subExamFetching', false);
    }
  };

  fetchExamTypesAndExams = async refetchAgain => {
    const { batchId } = getGlobalCurrentBatchUtils();
    this.isLoading('mainExamFetching', true);
    const resData =
      !this.props.examTypeList?.length || refetchAgain
        ? await this.props.fetchAllExamTypes({
            batchId,
            token: this.props.loggedUserToken,
          })
        : this.props.examTypeList;
    this.isLoading('mainExamFetching', false);
    if (resData?.length || refetchAgain) {
      if (!this.state.examType) {
        const examTypeList = resData?.sort((a, b) => new Date(a.startDate) - new Date(b.startDate));
        // A dashboard exam card links here with ?examId= so that exam opens instead of the first one.
        const linkedExamId = Number(new URLSearchParams(this.props.location?.search).get('examId'));
        const linkedExam = linkedExamId && examTypeList?.find(dto => dto.examTypeDetailId === linkedExamId);
        const { examTypeDetailId, examType } = linkedExam || examTypeList?.[0] || {};
        this.fetchBatchExams(examType);
        this.setState({ examTypeDetailId, examType, currentIndex: examTypeDetailId });
        if (linkedExam) {
          setTimeout(
            () => document.getElementById(`exam-type-${examTypeDetailId}`)?.scrollIntoView({ block: 'start' }),
            400
          );
        }
      } else {
        this.fetchBatchExams(this.state?.examType, true);
      }
    } else {
      this.fetchBatchExams();
    }
  };

  openContent = (examType, examTypeDetailId, index, action) => {
    if (action === 'open') {
      const { batchId } = getGlobalCurrentBatchUtils();
      this.fetchBatchExams(examType);
      if (batchId) {
        this.fetchStudentExamMark(examTypeDetailId, batchId, false, true);
      }
    }
    this.setState(prevState => ({
      ...prevState,
      examType,
      examTypeDetailId,
      currentIndex: this.state.currentIndex !== index ? index : '',
    }));
  };

  renderMarkModal = examTypeDetailId => {
    const mainExam = this.props?.examTypeList?.find(el => {
      return el?.examTypeDetailId === examTypeDetailId;
    });
    this.setState({ isViewMarkModalOpen: true, mainExamTotalMark: mainExam?.subjectTotalMark || 0 });
  };

  fetchStudentExamMark = (
    examTypeDetailId = this.state.examTypeDetailId || this.state.markData.examTypeDetailId,
    passBatchId,
    canOpenMarkViewModal,
    refetchAgain
  ) => {
    const { batchId } = getGlobalCurrentBatchUtils();
    const studentId = this.state.studentId;
    if (studentId && (!this.props.studentExamMarkList?.length || refetchAgain)) {
      return this.props
        .fetchStudentExamMark({
          examTypeDetailId,
          studentId,
          token: this.props.loggedUserToken,
          batchId: passBatchId || batchId,
        })
        .then(() => {
          canOpenMarkViewModal && this.renderMarkModal(examTypeDetailId);
        });
    } else {
      canOpenMarkViewModal && this.renderMarkModal(examTypeDetailId);
    }
  };

  goToExamSubjectPage = async (examTypeDetailId, bId) => {
    const { batchId = bId } = getGlobalCurrentBatchUtils();
    this.fetchStudentExamMark(examTypeDetailId, batchId, true);
  };

  handleSelectChange = async studentId => {
    this.setState({ ...this.state, studentId }, () => {
      this.fetchExamTypesAndExams();
      this.fetchStudentExamMark(undefined, undefined, false, true);
    });
  };

  getSelectStudent = studentId => {
    const existItem = this.props.courseStudents?.find(item => item.studentId === studentId);
    if (existItem) {
      return {
        value: existItem.studentId,
        label: `${existItem.firstName} ${existItem.lastName}`,
      };
    }
    return null;
  };

  formModalOpen = (name, passParams = null) => {
    this.setState(prevState => ({
      ...prevState,
      [name]: true,
      ...(passParams && passParams),
    }));
  };

  formModalClose = () => {
    this.setState({
      isModalOpen: false,
      isViewMarkModalOpen: false,
      isTypeModalOpen: false,
      isSubjectExamModalOpen: false,
      isAddMarkModalOpen: false,
      confirmModalOpen: false,
      deleteMainExamId: 0,
      deleteSubExamId: 0,
      mainExamStartDate: '',
      mainExamEndDate: '',
      examDuration: 0,
      subjectTotalMark: 0,
      isImportMarkModalOpen: false,
      // Import marks
      mainExamId: 0,
      subjectId: 0,
      mainExamTotalMark: 0,
      // Bulk (inline, no-file) mark entry
      isBulkMarkModalOpen: false,
      bulkMarkSubjectId: 0,
      bulkMarkSubjectName: '',
      bulkMarkExamTypeDetailId: 0,
      bulkMarkTotalMark: 0,
    });
  };

  handleMarkChange = (examTypeDetailId, examSubjectDetailId, subjectId, mark) => {
    this.setState(prevState => ({
      ...prevState,
      markData: {
        examTypeDetailId,
        examSubjectDetailId,
        subjectId,
        mark,
      },
    }));
  };

  // Marks with a progReportId already exist server-side, so re-saving one must go through
  // PUT with that id (an update) rather than POST (which would create a duplicate row and
  // collide with the one-mark-per-subject-exam constraint).
  // `explicit` is the check button: it always answers (saved, nothing changed, or why not), and a subject with no mark yet saves
  // the 0 the box shows. Leaving the box (blur) saves only a mark the teacher actually changed, quietly apart from the result.
  saveStudentMark = (markVal, item, examTypeDetailId, explicit = false) => {
    // Clicking the check blurs the box first: both would write the same mark, the second one failing as a duplicate.
    if (this.markSaving) {
      return undefined;
    }
    const { markData } = this.state;
    const edited = markData.examSubjectDetailId === item.examSubjectDetailId;
    const saved = !!markVal?.progReportId;
    const mark = edited ? `${markData.mark}` : saved ? `${markVal.studentMark}` : '0';
    if (edited && mark === '') {
      explicit && this.showWarning('Enter a mark first', 'warning');
      return undefined;
    }
    const unchanged = saved && mark === `${markVal.studentMark}`;
    if (unchanged || (!edited && !saved && !explicit)) {
      explicit && this.showWarning('No change to save. Change the mark first.', 'warning');
      return undefined;
    }
    return this.updateStudentMark(
      saved ? { action: 'put', pId: markVal.progReportId } : { action: 'post', pId: null },
      { examTypeDetailId, item, mark }
    );
  };

  updateStudentMark = (actionObj, { examTypeDetailId, item, mark }) => {
    const subjectId = item.subject?.subjectId;
    const { batchId = this.props.currentBatch.batchId } = getGlobalCurrentBatchUtils();
    if (!(examTypeDetailId && subjectId && this.state.studentId && batchId)) {
      this.showWarning('Choose the student and exam first', 'warning');
      return undefined;
    }
    const postData = {
      examTypeDetails: { examTypeDetailId },
      subject: { subjectId },
      studentMark: mark,
      student: {
        studentId: this.state.studentId,
      },
      batchId,
    };
    this.markSaving = true;
    this.setState({ markSavingId: item.examSubjectDetailId });
    return this.props
      .saveMark({
        postData,
        ...(actionObj?.pId && actionObj?.action === 'put' && { progReportId: actionObj?.pId }),
        token: this.props.loggedUserToken,
      })
      .then(() => {
        this.showWarning(`${item.subject?.name} mark saved`, 'success');
        this.setState(prevState => ({ ...prevState, markData: initMarkData }));
        return this.fetchStudentExamMark(examTypeDetailId, batchId, false, true);
      })
      .catch(err => {
        this.showWarning(formResMessage(err), 'error');
      })
      .finally(() => {
        this.markSaving = false;
        this.setState({ markSavingId: 0 });
      });
  };

  markUpdateSuccess = actionParam => {
    this.setState({ isModalOpen: false });
    this.showWarning(actionParam === 'add' ? 'Mark added successfully' : 'Mark Updated successfully', 'success');
    this.fetchExamTypesAndExams();
    const { batchId } = getGlobalCurrentBatchUtils();
    if (batchId && this.state.examTypeDetailId && !this.props.studentExamMarkList?.length) {
      this.fetchStudentExamMark(this.state.examTypeDetailId, batchId);
    }
  };

  handleSubTabChange = tab => {
    if (tab !== this.state.subActive) {
      this.setState(prevState => ({ ...prevState, subActive: tab }));
      if (tab === 0 || tab === 2) {
        this.fetchExamTypesAndExams();
      } else {
        const { batchId } = getGlobalCurrentBatchUtils();
        if (batchId && this.state.examTypeDetailId && !this.props.studentExamMarkList?.length) {
          this.fetchStudentExamMark(this.state.examTypeDetailId, batchId);
        }
      }
    }
  };

  saveExamType = data => {
    const { batchId } = getGlobalCurrentBatchUtils();
    if (batchId && this.props.courseId) {
      data = {
        ...data,
        createdUser: {
          id:
            this.props.loggedUserRole === constants.roles.teacher ? this.props.loggedUserId : this.props.propEmployeeId,
        },
        school: { schoolId: this.state.schoolId },
        course: { courseId: this.props.courseId },
        batch: { batchId: batchId || this.props.currentBatch.batchId },
      };
      return this.props.saveExamType({ postData: data, token: this.props.loggedUserToken });
    } else {
      this.showWarning(`Batch or ${courseStatic} is not valid, Please check and try again`, 'error');
    }
  };

  // Opens the "Edit exam dates" dialog for a main exam (from its own button, or from the subject exam dialog).
  openEditExamDates = exam => {
    this.formModalClose();
    this.setState({ editExam: exam });
  };

  closeEditExamDates = () => this.setState({ editExam: null });

  saveExamDates = async ({ startDate, endDate }) => {
    const { editExam } = this.state;
    const { batchId } = getGlobalCurrentBatchUtils();
    await this.props.updateExamType({
      examTypeDetailId: editExam.examTypeDetailId,
      postData: {
        ...editExam,
        startDate,
        endDate,
        school: editExam.school?.schoolId ? editExam.school : { schoolId: this.state.schoolId },
        batch: editExam.batch?.batchId ? editExam.batch : { batchId: batchId || this.props.currentBatch?.batchId },
      },
      token: this.props.loggedUserToken,
    });
    this.setState({ editExam: null });
    this.showWarning('Exam dates updated', 'success');
    this.fetchExamTypesAndExams(true);
  };

  examUpdateSuccess = actionParam => {
    this.formModalClose();
    this.showWarning(actionParam === 'add' ? 'Exam added successfully' : 'Exam Updated successfully', 'success');
    this.fetchExamTypesAndExams(true);
  };

  saveSubjectExam = data => {
    // const { batchId } = getGlobalCurrentBatchUtils();
    if (this.props.courseId && this.state.examTypeDetailId) {
      data = {
        ...data,
        // createdUser: {
        //   id:
        //     this.props.loggedUserRole === constants.roles.teacher ? this.props.loggedUserId : this.props.propEmployeeId,
        // },
        // school: { schoolId: this.state.schoolId },
        course: { courseId: this.props.courseId },
        // batch: { batchId: batchId || this.props.currentBatch.batchId },
        examTypeDetail: {
          examTypeDetailId: this.state.examTypeDetailId,
        },
      };
      return this.props.saveSubjectExam({ postData: data, token: this.props.loggedUserToken });
    } else {
      this.showWarning(`Batch or ${courseStatic} is not valid, Please check and try again`, 'error');
    }
  };

  deleteCancel = () => this.formModalClose();

  deleteSubjectExam = (deleteMainExamId, deleteSubExamId) => {
    this.setState(prevState => ({
      ...prevState,
      confirmModalOpen: true,
      confirmMessage: 'Are you sure you want to delete exam ?',
      deleteMainExamId,
      deleteSubExamId: deleteSubExamId || 0,
    }));
  };

  deleteConfirm = () => {
    this.props
      .deleteSubExam({
        deleteMainExamId: this.state.deleteMainExamId,
        examSubjectDetailId: this.state.deleteSubExamId,
        token: this.props.loggedUserToken,
      })
      .then(() => {
        this.fetchExamTypesAndExams(true);
        this.deleteCancel();
      })
      .catch(err => {
        this.showWarning(formResMessage(err), 'error');
        this.deleteCancel();
      });
  };

  uploadMarksData = formData => {
    const { batchId } = getGlobalCurrentBatchUtils();
    const postData = {
      schoolId: this.state.schoolId,
      batchId,
      subjectId: this.state.subjectId,
      examTypeDetailId: this.state.mainExamId,
      formData,
      token: this.props.loggedUserToken,
      uploadType: 'studentsMark',
    };
    if (
      postData.schoolId &&
      postData.batchId &&
      postData.subjectId &&
      postData.examTypeDetailId &&
      postData.formData &&
      postData.token
    ) {
      return this.props.uploadMarksData(postData);
    }
  };

  uploadSuccess = () => {
    this.formModalClose();
    this.showWarning(`Students marks uploaded successfully`, 'success');
  };

  render() {
    const {
      subActive,
      currentIndex,
      studentId,
      isViewMarkModalOpen,
      // New
      isTypeModalOpen,
      isSubjectExamModalOpen,
      examType,
      examTypeDetailId,
      confirmModalOpen,
      confirmMessage,
      markData,
      mainExamStartDate,
      mainExamEndDate,
      examDuration,
      subjectTotalMark,
      isImportMarkModalOpen,
      mainExamTotalMark,
      mainExamFetching,
      subExamFetching,
      isBulkMarkModalOpen,
      bulkMarkSubjectId,
      bulkMarkSubjectName,
      bulkMarkExamTypeDetailId,
      bulkMarkTotalMark,
    } = this.state;
    const {
      disableAll: isDisable,
      courseId,
      // myBatchList,
      subjectExamData,
      courseStudents,
      courseSubjects,
      studentExamMarkList,
      // propEmployeeId,
      commonExams,
      examTypeList,
    } = this.props;
    const disableAll = isDisable || !this.props.courseStudents?.length;
    // Three looks, all soft: 'header' chips are a light tint on the header, 'status' is a tinted tag in the status colour,
    // 'content' chips are white and outlined on the light panel.
    const chip = (icon, text, variant = 'content', color) => {
      const look = {
        header: {
          background: 'rgba(255,255,255,0.7)',
          color: colors.accentDark,
          border: `1px solid ${colors.accent}22`,
        },
        status: {
          background: `${color || colors.accent}1a`,
          color: color || colors.accent,
          border: `1px solid ${color || colors.accent}33`,
          fontWeight: 'bold',
        },
        content: { background: '#fff', color: colors.accentDark, border: `1px solid ${colors.accent}33` },
      }[variant];
      return (
        <span
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 5,
            fontSize: 12,
            padding: '2px 10px',
            borderRadius: 12,
            whiteSpace: 'nowrap',
            ...look,
          }}>
          {icon}
          {text}
        </span>
      );
    };
    const today = moment().format('YYYY-MM-DD');
    // Where the main exam stands: upcoming, running now, or over (by its own start and end dates).
    const examStatus = exam => {
      const start = moment(new Date(exam.startDate)).format('YYYY-MM-DD');
      const end = moment(new Date(exam.endDate)).format('YYYY-MM-DD');
      if (start > today) return { label: 'Upcoming', color: '#e65100' };
      if (end < today) return { label: 'Completed', color: '#2e7d32' };
      return { label: 'Ongoing', color: colors.accent };
    };
    const dangerStyle = { color: '#c62828', borderColor: '#c62828' };
    const primaryStyle = { backgroundColor: colors.accent, color: colors.white };

    const emptyListDiv = (
      <div style={{ textAlign: 'center', padding: '16px 12px 22px', color: colors.grey2 }}>
        <b>No subject exams yet.</b>
        <div style={{ fontSize: 12, marginTop: 4 }}>
          {subActive === 0
            ? 'Use "Add subject exam" to schedule the first one.'
            : 'Subject exams will show here once added.'}
        </div>
      </div>
    );

    const getRenderedContentDiv = (
      examTypeId,
      mainExamStartDate,
      examDuration = 3,
      mainExamSubjectTotalMark,
      examType
    ) => {
      return subjectExamData?.[examType]?.length
        ? subjectExamData?.[examType]
            ?.sort((a, b) => new Date(a.examDate) - new Date(b.examDate))
            ?.map(item => {
              const duration = moment(examDuration, ['h:mm A']).format('HH:mm');
              const markVal = studentExamMarkList?.find(el => el.subject?.subjectId === item.subject?.subjectId) || '';
              const stateMarkVal =
                markData?.examSubjectDetailId === item?.examSubjectDetailId ? markData?.mark : undefined;
              const isExamStarted =
                moment(new Date(item.examDate)).format('YYYY-MM-DD') < moment(new Date()).format('YYYY-MM-DD');
              const mainStarted = moment(new Date(mainExamStartDate)).format('YYYY-MM-DD') < today;
              const mainNotStarted = moment(new Date(mainExamStartDate)).format('YYYY-MM-DD') > today;
              const startMoment = moment(`${moment(item.examDate).format('YYYY-MM-DD')}T${item.examStartTime}`);
              return (
                <div
                  key={item.examSubjectDetailId}
                  style={{
                    display: 'flex',
                    flexWrap: 'wrap',
                    alignItems: 'center',
                    gap: 12,
                    padding: '12px 14px',
                    margin: '0 12px 10px',
                    background: '#fff',
                    border: '1px solid #E2D3EE',
                    borderLeft: `4px solid ${colors.accent}`,
                    borderRadius: 8,
                  }}>
                  <div style={{ flex: '1 1 260px', minWidth: 0 }}>
                    <div style={{ fontWeight: 'bold', fontSize: 15, color: colors.accentDark }}>
                      {item.subject?.name}
                    </div>
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginTop: 6 }}>
                      {chip(<EventIcon style={{ fontSize: 15 }} />, moment(item.examDate).format('DD MMM YYYY'))}
                      {chip(
                        <ScheduleIcon style={{ fontSize: 15 }} />,
                        `${startMoment.format('LT')} - ${startMoment.clone().add(duration, 'hours').format('LT')}`
                      )}
                      {chip(null, `Hall: ${item.examHallName} (${item.examHallCode})`)}
                      {chip(null, `Marks: ${mainExamSubjectTotalMark || '-'}`)}
                    </div>
                  </div>
                  <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 8 }}>
                    {subActive === 1 && isExamStarted && (
                      <>
                        <TextField
                          type="number"
                          label="Student Mark"
                          id="standard-size-small"
                          value={
                            stateMarkVal !== undefined
                              ? stateMarkVal
                              : markVal?.progReportId
                              ? markVal?.studentMark
                              : '0'
                          }
                          size="small"
                          onChange={e => {
                            const value = e.target.value;
                            if (value <= Number(mainExamSubjectTotalMark)) {
                              this.handleMarkChange(
                                examTypeId,
                                item.examSubjectDetailId,
                                item.subject?.subjectId,
                                e.target.value
                              );
                            } else {
                              this.showWarning(
                                `Subject mark cannot be more than ${mainExamSubjectTotalMark}`,
                                'warning'
                              );
                            }
                          }}
                          onBlur={() => this.saveStudentMark(markVal, item, examTypeId)}
                          disabled={!isExamStarted || this.state.markSavingId === item.examSubjectDetailId}
                        />
                        {/* The mark actually saves on the field's onBlur, but this checkmark renders with
                        a pointer cursor right next to it - without a handler it looks like a "confirm
                        the mark" button that silently does nothing when clicked, which a non-technical
                        teacher would reasonably expect to work. Wiring it to the same save call makes
                        the visible affordance actually do what it looks like it does. */}
                        {this.state.markSavingId === item.examSubjectDetailId ? (
                          <CircularProgress size={20} style={{ color: 'green' }} />
                        ) : (
                          <CheckIcon
                            titleAccess="Save mark"
                            style={{ color: 'green', cursor: 'pointer' }}
                            onClick={() => this.saveStudentMark(markVal, item, examTypeId, true)}
                          />
                        )}
                      </>
                    )}
                    {subActive === 0 && mainStarted && (
                      <>
                        <CustomButton
                          size="small"
                          name="Enter marks"
                          style={primaryStyle}
                          onClick={() =>
                            this.formModalOpen('isBulkMarkModalOpen', {
                              bulkMarkSubjectId: item.subject?.subjectId,
                              bulkMarkSubjectName: item.subject?.name,
                              bulkMarkExamTypeDetailId: examTypeId,
                              bulkMarkTotalMark: mainExamSubjectTotalMark,
                            })
                          }
                        />
                        <CustomButton
                          size="small"
                          variant="outlined"
                          name="Import marks"
                          onClick={() =>
                            this.formModalOpen('isImportMarkModalOpen', {
                              examType: examType,
                              mainExamId: examTypeId,
                              subjectId: item.subject?.subjectId,
                            })
                          }
                        />
                      </>
                    )}
                    {subActive === 0 && mainNotStarted && (
                      <CustomButton
                        size="small"
                        variant="outlined"
                        name="Delete exam"
                        style={dangerStyle}
                        onClick={() => this.deleteSubjectExam(examTypeId, item.examSubjectDetailId)}
                      />
                    )}
                  </div>
                </div>
              );
            })
        : emptyListDiv;
    };

    const examTypesDiv =
      examTypeList?.length > 0 &&
      examTypeList
        ?.sort((a, b) => new Date(a.startDate) - new Date(b.startDate))
        ?.map(item => {
          const index = item.examTypeDetailId;
          const isOpen = currentIndex === index;
          const status = examStatus(item);
          const toggle = () => this.openContent(item.examType, item.examTypeDetailId, index, isOpen ? 'close' : 'open');
          return (
            <div
              key={item.examTypeDetailId}
              id={`exam-type-${item.examTypeDetailId}`}
              style={{
                background: '#fff',
                border: `1px solid ${colors.accent}2e`,
                borderLeft: `4px solid ${colors.accent}`,
                borderRadius: 10,
                marginBottom: 16,
                overflow: 'hidden',
                boxShadow: isOpen ? '0 3px 12px rgba(123,31,162,0.10)' : '0 1px 3px rgba(0,0,0,0.06)',
              }}>
              <div
                role="button"
                tabIndex={0}
                onClick={toggle}
                onKeyDown={e => (e.key === 'Enter' || e.key === ' ') && toggle()}
                style={{
                  display: 'flex',
                  flexWrap: 'wrap',
                  alignItems: 'center',
                  gap: 10,
                  padding: '14px 16px',
                  cursor: 'pointer',
                  background: colors.sidebarActiveItemBg,
                  color: colors.accentDark,
                }}>
                <div style={{ flex: '1 1 260px', minWidth: 0 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
                    <span style={{ fontWeight: 'bold', fontSize: 17, color: colors.accentDark }}>{item.examTitle}</span>
                    {chip(null, status.label, 'status', status.color)}
                  </div>
                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginTop: 8 }}>
                    {chip(
                      <EventIcon style={{ fontSize: 15 }} />,
                      `${moment(item.startDate).format('DD MMM YYYY')} - ${moment(item.endDate).format('DD MMM YYYY')}`,
                      'header'
                    )}
                    {!!item.subjectTotalMark && chip(null, `Marks per subject: ${item.subjectTotalMark}`, 'header')}
                    {!!item.examDuration &&
                      chip(<ScheduleIcon style={{ fontSize: 15 }} />, `Duration: ${item.examDuration}`, 'header')}
                  </div>
                </div>
                <span style={{ color: colors.accent, display: 'flex' }}>
                  {isOpen ? <ExpandLessIcon /> : <KeyboardArrowDownIcon />}
                </span>
              </div>
              {isOpen && (
                <>
                  {(subActive === 0 || (subActive === 1 && subjectExamData?.[item.examType]?.length > 0)) && (
                    <div
                      style={{
                        display: 'flex',
                        flexWrap: 'wrap',
                        gap: 8,
                        padding: '10px 16px',
                        background: '#F7F2FB',
                        borderTop: `1px solid ${colors.accent}1a`,
                        borderBottom: `1px solid ${colors.accent}1a`,
                      }}>
                      {subActive === 0 && (
                        <>
                          <CustomButton
                            size="small"
                            name="Add subject exam"
                            style={primaryStyle}
                            onClick={() =>
                              this.formModalOpen('isSubjectExamModalOpen', {
                                examType: item.examType,
                                mainExamStartDate: item.startDate,
                                mainExamEndDate: item.endDate,
                                examDuration: item.examDuration,
                                subjectTotalMark: item.subjectTotalMark,
                              })
                            }
                          />
                          <CustomButton
                            size="small"
                            variant="outlined"
                            name="Edit exam dates"
                            onClick={() => this.openEditExamDates(item)}
                          />
                          {!subjectExamData?.[item.examType]?.length &&
                            moment(new Date(item.startDate)).format('YYYY-MM-DD') > today && (
                              <CustomButton
                                size="small"
                                variant="outlined"
                                name="Delete main exam"
                                style={dangerStyle}
                                onClick={() => this.deleteSubjectExam(item.examTypeDetailId)}
                              />
                            )}
                        </>
                      )}
                      {subActive === 1 && subjectExamData?.[item.examType]?.length > 0 && (
                        <CustomButton
                          size="small"
                          name="View student marks list"
                          style={primaryStyle}
                          onClick={() => this.goToExamSubjectPage(item.examTypeDetailId)}
                        />
                      )}
                    </div>
                  )}
                  {subExamFetching ? (
                    <div style={{ textAlign: 'center', padding: 10, background: '#FCFAFD' }}>
                      <CommonLoader />
                    </div>
                  ) : (
                    <div style={{ background: '#FCFAFD', padding: '12px 0 2px' }}>
                      {getRenderedContentDiv(
                        item.examTypeDetailId,
                        item.startDate,
                        item.examDuration,
                        item.subjectTotalMark,
                        item.examType
                      )}
                    </div>
                  )}
                </>
              )}
            </div>
          );
        });

    const emptyDiv = (
      <div
        style={{
          textAlign: 'center',
          padding: '34px 16px',
          background: '#fff',
          border: '1.5px dashed #EADCF7',
          borderRadius: 10,
        }}>
        <b style={{ color: colors.accentDark }}>No exams yet</b>
        <div style={{ fontSize: 13, color: colors.grey2, marginTop: 4 }}>
          {subActive === 0
            ? 'Use "Add Main Exam" to set up the first exam of this class.'
            : 'Exams show here once they are added.'}
        </div>
      </div>
    );

    const courseStudentDiv = subActive === 1 && (
      <FormGroup>
        <Label htmlFor="">
          <strong>
            Student<sup> *</sup>
          </strong>
          {!studentId && <span style={{ color: 'orange' }}> [Select student to view the marks]</span>}
        </Label>
        <CustomSelect
          noLabel={true}
          name="studentId"
          onChange={(name, value) => this.handleSelectChange(value)}
          options={formStudentSelectList(courseStudents)}
          value={studentId}
          applyLabelStyle={true}
        />
      </FormGroup>
    );

    return (
      <div className="content">
        <SubTabs
          className="mb-3"
          subTabs={subTabList}
          subActive={subActive}
          tabToggle={tab => this.handleSubTabChange(tab)}
        />
        {subActive === 2 ? (
          mainExamFetching ? (
            <LoadingCard />
          ) : (
            <MarksSheet
              courseStudents={courseStudents}
              examTypeList={examTypeList}
              subjectExamData={subjectExamData}
              courseId={courseId}
              onLoadExam={examTypeName => this.fetchBatchExams(examTypeName)}
              batchId={getGlobalCurrentBatchUtils().batchId}
              token={this.props.loggedUserToken}
              saveMark={this.props.saveMark}
              showWarning={this.showWarning}
            />
          )
        ) : (
          <>
            <Row>
              <Col sm={6} md={6}>
                {courseStudentDiv}
              </Col>
              <Col sm={6} md={6}>
                {subActive === 0 && (
                  <CustomButton
                    style={{ float: 'right', marginBottom: 5 }}
                    onClick={() => this.formModalOpen('isTypeModalOpen')}
                    disabled={!courseId}
                    name="Add Main Exam"
                  />
                )}
              </Col>
            </Row>
            <div>
              {mainExamFetching ? (
                <LoadingCard />
              ) : (
                <div>{examTypeList?.length > 0 && !disableAll ? examTypesDiv : emptyDiv}</div>
              )}
            </div>
          </>
        )}
        <ExamTypeFormModal
          isModalOpen={isTypeModalOpen}
          commonExams={commonExams}
          formModalCloseProp={this.formModalClose}
          saveExamType={this.saveExamType}
          exam={{}}
          updateExam={this.updateExam}
          examUpdateSuccess={this.examUpdateSuccess}
          examTypeList={examTypeList}
          examType={examType}
        />
        <SubjectExamFormModal
          isSubjectExamModalOpen={isSubjectExamModalOpen}
          saveSubjectExam={this.saveSubjectExam}
          updateExam={this.updateExam}
          examUpdateSuccess={this.examUpdateSuccess}
          formModalCloseProp={this.formModalClose}
          courseSubjects={courseSubjects}
          examType={examType}
          examTypeDetailId={examTypeDetailId}
          mainExamStartDate={mainExamStartDate}
          mainExamEndDate={mainExamEndDate}
          onEditMainExam={() => this.openEditExamDates(examTypeList.find(exam => exam.examType === examType))}
          subjectExamData={subjectExamData}
          examDuration={examDuration}
          subjectTotalMark={subjectTotalMark}
        />
        <EditExamDatesModal
          isOpen={!!this.state.editExam}
          exam={this.state.editExam}
          subjectExams={this.state.editExam ? subjectExamData?.[this.state.editExam.examType] || [] : []}
          otherExams={(examTypeList || []).filter(
            exam => exam.examTypeDetailId !== this.state.editExam?.examTypeDetailId
          )}
          onClose={this.closeEditExamDates}
          onSave={this.saveExamDates}
        />
        <MarkViewModal
          courseStudentDiv={courseStudentDiv}
          isViewMarkModalOpen={isViewMarkModalOpen}
          studentExamMarkList={studentExamMarkList}
          formModalClose={this.formModalClose}
          mainExamTotalMark={mainExamTotalMark}
          subjectExams={subjectExamData?.[this.state.examType] || []}
          examTypeDetailId={this.state.examTypeDetailId}
          studentId={studentId}
          batchId={getGlobalCurrentBatchUtils().batchId}
          token={this.props.loggedUserToken}
          saveMark={this.props.saveMark}
          showWarning={this.showWarning}
          onSaved={() =>
            this.fetchStudentExamMark(this.state.examTypeDetailId, getGlobalCurrentBatchUtils().batchId, false, true)
          }
        />
        <ConfirmModal
          confirmModalOpen={confirmModalOpen}
          deleteConfirm={this.deleteConfirm}
          deleteCancel={this.deleteCancel}
          confirmMessage={confirmMessage}
        />
        <ImportMarksModal // Import mark modal alias
          isImportEmployeesModalOpen={isImportMarkModalOpen}
          formModalClose={this.formModalClose}
          // batchCourses={courses}
          uploadData={this.uploadMarksData}
          uploadSuccess={this.uploadSuccess}
          scrollToTop={() => window.scrollTo(0, 0)}
          headerName="IMPORT CLASS STUDENTS MARK"
          uploadFor="MARKS"
        />
        <BulkMarkEntryModal
          isOpen={isBulkMarkModalOpen}
          formModalClose={this.formModalClose}
          courseStudents={courseStudents}
          subjectId={bulkMarkSubjectId}
          subjectName={bulkMarkSubjectName}
          examTypeDetailId={bulkMarkExamTypeDetailId}
          totalMark={bulkMarkTotalMark}
          batchId={getGlobalCurrentBatchUtils().batchId}
          token={this.props.loggedUserToken}
          saveMark={this.props.saveMark}
          showWarning={this.showWarning}
          onSaved={() => this.fetchBatchExams(this.state.examType, true)}
        />
      </div>
    );
  }
}

const mapStateToProps = state => {
  const loggedUserId = state.auth.loggedUserId ? state.auth.loggedUserId : 0;
  const loggedUserToken = state.auth.loggedUserToken ? state.auth.loggedUserToken : {};
  const loggedUserRole = state.auth.loggedUserRole ? state.auth.loggedUserRole : '';
  const myBatchList = state.marks.myBatchList ? state.marks.myBatchList : [];
  const courses = state.courses.courseList ? state.courses.courseList : [];
  const courseSubjects = state.subjects.courseSubjects || [];
  const studentExamMarkList = state.marks.studentExamMarkList || [];
  const batchExamList = state.marks.batchExamList || [];
  const subjectExamData = state.marks.batchCourseExam || {};
  const commonExams = state.config.commonExams || [];
  const examTypeList = state.marks.examTypeList || [];
  const currentBatch = state.batches.currentBatch;
  return {
    loggedUserId,
    loggedUserToken,
    loggedUserRole,
    courses,
    myBatchList,
    subjectExamData,
    courseSubjects,
    studentExamMarkList,
    batchExamList,
    commonExams,
    examTypeList,
    currentBatch,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchBatchExams: data => dispatch(fetchBatchOfExamService(data)),
    fetchCourseSubjects: data => dispatch(fetchCourseSubjectsService(data)),
    saveMark: data => dispatch(saveMarkService(data)),
    clearReducer: () => dispatch(clearReducer()),
    fetchStudentExamMark: data => dispatch(fetchStudentExamMarkService(data)),
    // New exam flow
    fetchCommonExams: data => dispatch(fetchCommonExamService(data)),
    fetchAllExamTypes: data => dispatch(fetchAllExamTypeService(data)),
    saveExamType: data => dispatch(saveExamTypeService(data)),
    updateExamType: data => dispatch(updateExamTypeService(data)),
    saveSubjectExam: data => dispatch(saveSubjectExamService(data)),
    deleteSubExam: data => dispatch(deleteSubExamService(data)),
    // Upload
    uploadMarksData: data => dispatch(uploadDataService(data)),
    // Students
    fetchCourseStudents: data => dispatch(fetchSchoolCourseStudentsService(data)),
  };
};

export default withRouter(connect(mapStateToProps, mapDispatchToProps)(MarksPage));
