import React from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter } from 'reactstrap';
import CustomButton from '../../../../../components/CustomButton';
import EmptyState from 'views/admin/Common/EmptyState';

class StudentsStatusViewModal extends React.PureComponent {
  render() {
    const { isStatusModalOpen, formModalClose, studentsHomeWorkStatusList: taskList } = this.props;
    const thisData = (
      <Modal size="lg" isOpen={isStatusModalOpen}>
        <form onSubmit={this.handleSubmit}>
          <ModalHeader>STUDENTS HOMEWORK STATUS</ModalHeader>
          <ModalBody>
            <div className="content">
              <div className="container-fluid">
                {taskList?.length > 0 && (
                  <div className="text-center">
                    <h6>
                      {`${taskList[0]?.subject?.name} (${taskList[0]?.subject?.course?.name || ''})${
                        taskList[0]?.timePeriod ? ` - ${taskList[0].timePeriod}` : ''
                      }`}
                    </h6>
                    <p>{taskList[0].taskName}</p>
                  </div>
                )}
                <table className="table table-bordered">
                  <thead>
                    <th>#</th>
                    <th>Student</th>
                    <th>Status</th>
                  </thead>
                  <tbody>
                    {taskList?.length > 0 ? (
                      taskList.map(item => {
                        return (
                          <tr key={item.studOrEmpTaskSeqId}>
                            <td>{item.studOrEmpTaskSeqId}</td>
                            <td>{`${item.firstName} ${item.lastName}`}</td>
                            <td>{item.status}</td>
                          </tr>
                        );
                      })
                    ) : (
                      <tr>
                        <td colSpan={3}>
                          <EmptyState compact bare icon="fas fa-user-graduate" title="No students found" />
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </ModalBody>
          <ModalFooter>
            <CustomButton type="button" color="default" onClick={formModalClose} name="Close" />
          </ModalFooter>
        </form>
      </Modal>
    );
    return <div>{thisData}</div>;
  }
}

export default StudentsStatusViewModal;
