import React from 'react';
import { connect } from 'react-redux';
import { Row, Col } from 'reactstrap';
import moment from 'moment';
// import DatePicker from 'views/admin/Common/Datepicker';
import { meetingTableHead } from 'variables/general';

import {
  fetchAllMeetingsService,
  saveMeetingService,
  fetchMeetingService,
  updateMeetingService,
  deleteMeetingService,
} from 'actions/admin/students';
import MeetingFormModal from './components/MeetingFormModal.jsx';
// import constants from '../../../../config/constants.js';
import { store } from '../../../../index.js';
import { showToast } from '../../../../actions/admin/auth.js';
import { formResMessage, getGlobalCurrentBatchUtils } from '../../../../utils/commonFunc.js';
import CustomButton from '../../../../components/CustomButton.jsx';
import MuiTable from 'views/admin/Common/MuiTable.jsx';
import { getSelecDateTime } from './components/MeetingFormModal.jsx';
import ListDropDown from 'views/admin/Common/ListDropDown.jsx';
import colors from 'config/colors.js';
import { passActiveTabAndCourseId } from '../EmployeeActivityPage.jsx';
import { LoadingCard } from 'views/admin/Common/Loader.jsx';

class MeetingPage extends React.Component {
  constructor() {
    super();
    this.state = {
      selectedDate: new Date(),
      showAlert: false,
      message: '',
      alertType: '',
      isModalOpen: false,
      confirmModalOpen: false,
      isStatusModalOpen: false,
      pageParams: {
        page: 1,
        size: 10,
      },
      // loader
      meetingFetching: false,
    };
  }

  componentDidMount() {
    const { visitedCourseIds, activeTab, courseId } = this.props;
    if (courseId && visitedCourseIds?.[activeTab] !== courseId) {
      passActiveTabAndCourseId(activeTab, courseId);
      this.fetchMeetingsData(true);
    } else {
      this.fetchMeetingsData();
    }
  }

  componentDidUpdate(prevProps) {
    const { activeTab, courseId } = this.props;
    if (prevProps.courseId !== courseId) {
      courseId && passActiveTabAndCourseId(activeTab, courseId);
      this.fetchMeetingsData(true);
    }
  }

  showWarning = (message, type) => {
    this.setState({ confirmModalOpen: false });
    store.dispatch(showToast(message, type));
  };

  isLoading = (name, value) => {
    this.setState({ [name]: value });
  };

  fetchMeetingsData = async refetchAgain => {
    const { batchId } = getGlobalCurrentBatchUtils();
    const { disableAll, courseId, loggedUserToken: token, meetingsData } = this.props;
    if (!disableAll && batchId && courseId && (!meetingsData?.content?.length || refetchAgain)) {
      this.isLoading('meetingFetching', true);
      await this.props.fetchMeetingsData({
        batchId,
        courseId,
        token,
        pageParams: this.state.pageParams,
      });
      this.isLoading('meetingFetching', false);
    }
  };

  // Meeting section ///
  formModalOpen = () => {
    // if(moment(this.state.selectedDate).format('YYYY-MM-DD') <= moment(new Date()).format('YYYY-MM-DD')){
    //   alert('Cant')
    // } else {
    this.setState({ isModalOpen: true });
    // }
  };

  formModalClose = () => {
    this.setState({
      isModalOpen: false,
      confirmModalOpen: false,
      isStatusModalOpen: false,
    });
  };

  saveMeeting = data => {
    const { batchId } = getGlobalCurrentBatchUtils();
    const { courseId } = this.props;
    if (batchId && courseId) {
      const postData = {
        ...data,
        batchId,
        courseId,
      };
      return this.props.saveMeeting({
        postData,
        token: this.props.loggedUserToken,
      });
    }
    this.showWarning('Current batch is not valid, Please check batch module', 'warning');
  };

  getMeeting = meetingId => {
    this.props
      .fetchMeeting({
        meetingId,
        token: this.props.loggedUserToken,
      })
      .then(() => {
        this.formModalOpen();
      });
  };

  updateMeeting = data => {
    const { batchId } = getGlobalCurrentBatchUtils();
    const { courseId } = this.props;
    if (batchId && courseId) {
      const postData = {
        ...data,
        batchId,
        courseId,
      };
      return this.props.updateMeeting({
        postData,
        meetingId: postData?.meetingId,
        token: this.props.loggedUserToken,
      });
    }
    this.showWarning('Current batch is not valid, Please check batch module', 'warning');
  };

  meetingUpdateSuccess = actionParam => {
    this.setState({ isModalOpen: false });
    this.showWarning(actionParam === 'add' ? 'Meeting added successfully' : 'Meeting Updated successfully', 'success');
    this.fetchMeetingsData(true);
  };

  deleteMeeting = meetingItem => {
    if (
      moment(meetingItem.creationDateTime).format('YYYY-MM-DD HH:mm') <= moment(new Date()).format('YYYY-MM-DD 18:00')
    ) {
      this.deleteConfirmMeeting(meetingItem.meetingId);
    } else {
      this.showWarning('Time has expired to remove Meeting', 'error');
    }
  };

  deleteConfirmMeeting = meetingId => {
    return this.props
      .deleteMeeting({ meetingId, token: this.props.loggedUserToken })
      .then(() => {
        this.fetchMeetingsData(true);
      })
      .catch(err => {
        this.showWarning(formResMessage(err), 'error');
      });
  };

  fetchPageData = page => {
    if (page && page !== this.state.pageParams.page) {
      this.setState(
        {
          ...this.state,
          pageParams: {
            ...this.state.pageParams,
            page,
          },
        },
        () => {
          this.fetchMeetingsData(true);
        }
      );
    }
  };

  render() {
    const { isModalOpen, meetingFetching } = this.state;
    const { courseId, meetingsData, subjects, meeting } = this.props;

    const getMeetingData = () => {
      return {
        ...meetingsData,
        content: meetingsData?.content?.length
          ? meetingsData?.content?.map(meetingItem => {
              const st = getSelecDateTime(meetingItem.meetupStartTime);
              const et = getSelecDateTime(meetingItem.meetupEndTime);
              let url = '';
              if (!meetingItem.meetupUrl.includes('http')) {
                url = `https://${meetingItem.meetupUrl}`;
              } else if (meetingItem.meetupUrl.includes('http') && !meetingItem.meetupUrl.includes('https')) {
                url = meetingItem.meetupUrl?.replace('http', 'https');
              } else {
                url = meetingItem.meetupUrl;
              }
              return {
                ...meetingItem,
                title: meetingItem.title,
                meetingUrl: url ? (
                  <a href={url} style={{ color: colors.aTag, fontWeight: 'bold' }} target="_blank" rel="noreferrer">
                    Join here
                  </a>
                ) : (
                  'No URL Found'
                ),
                meetupDate: moment(meetingItem.meetupDate).format('LL'),
                st: moment(st).format('hh:mm A'),
                et: moment(et).format('hh:mm A'),
                description: meetingItem.description,
                actionItem: (
                  <ListDropDown
                    actionList={['edit', 'delete']}
                    item={meetingItem}
                    fetchItem={() => this.getMeeting(meetingItem.meetingId)}
                    deleteItem={() => this.deleteMeeting(meetingItem)}
                  />
                ),
              };
            })
          : null,
      };
    };
    const tableData = (
      <MuiTable
        tableHeaders={meetingTableHead}
        tableBodyData={getMeetingData()}
        bodyColumns={['title', 'meetingUrl', 'meetupDate', 'st', 'et', 'description', 'actionItem']}
        dropDownActions={['edit', 'delete']}
        idName="meetingId"
        fetchItem={this.getMeeting}
        deleteItem={this.deleteMeeting}
        fetchPageData={this.fetchPageData}
        cellPadding={{ paddingTop: 8, paddingBottom: 8 }}
      />
    );
    return (
      <div className="content">
        {/* <span style={{ color: 'orange' }}>Note: Meeting conversation is only available in Mobile application</span> */}
        <Row>
          <Col sm={9} md={8} />
          <Col sm={3} md={4}>
            <CustomButton
              className="mt-0 mb-2"
              style={{ float: 'right' }}
              onClick={this.formModalOpen}
              disabled={!courseId}
              name="Create Online class"
            />
          </Col>
        </Row>
        {meetingFetching ? <LoadingCard /> : tableData}
        <MeetingFormModal
          isModalOpen={isModalOpen}
          courseId={courseId}
          formModalCloseProp={this.formModalClose}
          subjects={subjects}
          saveMeeting={this.saveMeeting}
          meeting={meeting}
          updateMeeting={this.updateMeeting}
          meetingUpdateSuccess={this.meetingUpdateSuccess}
        />
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    loggedUserRole: state.auth.loggedUserRole,
    subjects: state.subjects.subjectList,
    meetingsData: state.students.meetingsData,
    meeting: state.students.meeting,
    visitedCourseIds: state.auth.visitedCourseIds,
    activeTab: state.auth.activeTab,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    saveMeeting: data => dispatch(saveMeetingService(data)),
    fetchMeetingsData: data => dispatch(fetchAllMeetingsService(data)),
    fetchMeeting: data => dispatch(fetchMeetingService(data)),
    updateMeeting: data => dispatch(updateMeetingService(data)),
    deleteMeeting: data => dispatch(deleteMeetingService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(MeetingPage);
