import React from 'react';
import ReactDatePicker from 'react-datepicker';
import ChevronLeftIcon from '@material-ui/icons/ChevronLeft';
import ChevronRightIcon from '@material-ui/icons/ChevronRight';
import IconButton from '@material-ui/core/IconButton';
import Chip from '@material-ui/core/Chip';
import { makeStyles } from '@material-ui/core/styles';
import moment from 'moment';
import CommonTooltip from './CommonTooltip';
import colors from 'config/colors';

const useStyles = makeStyles({
  iconButton: {
    padding: 2,
    '&:hover': {
      backgroundColor: 'transparent',
    },
  },
  // The app-wide `.customDatePickerWidth` rule that's meant to stretch this input has a broken
  // selector (missing comma) that leaves the actual <input> unstyled, so it falls back to
  // shrinking to fit the flex row next to the prev/next arrows instead of showing the full
  // "dd/mm/yyyy" value - scoped here (fixed min-width, not a % that depends on ancestor sizing)
  // instead of touching that shared, widely-used global rule.
  datePickerWrapper: {
    '& input': {
      minWidth: 110,
    },
  },
});

const DatePicker = ({
  dateFormat,
  disabled,
  handleDateChange,
  selectedDate: passSelectedDate,
  minDate,
  maxDate,
  showOnlyMonthAndYear,
  showTimeSelect,
  showDateWithTime,
  minTime,
  maxTime,
  timeIntervals,
  className,
  // Only meaningful for "browse by date" filters (Attendance, Circular, etc.) - a DOB or due-date
  // field has no concept of "today" to call out, so this stays opt-in rather than global.
  highlightToday,
}) => {
  let format = dateFormat || 'dd/MM/yyyy';
  if (showOnlyMonthAndYear) format = 'MM/yyyy';
  if (showDateWithTime) format = 'dd/MM/yyyy  h:mm aa';

  const classes = useStyles();

  const selectedDate = passSelectedDate ? new Date(passSelectedDate) : null;
  const unit = showOnlyMonthAndYear ? 'month' : 'day';
  const isToday = highlightToday && !!selectedDate && moment(selectedDate).isSame(moment(), unit);

  const nextDate = selectedDate && moment(selectedDate).clone().add(1, unit);
  const prevDate = selectedDate && moment(selectedDate).clone().subtract(1, unit);
  const isPrevDisabled = !selectedDate || (minDate && prevDate.isBefore(moment(minDate), unit));
  const isNextDisabled = !selectedDate || (maxDate && nextDate.isAfter(moment(maxDate), unit));

  const isTodayInRange =
    (!minDate || !moment().isBefore(moment(minDate), unit)) && (!maxDate || !moment().isAfter(moment(maxDate), unit));
  const isTodayDisabled = disabled || isToday || !isTodayInRange;
  const goToToday = () => {
    if (!isTodayDisabled) {
      handleDateChange(new Date());
    }
  };

  // Previous = back in time = left/decrease, Next = forward in time = right/increase - matches
  // every calendar app's convention, unlike the up/down chevrons this replaced (which pointed
  // the wrong way: up read as "forward" but stepped the date backward, and vice versa).
  const handleNextPrevChange = action => {
    if (action === 'previous' && !isPrevDisabled) {
      handleDateChange(prevDate);
    } else if (action === 'next' && !isNextDisabled) {
      handleDateChange(nextDate);
    }
  };

  return (
    <div style={{ display: 'flex', alignItems: 'center', width: '100%' }}>
      <CommonTooltip content={showOnlyMonthAndYear ? 'Previous month' : 'Previous day'}>
        <span>
          <IconButton
            className={classes.iconButton}
            size="small"
            disabled={disabled || isPrevDisabled}
            onClick={() => handleNextPrevChange('previous')}>
            <ChevronLeftIcon fontSize="small" />
          </IconButton>
        </span>
      </CommonTooltip>
      <ReactDatePicker
        wrapperClassName={classes.datePickerWrapper}
        className={`form-control ${className}`}
        selected={selectedDate}
        onChange={value => {
          handleDateChange(value);
        }}
        minDate={minDate || null}
        maxDate={maxDate || null}
        dateFormat={format}
        placeholderText="Select date..."
        peekNextMonth
        showMonthDropdown
        showYearDropdown
        showMonthYearPicker={!!showOnlyMonthAndYear}
        dropdownMode="select"
        disabled={disabled}
        showTimeSelect={showTimeSelect}
        minTime={minTime || null}
        maxTime={maxTime || null}
        timeIntervals={timeIntervals}
      />
      {highlightToday && (
        <CommonTooltip content={isToday ? "You're viewing today" : 'Jump to today'}>
          <span>
            <Chip
              size="small"
              label="Today"
              clickable={!isTodayDisabled}
              onClick={goToToday}
              style={{
                marginLeft: 6,
                marginRight: 6,
                fontWeight: 'bold',
                fontSize: 11,
                height: 20,
                cursor: isTodayDisabled ? 'default' : 'pointer',
                backgroundColor: isToday ? colors.accent : `${colors.accent}1a`,
                color: isToday ? '#FFFFFF' : colors.accent,
                opacity: isTodayDisabled && !isToday ? 0.5 : 1,
              }}
            />
          </span>
        </CommonTooltip>
      )}
      <CommonTooltip content={showOnlyMonthAndYear ? 'Next month' : 'Next day'}>
        <span>
          <IconButton
            className={classes.iconButton}
            size="small"
            disabled={disabled || isNextDisabled}
            onClick={() => handleNextPrevChange('next')}>
            <ChevronRightIcon fontSize="small" />
          </IconButton>
        </span>
      </CommonTooltip>
    </div>
  );
};

export default DatePicker;
