import React from 'react';
import { Badge } from 'reactstrap';
import moment from 'moment';
import constants from '../../../../../config/constants';
import MuiTable from 'views/admin/Common/MuiTable';
import { ActiveSpan, DeactiveSpan } from 'views/admin/Common/StatusBadges';
import { formatLeaveDate, leaveDayCount, toLeaveDate } from 'utils/leaveDates';

export default class StudentsLeave extends React.Component {
  render() {
    const { disableAll, loggedUserRole, studentsLeaveData, approveLeave, cancelLeave, fetchPageData } = this.props;

    const studentsLeaveHead = ['Reg.No', 'Name', 'Start date', 'End date', 'Days', 'Reason', 'Action'];

    const getStudentsLeave = () => {
      return {
        ...studentsLeaveData,
        content: studentsLeaveData?.content?.map(el => {
          const isExpired =
            el.leaveStatus === 'PENDING' && toLeaveDate(el.startDate) < moment(new Date()).format('YYYY-MM-DD');
          return {
            ...el,
            registerNumber: el?.student?.registerNumber,
            studentName: `${el?.student?.firstName}${el?.student?.middleName ? ` ${el?.student?.middleName}` : ''} ${
              el?.student?.lastName
            }`,
            startDate: formatLeaveDate(el.startDate),
            endDate: formatLeaveDate(el.endDate),
            days: leaveDayCount(el.startDate, el.endDate),
            reason: el.reason,
            actionItem: (
              <>
                {isExpired ? (
                  <Badge color="warning" className="ml-1 text-dark">
                    Expired
                  </Badge>
                ) : !isExpired && el.leaveStatus === 'PENDING' && loggedUserRole !== constants.roles.guardian ? (
                  <>
                    <Badge
                      color="success"
                      onClick={() =>
                        approveLeave('adminORemployee', { leaveId: el?.leaveId, studentId: el?.student?.studentId })
                      }
                      style={{ color: '#ffffff', cursor: 'pointer', paddingBlock: 7, paddingInline: 10 }}>
                      APPROVE
                    </Badge>{' '}
                    <Badge
                      color="danger"
                      onClick={() =>
                        cancelLeave('adminORemployee', { leaveId: el?.leaveId, studentId: el?.student?.studentId })
                      }
                      style={{ cursor: 'pointer', paddingBlock: 7, paddingInline: 10 }}>
                      CANCEL
                    </Badge>
                  </>
                ) : null}
                {el.leaveStatus === 'APPROVED' ? (
                  <ActiveSpan status="Approved" />
                ) : el.leaveStatus === 'REJECTED' ? (
                  <DeactiveSpan status="Cancelled" />
                ) : null}
              </>
            ),
          };
        }),
      };
    };
    return (
      <MuiTable
        tableHeaders={studentsLeaveHead}
        tableBodyData={!disableAll ? getStudentsLeave() : { content: [] }}
        bodyColumns={['registerNumber', 'studentName', 'startDate', 'endDate', 'days', 'reason', 'actionItem']}
        fetchPageData={fetchPageData}
      />
    );
  }
}
