import React, { useState } from 'react';
import moment from 'moment';
import colors from 'config/colors';
import EmptyState from 'views/admin/Common/EmptyState';

const NEW_DAYS = 3;

// Home work and assignments as the same list the app shows (and the student page's cards follow): a month heading over its rows
// (and, for assignments, a day heading too), newest first; each row has a date tile, the title with NEW when recent, the subject
// (and period), a preview of the description - a click opens the whole text - the last date to submit for an assignment, who gave
// it, and the row's actions.
//   items: [{ id, title, subject, period, description, date, dueDate, priority, by, actions }]
//   groupBy: 'month' (home work) | 'day' (assignments, a day heading under each month)
const TaskList = ({ items, groupBy = 'month', emptyTitle, emptySubtitle }) => {
  const [openId, setOpenId] = useState(null);
  if (!items.length) {
    return <EmptyState icon="far fa-folder-open" title={emptyTitle} subtitle={emptySubtitle} />;
  }
  const sorted = [...items].sort((a, b) => moment(b.date).valueOf() - moment(a.date).valueOf());
  return (
    <div style={{ background: '#fff', borderRadius: 12, overflow: 'hidden', boxShadow: '0 1px 6px rgba(0,0,0,0.08)' }}>
      {sorted.map((item, index) => {
        const date = moment(item.date);
        const previous = index ? moment(sorted[index - 1].date) : null;
        const newMonth = !previous || !previous.isSame(date, 'month');
        const newDay = groupBy === 'day' && (!previous || !previous.isSame(date, 'day'));
        const isNew = moment().diff(date, 'days') < NEW_DAYS;
        const isOpen = openId === item.id;
        return (
          <React.Fragment key={item.id}>
            {newMonth && (
              <div
                style={{
                  background: '#FAF5FD',
                  color: colors.accentDark,
                  fontSize: 12,
                  fontWeight: 'bold',
                  letterSpacing: 0.6,
                  padding: '6px 16px',
                }}>
                {date.format('MMMM YYYY').toUpperCase()}
              </div>
            )}
            {newDay && (
              <div style={{ color: colors.grey2, fontSize: 12, fontWeight: 'bold', padding: '8px 16px 0' }}>
                {date.format('dddd, D MMMM')}
              </div>
            )}
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 14,
                padding: '12px 16px',
                borderTop: newMonth || newDay ? 'none' : `1px solid ${colors.grey5 || '#eef0f3'}`,
              }}>
              <div
                style={{
                  width: 52,
                  flexShrink: 0,
                  textAlign: 'center',
                  borderRadius: 10,
                  padding: '6px 0',
                  background: `${colors.accent}14`,
                  color: colors.accent,
                  fontWeight: 'bold',
                }}>
                <div style={{ fontSize: 20, lineHeight: '22px' }}>{date.format('DD')}</div>
                <div style={{ fontSize: 11 }}>{date.format('MMM').toUpperCase()}</div>
              </div>
              <div
                role="button"
                tabIndex={0}
                onClick={() => setOpenId(isOpen ? null : item.id)}
                onKeyDown={e => (e.key === 'Enter' || e.key === ' ') && setOpenId(isOpen ? null : item.id)}
                style={{ flex: 1, minWidth: 0, cursor: 'pointer' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                  <b style={{ fontSize: 15 }}>{item.title}</b>
                  {isNew && (
                    <span
                      style={{
                        background: colors.accent,
                        color: '#fff',
                        borderRadius: 8,
                        padding: '0 8px',
                        fontSize: 10,
                        fontWeight: 'bold',
                      }}>
                      NEW
                    </span>
                  )}
                  {!!item.priority && (
                    <span style={{ color: '#e08e00', fontSize: 11, fontWeight: 'bold' }}>{item.priority}</span>
                  )}
                </div>
                <div style={{ color: colors.accent, fontSize: 11, fontWeight: 'bold', marginTop: 2 }}>
                  {`${item.subject || ''}${item.period ? ` · ${item.period}` : ''}`.toUpperCase()}
                </div>
                <div
                  style={{
                    color: '#6b778a',
                    fontSize: 13,
                    marginTop: 2,
                    whiteSpace: isOpen ? 'pre-wrap' : 'nowrap',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    wordBreak: 'break-word',
                  }}>
                  {item.description}
                </div>
                <div style={{ display: 'flex', gap: 14, flexWrap: 'wrap', marginTop: 3, fontSize: 12 }}>
                  {!!item.dueDate && (
                    <span style={{ color: '#e08e00', fontWeight: 'bold' }}>
                      Last date to submit: {moment(item.dueDate).format('MMM D, YYYY')}
                    </span>
                  )}
                  {!!item.by && <span style={{ color: '#9a9a9a' }}>By {item.by}</span>}
                </div>
              </div>
              <div style={{ flexShrink: 0 }}>{item.actions}</div>
            </div>
          </React.Fragment>
        );
      })}
    </div>
  );
};

export default TaskList;
