import React from 'react';
import { connect } from 'react-redux';
import { fetchCourseStudentsLeaveService } from 'actions/admin/students';
import {
  applyEmpLeaveService,
  fetchEmployeeLeavesByAdminService,
  fetchEmployeeLeaveService,
  approveLeaveService,
  cancelLeaveService,
} from 'actions/admin/employees';
import ConfirmModal from 'views/admin/Common/ConfirmModal.jsx';
import StudentsLeave from './components/StudentsLeave';
// import EmployeeLeave from './components/EmployeeLeave';
import constants from '../../../../config/constants';
import { formResMessage, getGlobalSchoolUtils } from '../../../../utils/commonFunc';
import { store } from '../../../..';
import { showToast } from '../../../../actions/admin/auth';
import { passActiveTabAndCourseId } from '../EmployeeActivityPage';

class LeavesPage extends React.Component {
  state = {
    schoolId: 0,
    selectedStatusType: 'PENDING',
    action: '',
    confirmMessage: '',
    leaveId: 0,
    confirmModalOpen: false,
    studentsPageParams: {
      page: 1,
      size: 10,
    },
    studentId: 0,
    isUpdating: false,
  };

  fetchLeaves = (globalSchool, refetchAgain) => {
    this.setState(
      {
        schoolId: globalSchool.schoolId,
      },
      () => {
        this.fetchStudentsLeave(refetchAgain);
        // this.fetchEmployeeLeaves(refetchAgain);
      }
    );
  };

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    if (globalSchool) {
      const { visitedCourseIds, activeTab, courseId } = this.props;
      if (courseId && visitedCourseIds?.[activeTab] !== courseId) {
        this.fetchLeaves(globalSchool, true);
        passActiveTabAndCourseId(activeTab, courseId);
      } else {
        this.fetchLeaves(globalSchool);
      }
    }
  }

  componentDidUpdate(prevProps) {
    const { activeTab, courseId } = this.props;
    if (courseId && prevProps.courseId !== courseId) {
      courseId && passActiveTabAndCourseId(activeTab, courseId);
      this.fetchStudentsLeave(true);
    }
    // if (this.props.propEmployeeId && prevProps.propEmployeeId !== this.props.propEmployeeId) {
    //   this.fetchEmployeeLeaves(true);
    // }
  }

  showWarning = (message, type) => {
    this.setState({ confirmModalOpen: false });
    store.dispatch(showToast(message, type));
  };

  fetchEmployeeLeaves = refetchAgain => {
    const data = {
      schoolId: this.state.schoolId,
      token: this.props.loggedUserToken,
    };
    if (
      this.props.loggedUserRole === constants.roles.teacher &&
      (!this.props.employeeLeaveData?.content?.length || refetchAgain)
    ) {
      return this.props.fetchEmployeeLeaves({
        ...data,
        employeeId: this.props.loggedUserId,
        pageParams: this.state.studentsPageParams,
      });
    } else if (!this.props.employeeLeaveData?.content?.length || refetchAgain) {
      return this.props.fetchEmployeeLeavesByAdmin({
        ...data,
        employeeId: this.props.propEmployeeId,
        selectedStatusType: this.state.selectedStatusType,
        pageParams: this.state.studentsPageParams,
      });
    }
  };

  fetchStudentsLeave = refetchAgain => {
    if (this.props.courseId && (!this.props.studentsLeaveData?.content?.length || refetchAgain)) {
      return this.props.fetchStudentsLeave({
        courseId: this.props.courseId,
        token: this.props.loggedUserToken,
        pageParams: this.state.studentsPageParams,
      });
    }
  };

  leaveUpdateSuccess = () => {
    this.setState({ isModalOpen: false });
    this.showWarning('Updated Successfully', 'success');
    // this.fetchEmployeeLeaves(true);
  };

  applyEmpLeave = data => {
    const postData = {
      ...data,
      employee: {
        employeeId: this.props.loggedUserId,
      },
    };
    return this.props.applyEmpLeave({
      postData,
      token: this.props.loggedUserToken,
    });
  };

  handleStatusChange = sVal => {
    this.setState(
      {
        selectedStatusType: sVal.value ? sVal.value : 'PENDING',
      },
      () => {
        // this.fetchEmployeeLeaves(true)
      }
    );
  };

  approveLeave = (userRole, leaveIds) => {
    const { leaveId, studentId } = leaveIds;
    this.setState({
      action: 'approve',
      confirmMessage: 'Are you sure you want to approve ?',
      confirmModalOpen: true,
      leaveId,
      studentId,
    });
  };

  cancelLeave = (userRole, leaveIds) => {
    const { leaveId, studentId } = leaveIds;
    this.setState({
      action: 'cancel',
      confirmMessage: `Are you sure you want to cancel ?`,
      confirmModalOpen: true,
      leaveId,
      studentId,
    });
  };

  deleteCancel = () => {
    this.setState({
      action: '',
      confirmMessage: '',
      leaveId: 0,
      confirmModalOpen: false,
      isUpdating: false,
    });
  };

  deleteConfirm = () => {
    let employeeId = 0;
    if (this.props.loggedUserRole === constants.roles.teacher) {
      employeeId = this.props.loggedUserId;
    } else {
      employeeId = this.props.propEmployeeId;
    }
    if (this.state.action === 'approve') {
      this.setState(prevState => ({ ...prevState, isUpdating: true }));
      return this.props
        .approveLeave({
          leaveId: this.state.leaveId,
          studentId: this.state.studentId,
          token: this.props.loggedUserToken,
          employeeId,
        })
        .then(() => {
          this.deleteCancel();
          // this.fetchEmployeeLeaves(true);
          this.fetchStudentsLeave(true);
        })
        .catch(err => {
          this.deleteCancel();
          this.showWarning(formResMessage(err), 'error');
        });
    }
    if (this.state.action === 'cancel') {
      this.setState(prevState => ({ ...prevState, isUpdating: true }));
      return this.props
        .removeLeave({
          leaveId: this.state.leaveId,
          studentId: this.state.studentId,
          token: this.props.loggedUserToken,
          employeeId,
        })
        .then(() => {
          this.deleteCancel();
          // this.fetchEmployeeLeaves(true);
          this.fetchStudentsLeave(true);
        })
        .catch(err => {
          this.deleteCancel();
          this.showWarning(formResMessage(err), 'error');
        });
    }
  };

  fetchPageData = page => {
    this.setState(
      {
        studentsPageParams: {
          ...this.state.studentsPageParams,
          page,
        },
      },
      () => {
        // window.scrosllTo(0, this.topRef.current.offsetTop)
        // let wHeight = window.innerHeight;
        // window.scrollY = wHeight;
        if (this.props.subActive === 1) {
          this.fetchStudentsLeave(true);
        } else {
          // this.fetchEmployeeLeaves(true);
        }
      }
    );
  };

  render() {
    const { confirmModalOpen, confirmMessage, isUpdating } = this.state;
    const { disableAll, subActive, loggedUserRole, studentsLeaveData, isEmpOrCourseIdIsInvalid } = this.props;
    return (
      <>
        {subActive === 1 && (
          <StudentsLeave
            disableAll={disableAll}
            loggedUserRole={loggedUserRole}
            studentsLeaveData={studentsLeaveData}
            fetchPageData={this.fetchPageData}
            cancelLeave={this.cancelLeave}
            approveLeave={this.approveLeave}
            isEmpOrCourseIdIsInvalid={isEmpOrCourseIdIsInvalid}
          />
        )}
        {/* {subActive === 2 && (
          <EmployeeLeave
            propEmployeeId={propEmployeeId}
            disableAll={disableAll}
            loggedUserRole={this.props.loggedUserRole}
            employeeLeaveData={employeeLeaveData}
            applyLeave={this.applyEmpLeave}
            leaveUpdateSuccess={this.leaveUpdateSuccess}
            cancelLeave={this.cancelLeave}
            approveLeave={this.approveLeave}
            selectedStatusType={selectedStatusType}
            handleStatusChange={this.handleStatusChange}
            fetchPageData={this.fetchPageData}
            isEmpOrCourseIdIsInvalid={isEmpOrCourseIdIsInvalid}
          />
        )} */}
        <ConfirmModal
          confirmMessage={confirmMessage}
          confirmModalOpen={confirmModalOpen}
          deleteConfirm={this.deleteConfirm}
          deleteCancel={this.deleteCancel}
          loading={isUpdating}
        />
      </>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    loggedUserRole: state.auth.loggedUserRole,
    employeeLeaveData: state.employees.employeeLeaveList,
    studentsLeaveData: state.students.studentsLeaveData,
    visitedCourseIds: state.auth.visitedCourseIds,
    activeTab: state.auth.activeTab,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchStudentsLeave: data => dispatch(fetchCourseStudentsLeaveService(data)),
    fetchEmployeeLeaves: data => dispatch(fetchEmployeeLeaveService(data)),
    fetchEmployeeLeavesByAdmin: data => dispatch(fetchEmployeeLeavesByAdminService(data)),
    applyEmpLeave: data => dispatch(applyEmpLeaveService(data)),
    approveLeave: data => dispatch(approveLeaveService(data)),
    removeLeave: data => dispatch(cancelLeaveService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(LeavesPage);
