import React from 'react';
import { connect } from 'react-redux';
import { Row, Col } from 'reactstrap';
import moment from 'moment';

import {
  saveHomeWorkService,
  viewStudentHomeWorkStatusService,
  deleteHomeWorkService,
  fetchCourseDayTimeSlotService,
} from 'actions/admin/students';
import HomeWorkFormModal from './components/HomeWorkFormModal.jsx';
import StudentsStatusViewModal from './components/StudentsStatusViewModal.jsx';
import constants, { courseStatic } from '../../../../config/constants.js';
import {
  getGlobalCurrentBatchUtils,
  getCurrentYearBatchUtils,
  getGlobalSchoolUtils,
  formResMessage,
} from '../../../../utils/commonFunc.js';
import { store } from '../../../../index.js';
import { showToast } from '../../../../actions/admin/auth.js';
import { fetchCurrentBatchByYearService } from '../../../../actions/admin/batches.js';
import CustomButton from '../../../../components/CustomButton.jsx';
import SubTabs from '../SubTabs.jsx';
import AssignmentPage from '../Assignment/AssignmentPage.jsx';
import { fetchCourseSubjectsService } from '../../../../actions/admin/subjects.js';
import TaskList from '../components/TaskList';
import LoadMore from '../components/LoadMore';
import ListDropDown from 'views/admin/Common/ListDropDown.jsx';
import { LoadingCard } from 'views/admin/Common/Loader.jsx';

const subTabList = [
  { tabName: 'Home work', index: 0 },
  { tabName: 'Assignment', index: 1 },
];
class HomeWorkPage extends React.Component {
  constructor() {
    super();
    this.state = {
      selectedDate: new Date(),
      isModalOpen: false,
      isStatusModalOpen: false,
      subActive: 0,
      subTimes: [],
    };
  }

  componentDidMount() {
    this.fetchCourseDayTimeSlot();
    this.fetchCourseSubjects();
    const { batchId } = getGlobalCurrentBatchUtils();
    if (!batchId) {
      this.fetchCurrentBatch();
    }
  }

  fetchCurrentBatch = () => {
    const { startYear, endYear } = getCurrentYearBatchUtils();
    const globalSchool = getGlobalSchoolUtils();
    const { batchId } = getGlobalCurrentBatchUtils();
    if (!batchId && globalSchool?.schoolId) {
      store.dispatch(
        fetchCurrentBatchByYearService({
          token: this.props.loggedUserToken,
          schoolId: globalSchool.schoolId,
          startYear,
          endYear,
        })
      );
    }
  };

  componentDidUpdate(prevProps) {
    if (prevProps.propsCourseId !== this.props.propsCourseId) {
      this.fetchCourseSubjects(true);
      this.fetchCourseDayTimeSlot();
    }
    // empSubjectList is fetched by the parent (EmployeeActivityPage), independently of and
    // often slightly after this component's own courseSubjects/courseDayTimeSlot fetches -
    // on first load it can still be empty by the time those resolve and compute subTimes,
    // leaving the subject dropdown stuck empty until something else happens to call
    // updateTimeSheetSubjects again (e.g. switching sub-tabs). React to it arriving here
    // instead of relying on that coincidence.
    if (prevProps.empSubjectList !== this.props.empSubjectList) {
      this.updateTimeSheetSubjects();
    }
  }

  // List every subject the teacher is assigned to *for the currently selected class*, not
  // just the ones with a slot on today's timetable - a teacher whose subject has no
  // period today (free period, non-teaching day, timetable not loaded yet) still needs to
  // be able to log homework for it. Today's slot (if any) is attached for the auto-filled
  // period time; when there isn't one, HomeWorkFormModal falls back to letting the
  // admin/teacher enter the period time manually. Scoping to propsCourseId matters: a
  // teacher can be assigned subjects across several classes, but courseSubjects (used to
  // resolve the subjectId on submit) is only ever loaded for the one class picked above,
  // so offering subjects from other classes here would let the picker show a subject that
  // then fails to resolve.
  getTimeSheetSubjects = () => {
    const { courseDayTimeSlots, empSubjectList, propsCourseId } = this.props;
    if (empSubjectList?.length) {
      return empSubjectList
        .filter(
          sto =>
            sto?.subject?.studyLevel !== 'NONE' &&
            sto?.subject?.subjectCode !== 'BREAK' &&
            sto?.subject?.course?.courseId === propsCourseId
        )
        .map(sto => {
          const todaySlot = courseDayTimeSlots?.find(dto => dto?.subjectCode === sto?.subject?.subjectCode);
          return {
            label: todaySlot ? `${sto.subject.name} - ${todaySlot.timePeriod}` : sto.subject.name,
            value: sto.subject.subjectCode,
            timePeriod: todaySlot?.timePeriod,
          };
        });
    }
    return [];
  };

  updateTimeSheetSubjects = () => {
    const subTimes = this.getTimeSheetSubjects();
    this.setState(prevState => ({
      ...prevState,
      subTimes: subTimes?.length ? subTimes : [],
    }));
  };

  fetchCourseSubjects = async refetchAgain => {
    if (this.props.propsCourseId && (!this.props.courseSubjects?.length || refetchAgain)) {
      await this.props.fetchCourseSubjects({
        courseId: this.props.propsCourseId,
        token: this.props.loggedUserToken,
      });
    }
    this.updateTimeSheetSubjects();
  };

  showWarning = (message, type) => {
    this.setState({ confirmModalOpen: false });
    store.dispatch(showToast(message, type));
  };

  fetchCourseDayTimeSlot = async () => {
    const { propsCourseId, propsSchoolId, courseDayTimeSlots } = this.props;
    const { batchId } = getGlobalCurrentBatchUtils();
    if (batchId && propsCourseId && propsSchoolId && !courseDayTimeSlots?.length) {
      await this.props.fetchCourseDayTimeSlot({
        courseId: propsCourseId,
        schoolId: propsSchoolId,
        batchId,
        dayStr:
          moment(this.state.selectedDate).format('ddd').toUpperCase() === 'SUN'
            ? moment().add(1, 'day').format('ddd').toUpperCase()
            : moment().format('ddd').toUpperCase(),
        token: this.props.loggedUserToken,
      });
      this.updateTimeSheetSubjects();
    }
    // else {
    //   this.showWarning("Current batch is not valid, Please check in batches module", "warning")
    // }
  };

  // HomeWork section ///

  formModalOpen = () => {
    // if(moment(this.state.selectedDate).format('YYYY-MM-DD') <= moment(new Date()).format('YYYY-MM-DD')){
    //   alert('Cant')
    // } else {
    this.setState({ isModalOpen: true });
    // }
  };

  formModalClose = () => {
    this.setState({
      isModalOpen: false,
      confirmModalOpen: false,
      isStatusModalOpen: false,
    });
  };

  saveHomeWork = data => {
    const homeWorkData = {
      createdUser: {
        id: this.props.loggedUserRole === constants.roles.teacher ? this.props.loggedUserId : this.props.propEmployeeId,
      },
      employee: { employeeId: this.props.propEmployeeId },
      subject: { subjectId: data.subjectId },
      name: data.name,
      description: data.description,
      timePeriod: data.timePeriod || '',
    };
    return this.props.saveHomeWork({ homeWorkData, token: this.props.loggedUserToken });
  };

  viewStudentStatus = taskId => {
    return this.props.viewStudentHomeWorkStatus({ taskId, token: this.props.loggedUserToken }).then(() =>
      this.setState({
        isModalOpen: false,
        confirmModalOpen: false,
        isStatusModalOpen: true,
      })
    );
  };

  homeWorkUpdateSuccess = () => {
    this.setState({ isModalOpen: false });
    this.showWarning('HomeWork added successfully', 'success');
    this.props.fetchHomeWorksData(this.state.selectedDate, false, true);
  };

  deleteHomeWork = homeWorkItem => {
    if (
      moment(homeWorkItem.creationDateTime).format('YYYY-MM-DD') === moment(new Date()).format('YYYY-MM-DD') &&
      moment(homeWorkItem.creationDateTime).format('YYYY-MM-DD HH:mm') <= moment(new Date()).format('YYYY-MM-DD 18:00')
    ) {
      this.deleteConfirmHomeWork(homeWorkItem.taskId);
    } else {
      this.showWarning('Time has expired to remove Home work', 'warning');
    }
  };

  deleteConfirmHomeWork = taskId => {
    return this.props
      .deleteHomeWork({ taskId, token: this.props.loggedUserToken })
      .then(() => {
        this.props.fetchHomeWorksData(this.state.selectedDate, false, true);
      })
      .catch(err => {
        this.showWarning(formResMessage(err), 'error');
      });
  };

  handleSubTabChange = tab => {
    if (tab !== this.state.subActive) {
      this.setState(prevState => ({ ...prevState, subActive: tab }));
      if (tab === 0) {
        this.props.fetchHomeWorksData(this.state.selectedDate, false);
      }
      this.fetchCourseSubjects();
    }
  };

  refreshData = () => {
    if (this.state.subActive === 0) {
      this.props.fetchHomeWorksData(this.state.selectedDate, false, true);
    } else {
      this.props.fetchAssignmentsData(this.state.selectedDate, false, 1, true);
    }
  };

  render() {
    const { subActive, isModalOpen, isStatusModalOpen, subTimes } = this.state;
    const {
      propsCourseId,
      homeWorkList,
      employee,
      courseSubjects,
      studentsHomeWorkStatusList,
      courseDayTimeSlots,
      // Assignment
      propEmployeeId,
      // propsCourseId,
      courseStudents,
      fetchAssignmentsData,
      assignmentPageParams,
      homeworkFetching,
      assignmentFetching,
    } = this.props;

    const getTaskList = () => {
      // Newest first, like the mobile list.
      return [...homeWorkList]
        .filter(fData => fData.subject.course.courseId === propsCourseId)
        .sort((a, b) => moment(b.creationDateTime).valueOf() - moment(a.creationDateTime).valueOf())
        .map(homeWorkItem => {
          return {
            ...homeWorkItem,
            subNameAndCourse: `${homeWorkItem.subject.name} (${homeWorkItem.subject?.course?.name || ''})`,
            name: homeWorkItem.name,
            description: homeWorkItem.description,
            // Older tasks stored a "start/end" pair here and still display as a range;
            // newer ones store just a period label (or nothing, if the subject had no slot
            // on the day it was logged) - homeWorkItem.timePeriod can be missing entirely,
            // since the backend drops empty strings from the response.
            timePeriod: homeWorkItem.timePeriod ? homeWorkItem.timePeriod.replace('/', ' - ') : '',
            actionItem: (
              <ListDropDown
                actionList={['students status', 'delete']}
                item={homeWorkItem}
                viewStudentStatus={() => this.viewStudentStatus(homeWorkItem.taskId)}
                deleteItem={() => this.deleteHomeWork(homeWorkItem)}
              />
            ),
          };
        });
    };

    const taskItems = (homeWorkList?.length ? getTaskList() : []).map(item => ({
      id: item.taskId,
      title: item.name,
      subject: item.subject?.name,
      period: item.timePeriod,
      description: item.description,
      date: item.creationDateTime,
      by: item.createdUser?.name,
      actions: item.actionItem,
    }));

    const homeWorkComp = (
      <>
        <Row className="mt-2 mb-3">
          <Col>
            <CustomButton
              style={{ float: 'right' }}
              onClick={this.formModalOpen}
              disabled={!propsCourseId}
              name="Add Homework"
            />
            {!propsCourseId && (
              <span style={{ color: 'orange' }}>
                <sup>*</sup>Select {courseStatic} to enable
              </span>
            )}
          </Col>
        </Row>
        {homeworkFetching && !taskItems.length ? (
          <LoadingCard />
        ) : (
          <>
            <TaskList
              groupBy="month"
              emptyTitle="Nothing to show here yet"
              emptySubtitle={
                propsCourseId
                  ? 'Home work you give shows here, newest first.'
                  : `Select a ${courseStatic.toLowerCase()} first.`
              }
              items={taskItems}
            />
            <LoadMore
              visible={taskItems.length >= this.props.homeworkLimit}
              loading={homeworkFetching}
              onClick={this.props.onLoadMoreHomeWork}
            />
          </>
        )}
      </>
    );

    return (
      <div className="content">
        <SubTabs
          className="mb-3"
          subTabs={subTabList}
          subActive={subActive}
          tabToggle={tab => this.handleSubTabChange(tab)}
          showRefresh={true}
          refreshData={this.refreshData}
        />
        {subActive === 0 && homeWorkComp}
        {subActive === 1 && (
          <AssignmentPage
            assignmentFetching={assignmentFetching}
            subActive={subActive}
            propEmployeeId={propEmployeeId}
            propsCourseId={propsCourseId}
            courseStudents={courseStudents}
            fetchAssignmentsData={fetchAssignmentsData}
            assignmentPageParams={assignmentPageParams}
            courseSubjects={courseSubjects}
          />
        )}
        <HomeWorkFormModal
          isModalOpen={isModalOpen}
          propsCourseId={propsCourseId}
          employee={employee}
          courseSubjects={courseSubjects}
          courseDayTimeSlots={courseDayTimeSlots}
          formModalCloseProp={this.formModalClose}
          saveHomeWork={this.saveHomeWork}
          homeWorkUpdateSuccess={this.homeWorkUpdateSuccess}
          fetchCourseSubjects={this.fetchCourseSubjects}
          fetchCourseDayTimeSlot={this.fetchCourseDayTimeSlot}
          subTimes={subTimes}
        />
        <StudentsStatusViewModal
          isStatusModalOpen={isStatusModalOpen}
          studentsHomeWorkStatusList={studentsHomeWorkStatusList}
          formModalClose={this.formModalClose}
        />
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    loggedUserRole: state.auth.loggedUserRole,
    courseSubjects: state.subjects.courseSubjects,
    homeWorkList: state.students.homeWorkList,
    studentsHomeWorkStatusList: state.students.studentsHomeWorkStatusList,
    // Time slots
    courseDayTimeSlots: state.students.courseDayTimeSlots,
    empSubjectList: state.subjects?.empSubjectList,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchCourseDayTimeSlot: data => dispatch(fetchCourseDayTimeSlotService(data)),
    fetchCourseSubjects: data => dispatch(fetchCourseSubjectsService(data)),
    saveHomeWork: data => dispatch(saveHomeWorkService(data)),
    viewStudentHomeWorkStatus: data => dispatch(viewStudentHomeWorkStatusService(data)),
    deleteHomeWork: data => dispatch(deleteHomeWorkService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(HomeWorkPage);
