import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Table, Input } from 'reactstrap';
import moment from 'moment';
import CustomSelect from 'components/CustomSelect';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';
import { formStudentName } from 'config/constants';
import { fetchSubjectProgressReportApi } from 'actions/admin/marks';
import { LoadingCard } from 'views/admin/Common/Loader';
import EmptyState from 'views/admin/Common/EmptyState';

// The whole class's marks for one exam on one sheet: a row per student, a column per subject, every mark editable. It is the
// class-wide way to enter or correct marks (the "Student marks" tab does it one student at a time, and each subject can also be
// entered for the whole class from "Class exams"). Changed marks are highlighted and saved together; a subject whose exam has not
// been held yet stays locked, the same as in the other tabs.
const MarksSheet = ({
  courseStudents = [],
  examTypeList = [],
  subjectExamData = {},
  courseId,
  onLoadExam,
  batchId,
  token,
  saveMark,
  showWarning,
}) => {
  const exams = useMemo(
    () => [...examTypeList].sort((a, b) => new Date(a.startDate) - new Date(b.startDate)),
    [examTypeList]
  );
  const [examTypeDetailId, setExamTypeDetailId] = useState(exams[0]?.examTypeDetailId || 0);
  const exam = exams.find(item => item.examTypeDetailId === examTypeDetailId);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  // { [studentId]: { [subjectId]: { progReportId, studentMark } } } and the cells changed since they were loaded
  const [marks, setMarks] = useState({});
  const [dirty, setDirty] = useState({});

  useEffect(() => {
    if (!examTypeDetailId && exams.length) setExamTypeDetailId(exams[0].examTypeDetailId);
  }, [exams, examTypeDetailId]);

  // the subjects held in this exam for this class, in exam order
  const subjectExams = useMemo(
    () =>
      [...(exam ? subjectExamData[exam.examType] || [] : [])]
        // the exam lists every class's subjects; this sheet is for the chosen class
        .filter(
          item =>
            !(item.course || item.subject?.course) ||
            Number((item.course || item.subject.course).courseId) === Number(courseId)
        )
        .sort((a, b) => new Date(a.examDate) - new Date(b.examDate)),
    [exam, subjectExamData, courseId]
  );
  const subjectKey = subjectExams.map(item => item.subject?.subjectId).join(',');

  useEffect(() => {
    if (exam) onLoadExam?.(exam.examType);
  }, [examTypeDetailId]);

  const load = useCallback(() => {
    if (!exam || !batchId || !subjectExams.length) {
      setMarks({});
      setDirty({});
      return undefined;
    }
    let cancelled = false;
    setLoading(true);
    Promise.all(
      subjectExams.map(item =>
        fetchSubjectProgressReportApi({
          batchId,
          examTypeDetailId: exam.examTypeDetailId,
          subjectId: item.subject.subjectId,
          token,
        })
          .then(res => ({ subjectId: item.subject.subjectId, rows: res.data || [] }))
          .catch(() => ({ subjectId: item.subject.subjectId, rows: [], failed: true }))
      )
    ).then(results => {
      if (cancelled) return;
      const next = {};
      results.forEach(({ subjectId, rows }) => {
        rows.forEach(row => {
          const studentId = row?.student?.studentId;
          if (studentId) {
            next[studentId] = {
              ...next[studentId],
              [subjectId]: { progReportId: row.progReportId, studentMark: row.studentMark },
            };
          }
        });
      });
      setMarks(next);
      setDirty({});
      setLoading(false);
      if (results.some(item => item.failed)) showWarning('Could not load the marks of some subjects', 'warning');
    });
    return () => {
      cancelled = true;
    };
  }, [exam, batchId, subjectKey, token]);

  useEffect(() => load(), [load]);

  const total = subjectExams.length ? Number(exam?.subjectTotalMark) || 0 : 0;
  const today = moment().format('YYYY-MM-DD');
  const held = item => moment(item.examDate).format('YYYY-MM-DD') <= today;

  const change = (studentId, subjectId, value) => {
    if (value !== '' && (Number(value) < 0 || (total && Number(value) > total))) {
      showWarning(`Mark must be between 0 and ${total}`, 'warning');
      return;
    }
    setMarks(prev => ({
      ...prev,
      [studentId]: { ...prev[studentId], [subjectId]: { ...prev[studentId]?.[subjectId], studentMark: value } },
    }));
    setDirty(prev => ({ ...prev, [`${studentId}:${subjectId}`]: true }));
  };

  const dirtyCells = Object.keys(dirty).filter(key => {
    const [studentId, subjectId] = key.split(':');
    const value = marks[studentId]?.[subjectId]?.studentMark;
    return value !== '' && value !== undefined && value !== null;
  });

  const save = async () => {
    setSaving(true);
    // a cell that already has a progReportId exists on the server, so it goes out as an update (PUT), not a second entry
    const results = await Promise.allSettled(
      dirtyCells.map(key => {
        const [studentId, subjectId] = key.split(':');
        const cell = marks[studentId][subjectId];
        return saveMark({
          postData: {
            examTypeDetails: { examTypeDetailId },
            subject: { subjectId: Number(subjectId) },
            studentMark: cell.studentMark,
            student: { studentId: Number(studentId) },
            batchId,
          },
          ...(cell.progReportId && { progReportId: cell.progReportId }),
          token,
        });
      })
    );
    setSaving(false);
    const failed = results.filter(item => item.status === 'rejected').length;
    showWarning(
      failed
        ? `Saved ${dirtyCells.length - failed} of ${dirtyCells.length} marks - ${failed} failed`
        : `Saved ${dirtyCells.length} mark${dirtyCells.length > 1 ? 's' : ''}`,
      failed ? 'warning' : 'success'
    );
    load();
  };

  if (!exams.length) {
    return <EmptyState compact bare icon="far fa-folder-open" title="No exams yet" />;
  }

  return (
    <div style={{ background: '#fff', borderRadius: 10, padding: 16, boxShadow: '0 1px 6px rgba(0,0,0,0.08)' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'flex-end', gap: 12, marginBottom: 12 }}>
        <div style={{ minWidth: 240 }}>
          <b style={{ fontSize: 13, display: 'block', marginBottom: 6 }}>Exam</b>
          <CustomSelect
            noLabel
            name="sheetExam"
            value={examTypeDetailId}
            options={exams.map(item => ({ value: item.examTypeDetailId, label: item.examTitle }))}
            onChange={(name, value) => value && setExamTypeDetailId(value)}
            applyLabelStyle
          />
        </div>
        <div style={{ flex: 1, minWidth: 220, fontSize: 12, color: '#6b778a' }}>
          Every student and subject of the exam on one sheet. Edit any mark (out of {total || '-'}), then save: only the
          changed marks are sent. Subjects marked &ldquo;Opens ...&rdquo; can be filled from their exam day.
        </div>
        <CustomButton
          name={dirtyCells.length ? `Save ${dirtyCells.length} change${dirtyCells.length > 1 ? 's' : ''}` : 'Save'}
          disabled={saving || loading || !dirtyCells.length}
          loading={saving}
          onClick={save}
        />
      </div>
      {loading ? (
        <LoadingCard />
      ) : !subjectExams.length ? (
        <EmptyState
          compact
          bare
          icon="far fa-folder-open"
          title="No subject exams yet"
          subtitle="Add the subject exams in Class exams first."
        />
      ) : (
        <div style={{ overflowX: 'auto' }}>
          <Table size="sm" style={{ minWidth: 520 }}>
            <thead>
              <tr>
                <th>Reg. No</th>
                <th>Student</th>
                {subjectExams.map(item => (
                  <th key={item.examSubjectDetailId} className="text-center" style={{ minWidth: 96 }}>
                    <div>{item.subject?.name}</div>
                    <small className="text-muted">
                      {moment(item.examDate).format('DD MMM')} · /{total || '-'}
                    </small>
                    {!held(item) && (
                      <div
                        style={{
                          display: 'inline-block',
                          marginTop: 4,
                          padding: '1px 8px',
                          borderRadius: 10,
                          background: '#FFF3E0',
                          color: '#e65100',
                          fontSize: 10,
                          fontWeight: 'bold',
                        }}>
                        <i className="fas fa-lock mr-1" />
                        Opens {moment(item.examDate).format('DD MMM')}
                      </div>
                    )}
                  </th>
                ))}
                <th className="text-center">Total</th>
              </tr>
            </thead>
            <tbody>
              {courseStudents.length ? (
                courseStudents.map(student => {
                  const row = marks[student.studentId] || {};
                  const sum = subjectExams.reduce((acc, item) => {
                    const value = row[item.subject.subjectId]?.studentMark;
                    return value === '' || value === undefined || value === null ? acc : acc + Number(value);
                  }, 0);
                  return (
                    <tr key={student.studentId}>
                      <td>{student.registerNumber}</td>
                      <td>{formStudentName(student)}</td>
                      {subjectExams.map(item => {
                        const subjectId = item.subject.subjectId;
                        const isDirty = dirty[`${student.studentId}:${subjectId}`];
                        return (
                          <td key={item.examSubjectDetailId} className="text-center">
                            {held(item) ? (
                              <Input
                                type="number"
                                bsSize="sm"
                                min={0}
                                max={total || undefined}
                                value={row[subjectId]?.studentMark ?? ''}
                                onChange={e => change(student.studentId, subjectId, e.target.value)}
                                style={{
                                  width: 78,
                                  margin: '0 auto',
                                  background: isDirty ? '#FFF8E1' : undefined,
                                  borderColor: isDirty ? colors.accent : undefined,
                                }}
                              />
                            ) : (
                              <span style={{ color: '#c1c7cf' }}>-</span>
                            )}
                          </td>
                        );
                      })}
                      <td className="text-center">
                        <b>{sum}</b>
                        {!!total && <small className="text-muted"> / {total * subjectExams.length}</small>}
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan={subjectExams.length + 3} className="text-center">
                    No students in this class
                  </td>
                </tr>
              )}
            </tbody>
          </Table>
        </div>
      )}
    </div>
  );
};

export default MarksSheet;
